export const UNIT3_SEGMENT_B_ITEMS = [
  {"id": "3.5-basic-01", "course": "csa", "topic": "3.5", "tier": "basic", "lo": "3.5.A.1", "prompt": "A method named displayMenu prints a list of options to the screen but does not send any value back to the code that called it.\nWhich method header is correctly written for displayMenu?", "choices": ["public void displayMenu()", "public String displayMenu()", "public int displayMenu()", "void public displayMenu()"], "answer": 0, "explanation": "A method that returns nothing uses void before its name (3.5.A.1). String and int would require a return statement providing a matching value, and reversing void and public in the last choice produces an invalid header."},
  {"id": "3.5-basic-02", "course": "csa", "topic": "3.5", "tier": "basic", "lo": "3.5.A.2", "prompt": "A method named totalScore is supposed to calculate and send back a student's total score as a whole number to the class that called it.\nWhich method header correctly reflects this?", "choices": ["public void totalScore()", "public int totalScore()", "public totalScore()", "private void totalScore()"], "answer": 1, "explanation": "A non-void method's header lists the return type, int, in place of void (3.5.A.2). The first and last choices declare void, meaning no value is returned, and the third choice omits a return type entirely, which does not compile."},
  {"id": "3.5-basic-03", "course": "csa", "topic": "3.5", "tier": "basic", "lo": "3.5.A.3", "prompt": "Consider the method.\npublic double getHalf(double num)\n{\n    return num / 2.0;\n}\nWhat value does the call getHalf(9.0) cause to be returned to the caller?", "choices": ["9.0", "2.0", "4.5", "0.5"], "answer": 2, "explanation": "The return expression num / 2.0 is evaluated with num equal to 9.0, giving 4.5, which is returned to the caller by value (3.5.A.3). The other values do not match this calculation."},
  {"id": "3.5-basic-04", "course": "csa", "topic": "3.5", "tier": "basic", "lo": "3.5.A.4", "prompt": "Consider the method.\npublic int classify(int num)\n{\n    if (num < 0)\n    {\n        return -1;\n    }\n    return 1;\n}\nWhen classify(-5) is called, what happens after the return -1; statement executes?", "choices": ["The method continues and evaluates the if condition again", "The method continues and executes return 1;, replacing the earlier returned value", "The program throws an error because a method cannot contain two return statements", "Control returns immediately to the point where classify was called, and no further statements in the method run"], "answer": 3, "explanation": "A return statement immediately halts the current method and passes control back to the caller, so return 1; never executes for classify(-5) (3.5.A.4). Methods may contain multiple return statements as long as only one executes per call, and there is no error or repeated condition check."},
  {"id": "3.5-basic-05", "course": "csa", "topic": "3.5", "tier": "basic", "lo": "3.5.A.5", "prompt": "A class Wallet stores a private instance variable named balance. Which method below is an example of an accessor method?", "choices": ["public double getBalance()\n{\n    return balance;\n}", "public void setBalance(double newBalance)\n{\n    balance = newBalance;\n}", "public void deposit(double amount)\n{\n    balance += amount;\n}", "public void withdraw(double amount)\n{\n    balance -= amount;\n}"], "answer": 0, "explanation": "An accessor is a non-void method that lets other classes obtain a copy of an instance variable's value, exactly what getBalance() does (3.5.A.5). The other three methods are void and change balance rather than returning it, making them mutators instead."},
  {"id": "3.5-basic-06", "course": "csa", "topic": "3.5", "tier": "basic", "lo": "3.5.A.6", "prompt": "A class Thermostat stores a private instance variable named temperature. Which method below is an example of a mutator method?", "choices": ["public double getTemperature()\n{\n    return temperature;\n}", "public void setTemperature(double newTemp)\n{\n    temperature = newTemp;\n}", "public double doubleTemperature()\n{\n    return temperature * 2;\n}", "public boolean isFreezing()\n{\n    return temperature <= 32;\n}"], "answer": 1, "explanation": "A mutator changes an instance variable's value, and setTemperature does exactly that in a void method (3.5.A.6). The other three methods are non-void and simply return information without changing temperature, making them accessors instead."},
  {"id": "3.5-basic-07", "course": "csa", "topic": "3.5", "tier": "basic", "lo": "3.5.A.7", "prompt": "Consider the method header.\npublic double convertMinutesToHours(double minutes)\nHow does the method use the value passed in for minutes?", "choices": ["It ignores the value and always uses a fixed number of minutes", "It changes the value of minutes in the class that called the method", "It receives the value through the parameter minutes and uses it inside the method body to accomplish its task", "It creates a brand-new instance variable named minutes in the class"], "answer": 2, "explanation": "Parameters receive values passed by the caller, and the method body uses that value, here minutes, to carry out its task (3.5.A.7). The method does not affect the caller's variable, ignore its input, or create an instance variable."},
  {"id": "3.5-basic-08", "course": "csa", "topic": "3.5", "tier": "basic", "lo": "3.5.A.8", "prompt": "Consider the method.\npublic void doubleValue(int num)\n{\n    num = num * 2;\n}\nIn another method, the following code executes.\nint score = 10;\ndoubleValue(score);\nSystem.out.println(score);\nWhat is printed?", "choices": ["0", "10 is printed, then overwritten with 20", "An error occurs because score cannot be passed to doubleValue", "10"], "answer": 3, "explanation": "Because num is a primitive int, the parameter is initialized with a copy of score's value, so changing num inside doubleValue has no effect on score in the caller (3.5.A.8). The output is therefore 10, not 20, and there is no error or overwriting of the original variable."},
  {"id": "3.5-basic-09", "course": "csa", "topic": "3.5", "tier": "basic", "lo": "3.5.A.1", "prompt": "Which of the following method headers correctly declares a void method named logEvent that accepts a String message and returns no value?", "choices": ["public void logEvent(String message)", "public String logEvent(String message)", "public void logEvent(): String message", "public logEvent(void, String message)"], "answer": 0, "explanation": "void before the method name means the method returns no value, and the parameter list correctly declares a single String parameter (3.5.A.1). The other choices either give a return type that requires a return statement or place void and the parameter list incorrectly."},
  {"id": "3.5-basic-10", "course": "csa", "topic": "3.5", "tier": "basic", "lo": "3.5.A.2", "prompt": "A method named isEligible is supposed to determine and send back whether a customer qualifies for a discount. Which method header is most appropriate?", "choices": ["public void isEligible()", "public boolean isEligible()", "public isEligible()", "public String isEligible(void)"], "answer": 1, "explanation": "Since the method reports a true/false result back to the caller, boolean is the appropriate return type in place of void (3.5.A.2). The first choice declares no return value at all, the third omits a return type, and the fourth uses an invalid parameter list."},
  {"id": "3.5-basic-11", "course": "csa", "topic": "3.5", "tier": "basic", "lo": "3.5.A.3", "prompt": "Consider the method.\npublic int squareValue(int num)\n{\n    return num * num;\n}\nWhat value is returned by the call squareValue(6)?", "choices": ["6", "12", "36", "0"], "answer": 2, "explanation": "The expression num * num is evaluated with num equal to 6, producing 36, which is returned by value to the caller (3.5.A.3). None of the other values match this calculation."},
  {"id": "3.5-basic-12", "course": "csa", "topic": "3.5", "tier": "basic", "lo": "3.5.A.4", "prompt": "Consider the method.\npublic String checkAge(int age)\n{\n    if (age >= 18)\n    {\n        return \"adult\";\n    }\n    return \"minor\";\n}\nWhy does this method never return both \"adult\" and \"minor\" from a single call?", "choices": ["Because Java only allows methods to have one return statement in their entire body", "Because the if statement deletes the second return statement from memory before it runs", "Because the compiler chooses the first return statement to run and disables the rest permanently", "Because executing a return statement immediately exits the method, so at most one return statement can execute per call"], "answer": 3, "explanation": "A return statement halts execution and hands control back to the caller immediately, so once one runs, no other statement in the method, including a later return, executes for that call (3.5.A.4). Java allows multiple return statements in a method as long as at most one executes per call; there is no deletion or permanent disabling involved."},
  {"id": "3.5-basic-13", "course": "csa", "topic": "3.5", "tier": "basic", "lo": "3.5.A.5", "prompt": "A class Employee has a private instance variable salary. Which method signature best fits the description of an accessor for salary?", "choices": ["public double getSalary()", "public void getSalary()", "public void setSalary(double amount)", "private double getSalary()"], "answer": 0, "explanation": "An accessor is a public, non-void method that returns a copy of an instance variable's value, matching public double getSalary() (3.5.A.5). A void return type cannot send back a value, setSalary is a mutator rather than an accessor, and a private method could not be called from other classes."},
  {"id": "3.5-basic-14", "course": "csa", "topic": "3.5", "tier": "basic", "lo": "3.5.A.6", "prompt": "A class Vehicle has a private instance variable fuelLevel. Which method signature best fits the description of a mutator that refuels the vehicle?", "choices": ["public double getFuelLevel()", "public void refuel(double amount)", "public double refuel(double amount)", "private void refuel(double amount)"], "answer": 1, "explanation": "A mutator is typically a void method that changes an instance variable's value, matching public void refuel(double amount) (3.5.A.6). getFuelLevel only reports a value rather than changing one, a non-void refuel would need a return statement it does not use for its purpose, and declaring it private would prevent other classes from calling it."},
  {"id": "3.5-basic-15", "course": "csa", "topic": "3.5", "tier": "basic", "lo": "3.5.A.7", "prompt": "A method header is written as follows.\npublic double calculateTip(double billTotal, double tipPercent)\nWhy does this method include two parameters instead of one?", "choices": ["Because every method must have exactly two parameters", "Because Java requires one parameter for the method name and one for the return type", "Because the method needs both the bill total and the tip percent as separate values in order to compute the tip", "Because billTotal and tipPercent are actually instance variables written on the wrong line"], "answer": 2, "explanation": "Parameters let a method receive each value it needs to accomplish its task, and here the method needs both the bill amount and the percentage to calculate a tip (3.5.A.7). There is no rule requiring exactly two parameters, no parameter role for a method name or return type, and these are ordinary parameters, not misplaced instance variables."},
  {"id": "3.5-intermediate-01", "course": "csa", "topic": "3.5", "tier": "intermediate", "lo": "3.5.A.2", "prompt": "Consider the following class.\npublic class Rectangle\n{\n    private double length;\n    private double width;\n    public Rectangle(double len, double wid)\n    {\n        length = len;\n        width = wid;\n    }\n    public double computePerimeter()\n    {\n        double perimeter = 2 * (length + width);\n        return perimeter;\n    }\n}\nWhich statement correctly describes computePerimeter?", "choices": ["It is a void method because it stores its result in a local variable before using it", "It is a non-void method because its header specifies double as the return type and it returns a compatible value", "It is a void method because length and width are private", "It is a non-void method only because it has a parameter list"], "answer": 1, "explanation": "computePerimeter's header lists double in place of void, and it returns a double-compatible expression, making it a non-void method (3.5.A.2). Storing an intermediate result in a local variable does not affect whether a method is void, private instance variables have no bearing on return type, and this method actually has no parameters at all, so having a parameter list cannot be the reason."},
  {"id": "3.5-intermediate-02", "course": "csa", "topic": "3.5", "tier": "intermediate", "lo": "3.5.A.3", "prompt": "Consider the following class.\npublic class Circle\n{\n    private double radius;\n    public Circle(double r)\n    {\n        radius = r;\n    }\n    public double getCircumference()\n    {\n        return 2 * 3.14159 * radius;\n    }\n}\nIn another class, the following code executes.\nCircle c = new Circle(5.0);\ndouble result = c.getCircumference();\nWhat is stored in result after this code runs?", "choices": ["5.0", "3.14159", "approximately 31.4159", "0.0, because getCircumference does not actually return a value until printed"], "answer": 2, "explanation": "The return expression 2 * 3.14159 * radius is evaluated with radius equal to 5.0, producing approximately 31.4159, which is returned by value and stored in result (3.5.A.3). A return statement's value is produced as soon as the method call completes, regardless of whether it is later printed."},
  {"id": "3.5-intermediate-03", "course": "csa", "topic": "3.5", "tier": "intermediate", "lo": "3.5.A.4", "prompt": "Consider the following method inside a class named GradeChecker.\npublic String checkGrade(int score)\n{\n    if (score >= 90)\n    {\n        return \"A\";\n    }\n    else if (score >= 80)\n    {\n        return \"B\";\n    }\n    System.out.println(\"checked\");\n    return \"C or below\";\n}\nWhat is printed, and what is returned, when checkGrade(95) is called?", "choices": ["\"checked\" is printed, and \"A\" is returned", "\"checked\" is printed, and \"C or below\" is returned", "Nothing is printed, and both \"A\" and \"C or below\" are returned", "Nothing is printed, and \"A\" is returned, because the return inside the if statement exits the method immediately"], "answer": 3, "explanation": "Since score is 95, the condition score >= 90 is true, so return \"A\"; executes and immediately halts the method, meaning the println statement and the final return are never reached (3.5.A.4). A method can only return one value per call, so both values being returned is impossible."},
  {"id": "3.5-intermediate-04", "course": "csa", "topic": "3.5", "tier": "intermediate", "lo": "3.5.A.5", "prompt": "Consider the following class.\npublic class Playlist\n{\n    private String name;\n    private int songCount;\n    public Playlist(String playlistName, int count)\n    {\n        name = playlistName;\n        songCount = count;\n    }\n    public String getSummary()\n    {\n        return name + \" has \" + songCount + \" songs\";\n    }\n}\nWhich statement best describes getSummary?", "choices": ["It is an accessor method that builds and returns a String describing the playlist's instance variables without changing them", "It is a mutator method because it modifies name and songCount before returning", "It cannot compile because it uses two instance variables in one return statement", "It is a void method because it only returns a String rather than a number"], "answer": 0, "explanation": "getSummary reads name and songCount without altering them and returns a formatted String, making it a non-void accessor method (3.5.A.5). It never assigns new values to either instance variable, combining multiple instance variables in one return expression is legal, and returning a String does not make a method void."},
  {"id": "3.5-intermediate-05", "course": "csa", "topic": "3.5", "tier": "intermediate", "lo": "3.5.A.6", "prompt": "Consider the following class.\npublic class ScoreTracker\n{\n    private int totalPoints;\n    public ScoreTracker(int startingPoints)\n    {\n        totalPoints = startingPoints;\n    }\n    public void addPoints(int points)\n    {\n        totalPoints += points;\n    }\n    public int getTotalPoints()\n    {\n        return totalPoints;\n    }\n}\nIn another class, the following code executes.\nScoreTracker tracker = new ScoreTracker(10);\ntracker.addPoints(5);\nSystem.out.println(tracker.getTotalPoints());\nWhat is printed?", "choices": ["10", "15", "5", "Nothing, because addPoints does not return a value and cannot be used before getTotalPoints"], "answer": 1, "explanation": "addPoints is a mutator that updates totalPoints to 10 + 5 = 15, and getTotalPoints then returns that updated value as an accessor (3.5.A.6). A void method can still be called by itself as a statement even though it returns nothing, so the code compiles and prints 15, not the original 10 or just the added amount."},
  {"id": "3.5-intermediate-06", "course": "csa", "topic": "3.5", "tier": "intermediate", "lo": "3.5.A.7", "prompt": "Consider the following class.\npublic class TripPlanner\n{\n    private double milesPerGallon;\n    public TripPlanner(double mpg)\n    {\n        milesPerGallon = mpg;\n    }\n    public double estimateGallonsNeeded(double distanceInMiles)\n    {\n        return distanceInMiles / milesPerGallon;\n    }\n}\nWhat roles do milesPerGallon and distanceInMiles play in this class?", "choices": ["Both are parameters used only inside estimateGallonsNeeded", "milesPerGallon is a parameter of the constructor and a parameter of estimateGallonsNeeded at the same time", "milesPerGallon is an instance variable set once through the constructor's parameter, while distanceInMiles is a parameter that supplies a new value each time estimateGallonsNeeded is called", "distanceInMiles is an instance variable, while milesPerGallon is a local variable created inside estimateGallonsNeeded"], "answer": 2, "explanation": "milesPerGallon is stored as an instance variable, initialized once via the constructor's parameter mpg, while distanceInMiles is a parameter of estimateGallonsNeeded that supplies a value each time that method is called, letting the method use different distances (3.5.A.7). milesPerGallon is not itself a parameter of estimateGallonsNeeded, and distanceInMiles is not stored as an instance variable at all."},
  {"id": "3.5-intermediate-07", "course": "csa", "topic": "3.5", "tier": "intermediate", "lo": "3.5.A.8", "prompt": "Consider the following class.\npublic class Counter\n{\n    private int count;\n    public Counter(int startValue)\n    {\n        count = startValue;\n    }\n    public void tryReset(int newValue)\n    {\n        newValue = 0;\n    }\n}\nIn another class, the following code executes.\nCounter c = new Counter(8);\nint value = 100;\nc.tryReset(value);\nSystem.out.println(value);\nWhat is printed?", "choices": ["0", "8", "An error occurs because value cannot be passed as an argument", "100"], "answer": 3, "explanation": "Since value is a primitive int, tryReset's parameter newValue receives a copy of value's contents; assigning newValue = 0 only changes that local copy and has no effect on value in the calling code (3.5.A.8). The output is therefore 100, unaffected by count or the reassignment inside tryReset."},
  {"id": "3.5-intermediate-08", "course": "csa", "topic": "3.5", "tier": "intermediate", "lo": "3.5.A.1", "prompt": "A student is designing a Printer class with a method that sends a document to a physical printer but has no result to report back to the caller. Which of the following method headers is most appropriate?", "choices": ["public void printDocument(String documentName)", "public String printDocument(String documentName)", "public boolean printDocument(String documentName)", "public int printDocument(String documentName)"], "answer": 0, "explanation": "Since the method performs an action with nothing to send back, void is the correct choice before its name (3.5.A.1). The other three headers all promise a return value, which would require a return statement providing a String, boolean, or int result the method has no need to produce."},
  {"id": "3.5-intermediate-09", "course": "csa", "topic": "3.5", "tier": "intermediate", "lo": "3.5.A.2", "prompt": "Consider the following two candidate methods for a class Cylinder that already has private instance variables radius and height.\nI.\npublic void calculateVolume()\n{\n    double volume = 3.14159 * radius * radius * height;\n}\nII.\npublic double calculateVolume()\n{\n    return 3.14159 * radius * radius * height;\n}\nWhich method correctly computes and sends the cylinder's volume back to the class that calls it?", "choices": ["I, because it stores the result in a local variable named volume", "II, because its header specifies double as the return type and it returns the computed value", "Both I and II work identically since they compute the same expression", "Neither, because radius and height cannot be used inside a method"], "answer": 1, "explanation": "Method II declares double as its return type and returns the computed volume, so calling code can receive the result (3.5.A.2). Method I is void, so its local variable volume is discarded once the method ends and no value is ever sent back to the caller, making the two methods behave very differently despite computing the same expression."},
  {"id": "3.5-intermediate-10", "course": "csa", "topic": "3.5", "tier": "intermediate", "lo": "3.5.A.3", "prompt": "Consider the following class.\npublic class Inventory\n{\n    private int itemsInStock;\n    private int itemsSold;\n    public Inventory(int stock, int sold)\n    {\n        itemsInStock = stock;\n        itemsSold = sold;\n    }\n    public int getItemsRemaining()\n    {\n        return itemsInStock - itemsSold;\n    }\n}\nIn another class, the following code executes.\nInventory inv = new Inventory(50, 30);\nint remaining = inv.getItemsRemaining();\nWhat value is stored in remaining?", "choices": ["50", "30", "20", "80"], "answer": 2, "explanation": "The return expression itemsInStock - itemsSold evaluates to 50 - 30, or 20, which is returned by value and stored in remaining (3.5.A.3). The other choices reflect using only one instance variable or adding rather than subtracting them."},
  {"id": "3.5-intermediate-11", "course": "csa", "topic": "3.5", "tier": "intermediate", "lo": "3.5.A.4", "prompt": "Consider the following method inside a class named Validator.\npublic boolean isValidPassword(String password)\n{\n    if (password.length() < 8)\n    {\n        return false;\n    }\n    if (password.indexOf(\" \") >= 0)\n    {\n        return false;\n    }\n    return true;\n}\nWhy does isValidPassword never need to check both conditions once the first one fails?", "choices": ["Because Java automatically skips the length check whenever a space is found first", "Because password.length() and password.indexOf are the same method under a different name", "Because the second if statement can never be reached in any circumstance", "Because the first return statement to execute immediately exits the method, so any code after it, including the second if statement, does not run"], "answer": 3, "explanation": "A return statement inside an if block halts execution and returns control to the caller as soon as it runs, so once the first condition triggers return false;, the second if statement is never reached during that call (3.5.A.4). The second if statement is reachable when the first condition is false, and length() and indexOf are unrelated String methods."},
  {"id": "3.5-intermediate-12", "course": "csa", "topic": "3.5", "tier": "intermediate", "lo": "3.5.A.5", "prompt": "Consider the following class.\npublic class Rectangle2\n{\n    private double length;\n    private double width;\n    public Rectangle2(double len, double wid)\n    {\n        length = len;\n        width = wid;\n    }\n    public double getArea()\n    {\n        return length * width;\n    }\n    public void scale(double factor)\n    {\n        length = length * factor;\n        width = width * factor;\n    }\n}\nWhich method in this class is an accessor, and which is a mutator?", "choices": ["getArea is an accessor because it returns a computed value without changing the instance variables; scale is a mutator because it changes length and width", "getArea is a mutator because it uses multiplication; scale is an accessor because it has a parameter", "Both methods are accessors because both use the instance variables", "Both methods are mutators because both are declared inside the same class"], "answer": 0, "explanation": "getArea returns a value computed from length and width without modifying them, making it an accessor, while scale changes both instance variables and returns nothing, making it a mutator (3.5.A.5, 3.5.A.6). Using multiplication or having a parameter does not by itself determine accessor versus mutator status, and simply belonging to the same class does not make every method a mutator."},
  {"id": "3.5-intermediate-13", "course": "csa", "topic": "3.5", "tier": "intermediate", "lo": "3.5.A.6", "prompt": "A class Battery has a private instance variable chargePercent. A student writes the following method, intended to fully recharge the battery.\npublic void recharge()\n{\n    return 100;\n}\nWhy does this method fail to compile?", "choices": ["Because recharge does not have any parameters", "Because a void method cannot contain a return statement that returns a value, and this method also never actually updates chargePercent", "Because chargePercent must be passed in as a parameter to be changed", "Because return statements are not allowed inside methods that modify instance variables"], "answer": 1, "explanation": "A void method's return statement must not return a value at all, so return 100; is illegal here, and this draft additionally fails to accomplish its intended mutator purpose since it never assigns 100 to chargePercent (3.5.A.6). Parameters are not required to modify an instance variable that a method already has access to, and return statements without a value are allowed in mutators."},
  {"id": "3.5-intermediate-14", "course": "csa", "topic": "3.5", "tier": "intermediate", "lo": "3.5.A.7", "prompt": "Consider the following class.\npublic class TemperatureConverter\n{\n    private String scaleName;\n    public TemperatureConverter(String name)\n    {\n        scaleName = name;\n    }\n    public double convert(double degreesIn, double conversionFactor, double offset)\n    {\n        return degreesIn * conversionFactor + offset;\n    }\n}\nWhat is the primary purpose of giving convert three parameters instead of hard-coding specific numbers inside the method?", "choices": ["To prevent the method from ever being called more than once", "To allow the method to be declared without specifying a return type", "To let the same method perform the conversion calculation for many different input values and conversion formulas supplied by the caller", "To automatically turn degreesIn, conversionFactor, and offset into instance variables"], "answer": 2, "explanation": "Parameters let convert receive whatever values the caller supplies each time it is invoked, so one general method can handle many different conversions rather than needing a hard-coded version for each (3.5.A.7). The method can be called any number of times, still needs a return type since it is non-void, and parameters remain local to the method rather than becoming instance variables."},
  {"id": "3.5-intermediate-15", "course": "csa", "topic": "3.5", "tier": "intermediate", "lo": "3.5.A.8", "prompt": "Consider the following class.\npublic class Adjuster\n{\n    private int baseValue;\n    public Adjuster(int start)\n    {\n        baseValue = start;\n    }\n    public int adjust(int input)\n    {\n        input += baseValue;\n        return input;\n    }\n}\nIn another class, the following code executes.\nAdjuster a = new Adjuster(3);\nint original = 10;\nint result = a.adjust(original);\nSystem.out.println(original + \" \" + result);\nWhat is printed?", "choices": ["13 13", "3 10", "13 10", "10 13"], "answer": 3, "explanation": "Since original is a primitive int, adjust's parameter input receives a copy of its value; the statement input += baseValue changes only that local copy, leaving original unchanged at 10, while the method returns the adjusted copy, 13, which is stored in result (3.5.A.8). original is never modified by the method call, so it remains 10 regardless of what happens to input."},
  {"id": "3.5-complex-01", "course": "csa", "topic": "3.5", "tier": "complex", "lo": "3.5.A.4", "prompt": "Consider the following method inside a class named RouteChecker.\npublic String classifyRoute(int distanceInMiles)\n{\n    if (distanceInMiles > 100)\n    {\n        return \"long\";\n    }\n    else if (distanceInMiles > 20)\n    {\n        return \"medium\";\n    }\n    else\n    {\n        return \"short\";\n    }\n    System.out.println(\"done classifying\");\n}\nWhich statement correctly evaluates this method?", "choices": ["The method compiles and always prints \"done classifying\" before returning, regardless of distanceInMiles", "The method compiles, but the println statement only executes when distanceInMiles is exactly 20", "The method fails to compile because the println statement is unreachable \u2014 every branch of the if/else if/else chain already returns, so control can never reach that line", "The method fails to compile because a method may not contain more than one return statement"], "answer": 2, "explanation": "Since every branch of the if/else if/else chain contains a return statement, control can never fall through to reach the println call after the chain, making it unreachable code, which the Java compiler rejects (3.5.A.4). Java permits multiple return statements in one method, and there is no distanceInMiles value for which the println line would ever run."},
  {"id": "3.5-complex-02", "course": "csa", "topic": "3.5", "tier": "complex", "lo": "3.5.A.5", "prompt": "Consider the following class, which does not compile.\npublic class Appointment\n{\n    private String clientName;\n    private int durationMinutes;\n    public Appointment(String name, int minutes)\n    {\n        clientName = name;\n        durationMinutes = minutes;\n    }\n    public String getSummary()\n    {\n        String summary = clientName + \" (\" + duration + \" min)\";\n        return summary;\n    }\n}\nWhat is the compile error, and how should it be fixed?", "choices": ["getSummary must be declared void since it only builds a String; change public String getSummary() to public void getSummary()", "clientName cannot be used inside getSummary because it is private; it must be declared public", "The constructor is missing a return statement, so it must be changed to return durationMinutes", "duration is not a declared variable anywhere in the class; the instance variable is named durationMinutes, so duration should be replaced with durationMinutes"], "answer": 3, "explanation": "The class declares durationMinutes, not duration, so referencing duration inside getSummary refers to an undeclared variable and fails to compile; replacing it with durationMinutes fixes the accessor (3.5.A.5). getSummary correctly returns a String and should remain non-void, private instance variables are fully accessible from methods within their own declaring class, and constructors never return a value, so they cannot contain a return statement."},
  {"id": "3.5-complex-03", "course": "csa", "topic": "3.5", "tier": "complex", "lo": "3.5.A.6", "prompt": "A class SecuritySystem has a private instance variable armed. A student writes the following mutator, intended to arm the system.\npublic void armSystem()\n{\n    boolean armed = true;\n}\nWhen armSystem() is called on an object, the instance variable armed is never actually changed. What is the most likely explanation?", "choices": ["The declaration boolean armed = true; creates a new local variable named armed that only exists inside the method, rather than assigning true to the instance variable armed", "armSystem is declared void, and void methods are never allowed to change instance variables", "Local variables and instance variables must always have different names, so this code fails to compile", "The method needs a parameter in order to update any instance variable at all"], "answer": 0, "explanation": "Because the method redeclares armed with the type boolean, it creates a brand-new local variable that shadows the instance variable and disappears when the method ends, so writing armed = true; without redeclaring the type is required to change the instance variable (3.5.A.6). A void method can absolutely modify instance variables, using the same name for a local variable and an instance variable is legal Java, though it causes shadowing here, and a mutator does not require a parameter to update state that is already accessible."},
  {"id": "3.5-complex-04", "course": "csa", "topic": "3.5", "tier": "complex", "lo": "3.5.A.7", "prompt": "Consider the following class.\npublic class ShippingCalculator\n{\n    private double baseRate;\n    public ShippingCalculator(double rate)\n    {\n        baseRate = rate;\n    }\n    public double calculateCost(double weightInPounds, int zonesTraveled)\n    {\n        return baseRate + (weightInPounds * 0.5) + (zonesTraveled * 2.0);\n    }\n}\nConsider the following three candidate calls made from another class where calc is a properly instantiated ShippingCalculator reference.\nI.   calc.calculateCost(10.0, 3)\nII.  calc.calculateCost(3, 10.0)\nIII. calc.calculateCost(10, 3)\nWhich of these calls compile successfully?", "choices": ["I only", "I and III only", "II and III only", "I, II, and III"], "answer": 1, "explanation": "Calls I and III correctly supply a value compatible with double for weightInPounds followed by an int for zonesTraveled, since an int argument like 10 in call III widens automatically to double (3.5.A.7). Call II reverses the argument order, attempting to pass a double, 10.0, where an int is expected for zonesTraveled, which cannot be narrowed automatically and fails to compile."},
  {"id": "3.5-complex-05", "course": "csa", "topic": "3.5", "tier": "complex", "lo": "3.5.A.8", "prompt": "Consider the following class.\npublic class Inventory2\n{\n    private int stockCount;\n    public Inventory2(int count)\n    {\n        stockCount = count;\n    }\n    public void restock(int addedUnits)\n    {\n        addedUnits = addedUnits * 2;\n        stockCount += addedUnits;\n    }\n}\nIn another class, the following code executes.\nInventory2 inv = new Inventory2(20);\nint shipment = 5;\ninv.restock(shipment);\nSystem.out.println(shipment);\nWhat is printed, and why?", "choices": ["30, because restock updates both stockCount and shipment together", "10, because shipment is passed by reference and reflects the doubling inside restock", "5, because shipment is a primitive int, so restock's parameter addedUnits receives only a copy of its value, and reassigning addedUnits inside the method has no effect on shipment", "An error occurs because shipment is used both as an argument and later in a println statement"], "answer": 2, "explanation": "Since shipment is a primitive int, the parameter addedUnits is initialized with a copy of its value; doubling addedUnits and using it to update stockCount changes only the copy and the instance variable, leaving shipment itself at 5 in the caller (3.5.A.8). Primitive arguments are never passed by reference in Java, and there is nothing preventing a variable from being used as both an argument and later printed."},
  {"id": "3.5-complex-06", "course": "csa", "topic": "3.5", "tier": "complex", "lo": "3.5.A.1", "prompt": "A student is designing a MessageBoard class and drafts four candidate headers for a method that posts a message to the board and has no result to report back to the caller.\nI.   public void postMessage(String text)\nII.  public String postMessage(String text)\nIII. public postMessage(String text)\nIV.  void public postMessage(String text)\nWhich of these headers is both syntactically valid and appropriate for a method with no value to return?", "choices": ["II", "III", "IV", "I"], "answer": 3, "explanation": "Header I places void correctly before the method name, matching a method with nothing to send back to the caller (3.5.A.1). Header II declares a String return type that would require a return statement providing a String, header III omits a return type entirely and fails to compile, and header IV places the modifier and return type in the wrong order, which also fails to compile."},
  {"id": "3.5-complex-07", "course": "csa", "topic": "3.5", "tier": "complex", "lo": "3.5.A.2", "prompt": "A student is designing a Loan class and drafts four candidate methods intended to calculate and return the monthly payment as a double, given that the class already has private instance variables principal and monthlyRate.\nI.\npublic double getMonthlyPayment()\n{\n    return principal * monthlyRate;\n}\nII.\npublic void getMonthlyPayment()\n{\n    return principal * monthlyRate;\n}\nIII.\npublic double getMonthlyPayment()\n{\n    double payment = principal * monthlyRate;\n}\nIV.\ndouble getMonthlyPayment()\n{\n    principal * monthlyRate;\n}\nWhich of these candidates both compiles and correctly returns the calculated payment to the caller?", "choices": ["I", "II", "III", "IV"], "answer": 0, "explanation": "Candidate I declares double as the return type and returns a compatible expression, so it compiles and sends the computed payment back to the caller (3.5.A.2). Candidate II is void but illegally attempts to return a value, candidate III computes the value but never returns it, and candidate IV writes principal * monthlyRate as a standalone expression statement instead of a return statement, so it never returns a value either."},
  {"id": "3.5-complex-08", "course": "csa", "topic": "3.5", "tier": "complex", "lo": "3.5.A.3", "prompt": "Consider the following class.\npublic class UnitConverter\n{\n    private double conversionFactor;\n    public UnitConverter(double factor)\n    {\n        conversionFactor = factor;\n    }\n    public double convertValue(double amount)\n    {\n        double result = amount * conversionFactor;\n        return result;\n    }\n}\nIn another class, the following code executes.\nUnitConverter converter = new UnitConverter(2.5);\ndouble a = converter.convertValue(4.0);\ndouble b = converter.convertValue(a);\nSystem.out.println(a + \" \" + b);\nWhat is printed?", "choices": ["10.0 10.0", "10.0 25.0", "4.0 10.0", "2.5 6.25"], "answer": 1, "explanation": "The first call returns 4.0 * 2.5, or 10.0, which is stored in a; the second call then returns a * 2.5, meaning 10.0 * 2.5, or 25.0, stored in b, since each call independently evaluates and returns its own result (3.5.A.3). The other choices either fail to apply the conversion twice correctly or use the wrong values entirely."},
  {"id": "3.5-complex-09", "course": "csa", "topic": "3.5", "tier": "complex", "lo": "3.5.A.4", "prompt": "Consider the following method inside a class named DiscountCalculator.\npublic double applyDiscount(double price, boolean isMember)\n{\n    if (isMember)\n    {\n        double discounted = price * 0.9;\n        return discounted;\n    }\n    return price;\n}\nConsider the following three statements about this method.\nI.   If isMember is true, the statement return price; never executes for that call.\nII.  If isMember is false, the local variable discounted is never created.\nIII. A call to applyDiscount can cause both return statements to execute, in the order they appear.\nWhich of these statements are true?", "choices": ["I and III only", "II and III only", "I and II only", "I, II, and III"], "answer": 2, "explanation": "When isMember is true, the return inside the if block executes and immediately exits the method, so the final return price; is skipped (I), and when isMember is false, the if block's body, including the declaration of discounted, is never entered (II) (3.5.A.4). Statement III is false because a return statement halts the method immediately, so only one of the two return statements can ever execute during a single call."},
  {"id": "3.5-complex-10", "course": "csa", "topic": "3.5", "tier": "complex", "lo": "3.5.A.5", "prompt": "Consider the following class, which is intended to let other classes retrieve a student's average of two test scores.\npublic class TestScores\n{\n    private int testOne;\n    private int testTwo;\n    public TestScores(int t1, int t2)\n    {\n        testOne = t1;\n        testTwo = t2;\n    }\n    public double getAverage()\n    {\n        double avg = (testOne + testTwo) / 2;\n        return avg;\n    }\n}\nA programmer notices that getAverage() sometimes returns a whole number with no fractional part even when the true average should include a decimal, such as when testOne is 85 and testTwo is 92. What is the most likely cause of this bug?", "choices": ["getAverage should be declared void since it computes an average", "testOne and testTwo should be declared as double instead of int", "avg should be declared as an int instead of a double", "(testOne + testTwo) / 2 performs integer division because both testOne and testTwo are int, truncating any fractional part before the result is ever stored in the double variable avg"], "answer": 3, "explanation": "Since testOne and testTwo are both int, the expression (testOne + testTwo) / 2 uses integer division and truncates any decimal portion before being widened and stored in avg, so the accessor returns an incomplete value; writing (testOne + testTwo) / 2.0 would fix this (3.5.A.5). Declaring getAverage void would prevent it from returning any value at all, changing testOne and testTwo's type would restructure the whole class unnecessarily when only the division expression is the problem, and declaring avg as an int would make the loss of precision worse, not better."},
  {"id": "3.5-complex-11", "course": "csa", "topic": "3.5", "tier": "complex", "lo": "3.5.A.6", "prompt": "Consider the following class, which does not behave as intended.\npublic class ClimateControl\n{\n    private double currentTemp;\n    public ClimateControl(double temp)\n    {\n        currentTemp = temp;\n    }\n    public double adjustTemperature(double change) // Line 8\n    {\n        return currentTemp + change; // Line 10\n    }\n}\nThe adjustTemperature method is intended to permanently increase currentTemp by change and report nothing back to the caller. Which change corrects the method?", "choices": ["Replace line 8 with public void adjustTemperature(double change), and replace line 10 with currentTemp += change;", "Replace line 10 with currentTemp = currentTemp + change; return currentTemp;", "Keep the method exactly as written, since returning currentTemp + change already updates currentTemp", "Replace line 8 with private double adjustTemperature(double change), keeping line 10 unchanged"], "answer": 0, "explanation": "Since the method should update currentTemp permanently and report nothing back, it should be void, and its body should assign the new value with currentTemp += change; rather than merely returning a computed value that is never stored (3.5.A.6). The original version never assigns anything to currentTemp, so currentTemp is left unchanged no matter how many times the method is called; keeping a return type or making the method private does not fix the underlying issue that currentTemp is never actually updated."},
  {"id": "3.5-complex-12", "course": "csa", "topic": "3.5", "tier": "complex", "lo": "3.5.A.7", "prompt": "Consider the following two classes.\npublic class Coordinate\n{\n    private int xPos;\n    private int yPos;\n    public Coordinate(int x, int y)\n    {\n        xPos = x;\n        yPos = y;\n    }\n    public int getX()\n    {\n        return xPos;\n    }\n    public int getY()\n    {\n        return yPos;\n    }\n}\npublic class DistanceUtil\n{\n    public double distanceFromOrigin(Coordinate point)\n    {\n        int dx = point.getX();\n        int dy = point.getY();\n        return Math.sqrt(dx * dx + dy * dy);\n    }\n}\nHow does distanceFromOrigin make use of its parameter point?", "choices": ["point is a copy of the entire DistanceUtil class passed in as an argument", "point receives a reference to a Coordinate object, and the method calls that object's accessor methods, getX() and getY(), to obtain the values it needs", "point is automatically converted into two separate int parameters named dx and dy", "point cannot be used inside distanceFromOrigin because Coordinate and DistanceUtil are different classes"], "answer": 1, "explanation": "point is a parameter that receives a Coordinate object, and the method uses that object's own accessor methods to retrieve xPos and yPos indirectly rather than accessing the private fields directly (3.5.A.7). point is not a copy of a class, is not automatically split into separate parameters, and objects of one class can absolutely be used as parameter types in methods of another class."},
  {"id": "3.5-complex-13", "course": "csa", "topic": "3.5", "tier": "complex", "lo": "3.5.A.8", "prompt": "Consider the following class.\npublic class ScoreAdjuster\n{\n    private int bonusPool;\n    public ScoreAdjuster(int pool)\n    {\n        bonusPool = pool;\n    }\n    public int applyBonus(int playerScore, int bonusUsed)\n    {\n        playerScore += bonusUsed;\n        bonusPool -= bonusUsed;\n        return playerScore;\n    }\n}\nIn another class, the following code executes.\nScoreAdjuster adjuster = new ScoreAdjuster(50);\nint score = 80;\nint bonus = 10;\nint newScore = adjuster.applyBonus(score, bonus);\nSystem.out.println(score + \" \" + bonus + \" \" + newScore);\nWhat is printed?", "choices": ["90 10 90", "90 0 90", "80 10 90", "80 0 90"], "answer": 2, "explanation": "Both score and bonus are primitive int arguments, so applyBonus's parameters playerScore and bonusUsed each receive independent copies; changing playerScore inside the method and decrementing bonusPool have no effect on the caller's score or bonus variables, which remain 80 and 10, while the method returns the adjusted copy, 90, stored in newScore (3.5.A.8). Only bonusPool, an instance variable, is permanently changed by this call; the caller's local variables are untouched."},
  {"id": "3.5-complex-14", "course": "csa", "topic": "3.5", "tier": "complex", "lo": "3.5.A.1", "prompt": "A student is designing a NotificationSender class and drafts four candidate methods intended to send a notification and report nothing back to the caller.\nI.\npublic String sendNotification(String message)\n{\n    System.out.println(message);\n}\nII.\npublic void sendNotification(String message)\n{\n    return message;\n}\nIII.\nvoid sendNotification(String message)\n{\n    return \"sent\";\n}\nIV.\npublic void sendNotification(String message)\n{\n    System.out.println(message);\n}\nWhich candidate correctly compiles as a method with no return value?", "choices": ["I", "II", "III", "IV"], "answer": 3, "explanation": "Candidate IV correctly declares void and contains no return statement that provides a value, matching a method with nothing to send back (3.5.A.1). Candidate I promises a String but never returns one, and candidates II and III are void methods that illegally attempt to return a value, which does not compile regardless of the access modifier used."},
  {"id": "3.5-complex-15", "course": "csa", "topic": "3.5", "tier": "complex", "lo": "3.5.A.2", "prompt": "A student is designing a WeatherStation2 class that already has private instance variables highTemp and lowTemp, both int, and drafts four candidate methods intended to calculate and return the day's temperature range as an int.\nI.\npublic int getTempRange()\n{\n    return highTemp - lowTemp;\n}\nII.\npublic void getTempRange()\n{\n    return highTemp - lowTemp;\n}\nIII.\npublic int getTempRange()\n{\n    int range = highTemp - lowTemp;\n}\nIV.\npublic double getTempRange()\n{\n    return \"range value\";\n}\nWhich candidate both compiles and correctly returns the temperature range to the caller?", "choices": ["I", "II", "III", "IV"], "answer": 0, "explanation": "Candidate I declares int as the return type and returns a compatible int expression, so it compiles and correctly sends the range back to the caller (3.5.A.2). Candidate II is void but illegally returns a value, candidate III computes the range but never returns it, and candidate IV declares double as its return type yet attempts to return a String literal, which is not compatible with double."},
  {"id": "3.6-basic-01", "course": "csa", "topic": "3.6", "tier": "basic", "lo": "3.6.A.1", "prompt": "A ScoreCard class is defined as follows.\npublic class ScoreCard\n{\n    private int points;\n\n    public ScoreCard(int startPoints)\n    {\n        points = startPoints;\n    }\n\n    public void addPoints(int amount)\n    {\n        points = points + amount;\n    }\n\n    public int getPoints()\n    {\n        return points;\n    }\n}\nThe following method appears in a separate class.\npublic void boostScore(ScoreCard card)\n{\n    card.addPoints(10);\n}\nThe following code segment appears in a method in that same separate class.\nScoreCard sc = new ScoreCard(5);\nboostScore(sc);\nSystem.out.println(sc.getPoints());\nWhat is printed when the code segment executes?", "choices": ["15", "5", "10", "The code does not compile"], "answer": 0, "explanation": "card is a parameter that receives a copy of the reference stored in sc, so card and sc refer to the exact same ScoreCard object. Calling card.addPoints(10) mutates that shared object, raising points from 5 to 15, which is why sc.getPoints() reports 15 (3.6.A.1). \"5\" wrongly assumes the object argument is copied independently and left unaffected, \"10\" confuses the amount added with the final total, and the code is entirely legal, so it does compile."},
  {"id": "3.6-basic-02", "course": "csa", "topic": "3.6", "tier": "basic", "lo": "3.6.A.1", "prompt": "A Wallet class is defined as follows.\npublic class Wallet\n{\n    private int cash;\n\n    public Wallet(int startCash)\n    {\n        cash = startCash;\n    }\n\n    public void addCash(int amount)\n    {\n        cash = cash + amount;\n    }\n\n    public int getCash()\n    {\n        return cash;\n    }\n}\nThe following method appears in a separate class.\npublic void tryToChange(int amount, Wallet w)\n{\n    amount = 999;\n    w.addCash(50);\n}\nThe following code segment appears in a method in that same separate class.\nint amount = 20;\nWallet myWallet = new Wallet(100);\ntryToChange(amount, myWallet);\nWhich of the following correctly describes the result of executing this code segment?", "choices": ["amount changes to 999 and myWallet's cash changes to 150", "amount stays 20 and myWallet's cash changes to 150", "amount changes to 999 and myWallet's cash stays 100", "amount stays 20 and myWallet's cash stays 100"], "answer": 1, "explanation": "amount is a primitive int, so tryToChange receives only a copy of its value; reassigning the parameter amount inside the method has no effect on the caller's amount, which stays 20 (3.6.A.1). Wallet is an object, so w is a copy of the reference stored in myWallet; calling w.addCash(50) mutates the shared Wallet object, changing cash to 150. The other choices either wrongly change the caller's primitive or wrongly assume neither value changes."},
  {"id": "3.6-basic-03", "course": "csa", "topic": "3.6", "tier": "basic", "lo": "3.6.A.2", "prompt": "Two classes are defined as follows.\npublic class Balloon\n{\n    private String color;\n\n    public Balloon(String startColor)\n    {\n        color = startColor;\n    }\n\n    public String getColor()\n    {\n        return color;\n    }\n\n    public void setColor(String newColor)\n    {\n        color = newColor;\n    }\n}\npublic class BalloonShelf\n{\n    private Balloon stored;\n\n    public BalloonShelf(Balloon b)\n    {\n        stored = b;\n    }\n\n    public Balloon fetch()\n    {\n        return stored;\n    }\n}\nThe following code segment appears in a separate class.\nBalloon original = new Balloon(\"red\");\nBalloonShelf shelf = new BalloonShelf(original);\nBalloon fetched = shelf.fetch();\nfetched.setColor(\"blue\");\nSystem.out.println(original.getColor());\nWhat is printed?", "choices": ["red", "Two colors are printed: red then blue", "blue", "The code does not compile"], "answer": 2, "explanation": "fetch() returns the exact reference stored in the private field stored, which is the same reference passed in as original, so fetched and original refer to one identical Balloon object (3.6.A.2). Calling fetched.setColor(\"blue\") therefore mutates that shared object, so original.getColor() also reports \"blue\" (3.6.A.1). \"red\" wrongly assumes returning a reference makes an independent copy, and only one println statement runs, so no two colors are printed."},
  {"id": "3.6-basic-04", "course": "csa", "topic": "3.6", "tier": "basic", "lo": "3.6.A.1", "prompt": "A Greeter class is defined as follows.\npublic class Greeter\n{\n    public String shorten(String text)\n    {\n        text = text.substring(0, 3);\n        return text;\n    }\n}\nThe following code segment appears in a separate class.\nGreeter g = new Greeter();\nString phrase = \"Hello there\";\nString result = g.shorten(phrase);\nSystem.out.println(phrase);\nWhat is printed?", "choices": ["Hel", "there", "The code does not compile", "Hello there"], "answer": 3, "explanation": "String objects are immutable, so substring() always builds and returns a brand-new String rather than modifying the original characters. Reassigning the parameter text inside shorten only changes what that local parameter refers to; it never changes what the caller's variable phrase refers to, so phrase still holds \"Hello there\" (3.6.A.1). \"Hel\" mistakenly reports the value of result instead of phrase, \"there\" is not produced by any operation here, and the code compiles without issue."},
  {"id": "3.6-basic-05", "course": "csa", "topic": "3.6", "tier": "basic", "lo": "3.6.A.3", "prompt": "A Locker class has a private instance variable named combination. A method in a different class, Hallway, receives a Locker object as a parameter. Which of the following statements is true about code inside a method of the Hallway class?", "choices": ["It cannot directly access the Locker parameter's combination field, since combination is private and Hallway is a different class", "It can directly access the Locker parameter's combination field, since any parameter can access private data", "It can directly access combination only if the parameter's name is exactly the same as in Locker", "It can directly access combination only if Hallway is declared public"], "answer": 0, "explanation": "Private instance variables can only be accessed directly, using dot notation, by code inside the same class that declared them. Since Hallway is a different class from Locker, it cannot write something like lockerParam.combination even though it holds a valid reference to a Locker object (3.6.A.3). Access does not depend on the parameter's name matching anything in Locker, and it does not depend on whether Hallway itself is declared public."},
  {"id": "3.6-basic-06", "course": "csa", "topic": "3.6", "tier": "basic", "lo": "3.6.A.1", "prompt": "A Candle class is defined as follows.\npublic class Candle\n{\n    private int inchesLeft;\n\n    public Candle(int startInches)\n    {\n        inchesLeft = startInches;\n    }\n\n    public void burn(int inches)\n    {\n        inchesLeft = inchesLeft - inches;\n    }\n\n    public int getInchesLeft()\n    {\n        return inchesLeft;\n    }\n}\nThe following method appears in a separate class.\npublic void burnCandle(Candle c)\n{\n    c.burn(2);\n}\nThe following code segment appears in a method in that same separate class.\nCandle candleA = new Candle(10);\nCandle candleB = new Candle(10);\nburnCandle(candleA);\nSystem.out.println(candleB.getInchesLeft());\nWhat is printed?", "choices": ["8", "10", "12", "The code does not compile"], "answer": 1, "explanation": "candleA and candleB are two separate Candle objects created by two separate calls to new. Passing candleA into burnCandle only mutates the object candleA refers to, since c is a copy of candleA's reference, not candleB's (3.6.A.1). candleB is never passed into burnCandle at all, so its inchesLeft is untouched and remains 10. 8 would be candleA's updated value, and 12 is not produced by any operation shown."},
  {"id": "3.6-basic-07", "course": "csa", "topic": "3.6", "tier": "basic", "lo": "3.6.A.2", "prompt": "Two classes are defined as follows.\npublic class Envelope\n{\n    private String contents;\n\n    public Envelope(String startContents)\n    {\n        contents = startContents;\n    }\n\n    public String getContents()\n    {\n        return contents;\n    }\n}\npublic class Mailroom\n{\n    public Envelope makeEnvelope()\n    {\n        Envelope e = new Envelope(\"blank\");\n        return e;\n    }\n}\nThe following code segment appears in a separate class.\nMailroom room = new Mailroom();\nEnvelope e1 = room.makeEnvelope();\nEnvelope e2 = room.makeEnvelope();\nWhich of the following is true about e1 and e2 after this code executes?", "choices": ["e1 and e2 refer to the same Envelope object, since makeEnvelope always returns the identical reference", "The code does not compile, since a method cannot return a newly created object", "e1 and e2 refer to two different Envelope objects, since each call to makeEnvelope constructs and returns a reference to a brand-new object", "e1 and e2 are both null, since local variables inside a method cannot be returned"], "answer": 2, "explanation": "Every call to makeEnvelope() executes new Envelope(\"blank\") again, constructing and returning a reference to a distinct new object, so e1 and e2 refer to two separate Envelope objects even though they happen to hold identical contents (3.6.A.2). It is completely legal for a method to return a reference to an object it just created; the reference itself is what gets returned. Neither variable is null, and the claim that both calls share one object misunderstands what new does each time it runs."},
  {"id": "3.6-basic-08", "course": "csa", "topic": "3.6", "tier": "basic", "lo": "3.6.A.1", "prompt": "A Backpack class is defined as follows.\npublic class Backpack\n{\n    private int itemCount;\n\n    public Backpack(int startCount)\n    {\n        itemCount = startCount;\n    }\n\n    public void addItem()\n    {\n        itemCount = itemCount + 1;\n    }\n\n    public int getItemCount()\n    {\n        return itemCount;\n    }\n}\nThe following code segment appears in a separate class.\nBackpack pack1 = new Backpack(3);\nBackpack pack2 = pack1;\npack2.addItem();\nSystem.out.println(pack1.getItemCount());\nWhat is printed?", "choices": ["3", "0", "The code does not compile", "4"], "answer": 3, "explanation": "The assignment pack2 = pack1 copies the reference, not the object, so pack1 and pack2 end up referring to the exact same Backpack object. Calling pack2.addItem() mutates that shared object's itemCount, which is why pack1.getItemCount() also reports the updated value, 4 (3.6.A.1). \"3\" assumes pack1 and pack2 are independent objects, which they are not, and neither 0 nor a compile error is supported by this code."},
  {"id": "3.6-basic-09", "course": "csa", "topic": "3.6", "tier": "basic", "lo": "3.6.A.3", "prompt": "Two classes are defined as follows.\npublic class Jar\n{\n    private int cookieCount;\n\n    public Jar(int startCount)\n    {\n        cookieCount = startCount;\n    }\n}\npublic class Pantry\n{\n    public void compareJars(Jar jarA, Jar jarB)\n    {\n        System.out.println(jarA.cookieCount);\n    }\n}\nWhy does this code fail to compile?", "choices": ["cookieCount is a private instance variable of Jar, and Pantry is a different class, so it cannot access jarA.cookieCount directly", "Jar does not have a constructor, so no Jar object can ever be created", "A method cannot have two parameters of the same class type", "System.out.println cannot be used inside a method that has parameters"], "answer": 0, "explanation": "Private access is restricted to code written inside the declaring class. Since compareJars is defined in Pantry, not Jar, it cannot use dot notation to read jarA's private cookieCount field directly; it would need a public accessor instead (3.6.A.3). Jar does have a constructor, methods may certainly have two parameters of the same type, and println works fine with parameters \u2014 none of those are the actual issue."},
  {"id": "3.6-basic-10", "course": "csa", "topic": "3.6", "tier": "basic", "lo": "3.6.A.1", "prompt": "A Thermometer class is defined as follows.\npublic class Thermometer\n{\n    private double reading;\n\n    public Thermometer(double startReading)\n    {\n        reading = startReading;\n    }\n\n    public double getReading()\n    {\n        return reading;\n    }\n}\nThe following method appears in a separate class.\npublic double celsiusToFahrenheit(Thermometer t)\n{\n    return t.getReading() * 9.0 / 5.0 + 32;\n}\nThe following code segment appears in a method in that same separate class.\nThermometer therm = new Thermometer(20.0);\ndouble result = celsiusToFahrenheit(therm);\nWhich statement is true about the parameter t inside celsiusToFahrenheit?", "choices": ["t refers to a brand-new Thermometer object created just for this method call", "t is a copy of the reference stored in therm, so t and therm refer to the same Thermometer object", "t is a copy of the entire Thermometer object, independent from therm", "t cannot be used to call getReading(), since getReading() is a method"], "answer": 1, "explanation": "When an object reference is passed as an argument, the parameter receives a copy of that reference, not a copy of the object's data and not a newly created object, so t and therm refer to the same Thermometer object (3.6.A.1). No new object is created by this call, and calling the public method getReading() on t is perfectly legal, since t genuinely refers to a valid Thermometer object."},
  {"id": "3.6-basic-11", "course": "csa", "topic": "3.6", "tier": "basic", "lo": "3.6.A.1", "prompt": "A Sign class is defined as follows.\npublic class Sign\n{\n    public void flip(boolean isOn)\n    {\n        isOn = !isOn;\n    }\n}\nThe following code segment appears in a separate class.\nSign sign = new Sign();\nboolean lightOn = true;\nsign.flip(lightOn);\nSystem.out.println(lightOn);\nWhat is printed?", "choices": ["false", "The code does not compile", "true", "null"], "answer": 2, "explanation": "boolean is a primitive type, so flip's parameter isOn receives only a copy of lightOn's value. Reassigning isOn inside flip has no effect whatsoever on the caller's variable, so lightOn is unchanged and still prints true (3.6.A.1). \"false\" would only be correct if primitives were passed by reference, which Java never does, and a boolean variable can never hold null."},
  {"id": "3.6-basic-12", "course": "csa", "topic": "3.6", "tier": "basic", "lo": "3.6.A.2", "prompt": "Two classes are defined as follows.\npublic class Paintbrush\n{\n    private String bristleColor;\n\n    public Paintbrush(String startColor)\n    {\n        bristleColor = startColor;\n    }\n\n    public String getBristleColor()\n    {\n        return bristleColor;\n    }\n}\npublic class ArtBox\n{\n    private Paintbrush brush;\n\n    public ArtBox(Paintbrush b)\n    {\n        brush = b;\n    }\n\n    public Paintbrush getBrush()\n    {\n        return brush;\n    }\n}\nThe following code segment appears in a separate class.\nPaintbrush pb = new Paintbrush(\"green\");\nArtBox box = new ArtBox(pb);\nPaintbrush sameBrush = box.getBrush();\nWhich best describes the relationship between sameBrush and pb after this code executes?", "choices": ["sameBrush and pb are unrelated, since getBrush() only returns a copy of the brush's data", "sameBrush refers to a brand-new Paintbrush object, since getBrush() always constructs one to return", "The code does not compile, since a method cannot return a private instance variable's reference", "sameBrush and pb refer to the exact same Paintbrush object, since getBrush() returns the reference stored in brush, not a copy"], "answer": 3, "explanation": "getBrush() simply returns the reference value already stored in the private field brush, and that reference is the same one pb was constructed from, so sameBrush and pb are aliases for a single Paintbrush object (3.6.A.2). No new object is ever constructed inside getBrush(), the two variables are not unrelated, and returning a stored reference from a public method is entirely legal, private field or not."},
  {"id": "3.6-basic-13", "course": "csa", "topic": "3.6", "tier": "basic", "lo": "3.6.A.1", "prompt": "An Odometer class is defined as follows.\npublic class Odometer\n{\n    private int miles;\n\n    public Odometer(int startMiles)\n    {\n        miles = startMiles;\n    }\n\n    public void addMiles(int extra)\n    {\n        miles = miles + extra;\n    }\n\n    public int getMiles()\n    {\n        return miles;\n    }\n}\nThe following method appears in a separate class.\npublic void logTrip(int tripLength, Odometer car)\n{\n    tripLength = tripLength + 5;\n    car.addMiles(tripLength);\n}\nThe following code segment appears in a method in that same separate class.\nint tripLength = 10;\nOdometer car = new Odometer(200);\nlogTrip(tripLength, car);\nAfter this code executes, what are the values of tripLength (in the caller) and car.getMiles()?", "choices": ["tripLength is 10; car.getMiles() is 215", "tripLength is 15; car.getMiles() is 215", "tripLength is 10; car.getMiles() is 205", "tripLength is 15; car.getMiles() is 205"], "answer": 0, "explanation": "tripLength in the caller is a primitive int, so it is completely unaffected by any reassignment made to the parameter inside logTrip and remains 10. Inside the method, the local copy of tripLength becomes 15, and car.addMiles(15) mutates the shared Odometer object, since car is an alias for the caller's object, making car.getMiles() equal 200 + 15 = 215 (3.6.A.1). The other choices incorrectly change the caller's primitive value or miscalculate the final mileage."},
  {"id": "3.6-basic-14", "course": "csa", "topic": "3.6", "tier": "basic", "lo": "3.6.A.3", "prompt": "A Coin class is defined as follows.\npublic class Coin\n{\n    private int cents;\n\n    public Coin(int startCents)\n    {\n        cents = startCents;\n    }\n\n    public boolean sameValue(Coin other)\n    {\n        return cents == other.cents;\n    }\n}\nWhy does sameValue compile successfully even though it accesses other.cents directly?", "choices": ["Because cents was declared without the private keyword", "Because sameValue is defined inside the Coin class, and private access is restricted by class, not by individual object", "Because other is guaranteed to be the same object as the one calling sameValue", "Because int values are never private, only String and object types can be private"], "answer": 1, "explanation": "Private access depends on which class the code is written in, not on which specific object it involves. Since sameValue is a method of Coin, it may directly access the private cents field of any Coin object, including one passed in as a parameter (3.6.A.3). cents is in fact declared private, other does not need to be the same object as the caller, and primitive fields such as int can absolutely be declared private."},
  {"id": "3.6-basic-15", "course": "csa", "topic": "3.6", "tier": "basic", "lo": "3.6.A.1", "prompt": "A Kite class is defined as follows.\npublic class Kite\n{\n    private int height;\n\n    public Kite(int startHeight)\n    {\n        height = startHeight;\n    }\n\n    public int getHeight()\n    {\n        return height;\n    }\n}\nThe following method appears in a separate class.\npublic int readHeight(Kite k)\n{\n    int h = k.getHeight();\n    h = h + 100;\n    return h;\n}\nThe following code segment appears in a method in that same separate class.\nKite myKite = new Kite(30);\nint result = readHeight(myKite);\nSystem.out.println(myKite.getHeight());\nWhat is printed?", "choices": ["130", "100", "30", "The code does not compile"], "answer": 2, "explanation": "readHeight only reads height through the public getter getHeight() and stores it in a local primitive variable h; changing h afterward has no effect on the Kite object at all, since h is just a local int, not a reference to the object (3.6.A.1). Because no mutator method was ever called on myKite, its height was never changed, so getHeight() still reports the original value, 30. 130 confuses the local computation inside readHeight with the object's actual state, and 100 is not the value of anything printed here."},
  {"id": "3.6-intermediate-01", "course": "csa", "topic": "3.6", "tier": "intermediate", "lo": "3.6.A.1", "prompt": "Two classes are defined as follows.\npublic class Garden\n{\n    private int flowerCount;\n\n    public Garden(int startCount)\n    {\n        flowerCount = startCount;\n    }\n\n    public void plantFlowers(int amount)\n    {\n        flowerCount = flowerCount + amount;\n    }\n\n    public int getFlowerCount()\n    {\n        return flowerCount;\n    }\n}\npublic class Gardener\n{\n    public void waterAndPlant(Garden g, int extra)\n    {\n        extra = extra * 2;\n        g.plantFlowers(extra);\n    }\n}\nThe following code segment appears in a separate class.\nGarden yard = new Garden(5);\nGardener sam = new Gardener();\nint extra = 3;\nsam.waterAndPlant(yard, extra);\nSystem.out.println(extra);\nSystem.out.println(yard.getFlowerCount());\nWhich of the following correctly describes what is printed?", "choices": ["extra becomes 6, and yard's flowerCount becomes 11", "extra remains 3, and yard's flowerCount becomes 8", "extra becomes 6, and yard's flowerCount becomes 8", "extra remains 3, and yard's flowerCount becomes 11"], "answer": 3, "explanation": "extra in the caller is a primitive int, so waterAndPlant only receives a copy of its value; reassigning the parameter extra = extra * 2 inside the method has no effect on the caller's extra, which remains 3. Inside the method, however, the local copy of extra becomes 6, and g.plantFlowers(6) mutates the actual Garden object yard refers to, since g is a copy of that same reference, making flowerCount equal 5 + 6 = 11 (3.6.A.1). The other choices incorrectly change the caller's primitive or miscalculate the final flower count."},
  {"id": "3.6-intermediate-02", "course": "csa", "topic": "3.6", "tier": "intermediate", "lo": "3.6.A.2", "prompt": "Two classes are defined as follows.\npublic class Ribbon\n{\n    private double length;\n\n    public Ribbon(double startLength)\n    {\n        length = startLength;\n    }\n\n    public double getLength()\n    {\n        return length;\n    }\n\n    public void trim(double amount)\n    {\n        length = length - amount;\n    }\n}\npublic class RibbonSpool\n{\n    public Ribbon longerRibbon(Ribbon a, Ribbon b)\n    {\n        if (a.getLength() > b.getLength())\n        {\n            return a;\n        }\n        return b;\n    }\n}\nThe following code segment appears in a separate class.\nRibbon r1 = new Ribbon(12.0);\nRibbon r2 = new Ribbon(8.0);\nRibbonSpool spool = new RibbonSpool();\nRibbon winner = spool.longerRibbon(r1, r2);\nwinner.trim(2.0);\nSystem.out.println(r1.getLength());\nWhat is printed?", "choices": ["10.0", "12.0", "8.0", "The code does not compile"], "answer": 0, "explanation": "longerRibbon returns one of its own parameters' existing references rather than constructing a new Ribbon, so since r1's length (12.0) is greater than r2's, winner becomes an alias for the exact same object r1 refers to (3.6.A.2). Calling winner.trim(2.0) therefore mutates r1 itself, reducing its length from 12.0 to 10.0 (3.6.A.1). 12.0 wrongly assumes trimming winner does not affect r1, and 8.0 incorrectly confuses r1 with r2."},
  {"id": "3.6-intermediate-03", "course": "csa", "topic": "3.6", "tier": "intermediate", "lo": "3.6.A.1", "prompt": "Two classes are defined as follows.\npublic class Suitcase\n{\n    private double weight;\n\n    public Suitcase(double startWeight)\n    {\n        weight = startWeight;\n    }\n\n    public void addWeight(double amount)\n    {\n        weight = weight + amount;\n    }\n\n    public double getWeight()\n    {\n        return weight;\n    }\n}\npublic class TravelAgency\n{\n    public void packExtra(Suitcase bag, double amount)\n    {\n        amount = amount + 1.0;\n        bag.addWeight(amount);\n    }\n}\nThe following code segment appears in a separate class.\nSuitcase suitcase = new Suitcase(20.0);\ndouble extraWeight = 4.0;\nTravelAgency agency = new TravelAgency();\nagency.packExtra(suitcase, extraWeight);\nConsider the following statements about the state of the program immediately after packExtra returns.\nI. extraWeight in the caller still equals 4.0.\nII. suitcase.getWeight() equals 25.0.\nIII. The parameter bag and the variable suitcase refer to two different Suitcase objects.\nWhich of the statements are true?", "choices": ["I only", "I and II only", "II and III only", "I, II, and III"], "answer": 1, "explanation": "extraWeight is a primitive double, so its value in the caller is unaffected by the reassignment inside packExtra, making I true. Inside the method, amount becomes 5.0, and bag.addWeight(5.0) mutates the shared object, making suitcase.getWeight() equal 25.0, so II is also true. However, bag is a copy of the very same reference stored in suitcase, so they refer to the identical Suitcase object, not two different ones, making III false (3.6.A.1). Only I and II are true."},
  {"id": "3.6-intermediate-04", "course": "csa", "topic": "3.6", "tier": "intermediate", "lo": "3.6.A.3", "prompt": "A Battery class is defined as follows.\npublic class Battery\n{\n    private int chargePercent;\n\n    public Battery(int startCharge)\n    {\n        chargePercent = startCharge;\n    }\n\n    public Battery combine(Battery other)\n    {\n        int total = chargePercent + other.chargePercent;\n        if (total > 100)\n        {\n            total = 100;\n        }\n        return new Battery(total);\n    }\n}\nA second version of combine is instead written inside a separate class, as follows.\npublic class ChargerStation\n{\n    public Battery combine(Battery a, Battery b)\n    {\n        int total = a.chargePercent + b.chargePercent;\n        return new Battery(total);\n    }\n}\nWhich version(s) of combine compile successfully?", "choices": ["Version II only", "Both versions", "Version I only", "Neither version"], "answer": 2, "explanation": "The first version is defined inside the Battery class, so it may directly access the private chargePercent field of both the current object and the other parameter, since private access is determined by class, not by which object is involved (3.6.A.3). The second version is defined in a separate class, ChargerStation, so a.chargePercent and b.chargePercent are illegal direct accesses to a private field and cause a compile error; ChargerStation would need to call a public accessor instead."},
  {"id": "3.6-intermediate-05", "course": "csa", "topic": "3.6", "tier": "intermediate", "lo": "3.6.A.1", "prompt": "A Notebook class is defined as follows.\npublic class Notebook\n{\n    private String owner;\n\n    public Notebook(String startOwner)\n    {\n        owner = startOwner;\n    }\n\n    public String getOwner()\n    {\n        return owner;\n    }\n}\nThe following method appears in a separate class.\npublic void attemptSwap(Notebook a, Notebook b)\n{\n    Notebook temp = a;\n    a = b;\n    b = temp;\n}\nThe following code segment appears in a method in that same separate class.\nNotebook n1 = new Notebook(\"Amy\");\nNotebook n2 = new Notebook(\"Ben\");\nattemptSwap(n1, n2);\nSystem.out.println(n1.getOwner());\nSystem.out.println(n2.getOwner());\nWhat is printed?", "choices": ["n1 prints Ben and n2 prints Amy, because attemptSwap successfully swaps which object each refers to", "n1 prints Amy and n2 prints Amy, because both parameters end up referring to the same object", "The code does not compile, since Notebook objects cannot be reassigned inside a method", "n1 prints Amy and n2 prints Ben, because reassigning the parameters a and b inside attemptSwap only changes what those local parameters refer to, not what n1 and n2 refer to"], "answer": 3, "explanation": "Although attemptSwap reassigns which objects its parameters a and b refer to, those reassignments only affect the local parameter variables inside the method. The caller's variables n1 and n2 still refer to their original objects, because a and b are separate copies of the references, not the references n1 and n2 themselves (3.6.A.1). So n1 still prints \"Amy\" and n2 still prints \"Ben\". The claim that the objects are successfully swapped misunderstands that reassigning a parameter never changes the caller's variable, and no compile error results from reassigning a parameter."},
  {"id": "3.6-intermediate-06", "course": "csa", "topic": "3.6", "tier": "intermediate", "lo": "3.6.A.1", "prompt": "A Speaker class is defined as follows.\npublic class Speaker\n{\n    private int volume;\n\n    public Speaker(int startVolume)\n    {\n        volume = startVolume;\n    }\n\n    public void setVolume(int newVolume)\n    {\n        volume = newVolume;\n    }\n\n    public int getVolume()\n    {\n        return volume;\n    }\n}\nConsider three separate methods, each called exactly once with a Speaker argument named mySpeaker that starts with volume 40.\nI.\npublic void methodOne(Speaker s)\n{\n    s = new Speaker(10);\n}\nII.\npublic void methodTwo(Speaker s)\n{\n    s.setVolume(10);\n}\nIII.\npublic void methodThree(Speaker s)\n{\n    int v = s.getVolume();\n    v = 10;\n}\nAfter each method is called once on mySpeaker, for which method(s) does mySpeaker.getVolume() become 10?", "choices": ["II only", "I only", "I and III only", "I, II, and III"], "answer": 0, "explanation": "methodOne reassigns the local parameter s to refer to a brand-new Speaker object, which has no effect on mySpeaker, since s was only ever a copy of mySpeaker's reference and the original object is never touched. methodTwo calls the mutator setVolume(10) through s, which is an alias for mySpeaker, so this genuinely changes mySpeaker's volume to 10 (3.6.A.1). methodThree only copies the volume into a local primitive variable v and changes v, without ever calling a mutator on the object, so mySpeaker is unaffected. Only II actually mutates mySpeaker."},
  {"id": "3.6-intermediate-07", "course": "csa", "topic": "3.6", "tier": "intermediate", "lo": "3.6.A.2", "prompt": "Two classes are defined as follows.\npublic class Recipe\n{\n    private int calories;\n\n    public Recipe(int startCalories)\n    {\n        calories = startCalories;\n    }\n\n    public int getCalories()\n    {\n        return calories;\n    }\n}\npublic class Cookbook\n{\n    public Recipe combineRecipes(Recipe r1, Recipe r2)\n    {\n        Recipe combined = new Recipe(r1.getCalories() + r2.getCalories());\n        return combined;\n    }\n}\nThe following code segment appears in a separate class.\nRecipe soup = new Recipe(200);\nRecipe bread = new Recipe(150);\nCookbook book = new Cookbook();\nRecipe combo = book.combineRecipes(soup, bread);\nWhich of the following is true?", "choices": ["combo refers to the same object as soup, since combineRecipes returns a reference to one of its parameters", "combo refers to a brand-new Recipe object that is separate from both soup and bread, with calories equal to 350", "combo refers to a brand-new Recipe object, but its calories field remains 0, since new objects cannot be initialized from parameter data", "The code does not compile, since a method cannot create a new object using data read from its parameters"], "answer": 1, "explanation": "combineRecipes constructs a brand-new Recipe object using new, initialized with the sum of the two parameters' calorie values, and returns a reference to that new object, so combo is entirely independent of both soup and bread while correctly holding 350 calories (3.6.A.2). combo is not an alias for either parameter, its calories field is properly set through the constructor rather than left at a default, and reading values from parameters to build a new object is entirely legal."},
  {"id": "3.6-intermediate-08", "course": "csa", "topic": "3.6", "tier": "intermediate", "lo": "3.6.A.3", "prompt": "Two classes are defined as follows.\npublic class Player\n{\n    private int rank;\n\n    public Player(int startRank)\n    {\n        rank = startRank;\n    }\n\n    public int getRank()\n    {\n        return rank;\n    }\n}\npublic class ScoreKeeper\n{\n    private int bonus;\n\n    public ScoreKeeper(Player p)\n    {\n        bonus = p.getRank() * 2;\n    }\n\n    public int getBonus()\n    {\n        return bonus;\n    }\n}\nThe following code segment appears in a separate class.\nPlayer p1 = new Player(5);\nScoreKeeper keeper = new ScoreKeeper(p1);\nSystem.out.println(keeper.getBonus());\nWhat is printed, and why is this the only legal way for ScoreKeeper's constructor to obtain rank's value?", "choices": ["5, because ScoreKeeper directly accesses p.rank, which is legal since Player passed itself as a parameter", "10, because ScoreKeeper directly accesses p.rank, which is legal since rank is technically public inside a constructor", "5, because ScoreKeeper is a different class and can only obtain rank through Player's public getRank() method, not by writing p.rank directly", "10, because ScoreKeeper is a different class and can only obtain rank through Player's public getRank() method, not by writing p.rank directly"], "answer": 3, "explanation": "Since rank is private and ScoreKeeper is a class other than Player, ScoreKeeper cannot legally write p.rank directly; it must call the public accessor getRank() to obtain the value, exactly as the constructor does (3.6.A.3). getRank() returns 5, so bonus becomes 5 * 2 = 10. The choices claiming direct field access is legal both misstate the private access rule, and the choice with correct reasoning paired with the wrong printed value miscalculates the bonus."},
  {"id": "3.6-intermediate-09", "course": "csa", "topic": "3.6", "tier": "intermediate", "lo": "3.6.A.1", "prompt": "A Painting class is defined as follows.\npublic class Painting\n{\n    private String title;\n\n    public Painting(String startTitle)\n    {\n        title = startTitle;\n    }\n\n    public String getTitle()\n    {\n        return title;\n    }\n\n    public void setTitle(String newTitle)\n    {\n        title = newTitle;\n    }\n}\nA specification states that a display method should show a Painting's title without permanently changing the Painting object passed in. Two candidate implementations are proposed for a method in a separate Gallery class.\nI.\npublic String displayTitle(Painting p)\n{\n    String shown = p.getTitle();\n    return shown;\n}\nII.\npublic String displayTitle(Painting p)\n{\n    p.setTitle(p.getTitle());\n    return p.getTitle();\n}\nWhich version correctly follows the specification and good practice of not modifying a mutable object parameter unless required?", "choices": ["II only, since it explicitly reassigns the title before returning it", "Neither version, since any method receiving a mutable object parameter must modify it", "Both versions, since setTitle and getTitle have no real effect on the object", "I only, since it reads title through getTitle() without calling any mutator, leaving the Painting object unchanged"], "answer": 3, "explanation": "Version I only calls the accessor getTitle() and never calls a mutator, so it never changes the Painting object's state at all, matching good practice of not modifying a mutable parameter unless the specification requires it (3.6.A.1). Version II calls setTitle(), a mutator, even though it happens to reset the title to its same value in this case; relying on a mutator when none is required is not good practice, since in general such a call could produce a real, unwanted modification. There is no rule requiring every method with an object parameter to modify it, and the two versions are not equivalent in intent."},
  {"id": "3.6-intermediate-10", "course": "csa", "topic": "3.6", "tier": "intermediate", "lo": "3.6.A.2", "prompt": "Two classes are defined as follows.\npublic class Fish\n{\n    private double lengthInches;\n\n    public Fish(double startLength)\n    {\n        lengthInches = startLength;\n    }\n\n    public double getLength()\n    {\n        return lengthInches;\n    }\n\n    public void grow(double amount)\n    {\n        lengthInches = lengthInches + amount;\n    }\n}\npublic class Aquarium\n{\n    private Fish resident;\n\n    public Aquarium(Fish startFish)\n    {\n        resident = startFish;\n    }\n\n    public Fish getResident()\n    {\n        return resident;\n    }\n\n    public Fish makeClone()\n    {\n        Fish copy = new Fish(resident.getLength());\n        return copy;\n    }\n}\nThe following code segment appears in a separate class.\nFish goldie = new Fish(3.0);\nAquarium tank = new Aquarium(goldie);\nFish sameFish = tank.getResident();\nFish clonedFish = tank.makeClone();\nsameFish.grow(1.0);\nclonedFish.grow(5.0);\nSystem.out.println(goldie.getLength());\nWhat is printed?", "choices": ["4.0", "9.0", "3.0", "The code does not compile"], "answer": 0, "explanation": "getResident() returns the same reference stored in resident, which is the same object goldie refers to, so sameFish.grow(1.0) mutates goldie itself, raising its length from 3.0 to 4.0 (3.6.A.2, 3.6.A.1). In contrast, makeClone() constructs and returns a reference to a brand-new Fish object built from resident's current length, so clonedFish is entirely independent; growing clonedFish by 5.0 has no effect on goldie. 9.0 incorrectly combines both growth amounts as if they affected the same object, and 3.0 ignores the mutation made through sameFish entirely."},
  {"id": "3.6-intermediate-11", "course": "csa", "topic": "3.6", "tier": "intermediate", "lo": "3.6.A.3", "prompt": "A Mailbox class is defined as follows.\npublic class Mailbox\n{\n    private int letterCount;\n\n    public Mailbox(int startCount)\n    {\n        letterCount = startCount;\n    }\n}\nThe following method, intended to compare two Mailbox objects, is defined in a separate class, PostOffice, and does not compile.\npublic class PostOffice\n{\n    public boolean sameCount(Mailbox m1, Mailbox m2)\n    {\n        return m1.letterCount == m2.letterCount;\n    }\n}\nWhich change would fix this compile error while following good encapsulation practice and preserving the method's intended behavior?", "choices": ["Change letterCount's declaration in Mailbox to public", "Add a public method to Mailbox, such as getLetterCount(), and rewrite sameCount to call m1.getLetterCount() == m2.getLetterCount()", "Rename the parameters m1 and m2 to match letterCount exactly", "Move the PostOffice class's code into the same .java file as Mailbox, without changing anything else"], "answer": 1, "explanation": "The best fix that preserves encapsulation is to add a public accessor to Mailbox and have sameCount call it instead of accessing the private field directly, since private access is restricted to code inside the declaring class (3.6.A.3). Making letterCount public would technically also compile, but it breaks encapsulation and is not appropriate style; renaming parameters and simply placing both classes in the same file do not change which class the method is defined in, so neither would fix the actual error."},
  {"id": "3.6-intermediate-12", "course": "csa", "topic": "3.6", "tier": "intermediate", "lo": "3.6.A.1", "prompt": "Three classes are defined as follows.\npublic class Engine\n{\n    private int horsepower;\n\n    public Engine(int startHp)\n    {\n        horsepower = startHp;\n    }\n\n    public void upgrade(int amount)\n    {\n        horsepower = horsepower + amount;\n    }\n\n    public int getHorsepower()\n    {\n        return horsepower;\n    }\n}\npublic class Scooter\n{\n    private Engine motor;\n\n    public Scooter(Engine startMotor)\n    {\n        motor = startMotor;\n    }\n\n    public Engine getMotor()\n    {\n        return motor;\n    }\n}\npublic class Mechanic\n{\n    public void tuneUp(Scooter s)\n    {\n        Engine e = s.getMotor();\n        e.upgrade(20);\n    }\n}\nThe following code segment appears in a separate class.\nEngine eng = new Engine(50);\nScooter scoot = new Scooter(eng);\nMechanic joe = new Mechanic();\njoe.tuneUp(scoot);\nSystem.out.println(eng.getHorsepower());\nWhat is printed?", "choices": ["50", "20", "70", "The code does not compile"], "answer": 2, "explanation": "getMotor() returns the same reference stored in motor, which is the same object eng refers to; calling e.upgrade(20) inside tuneUp mutates that shared Engine object, so eng.getHorsepower() reflects the change and reports 70 (3.6.A.1, 3.6.A.2). 50 wrongly assumes the nested object is somehow copied when it is passed through two layers of objects, and 20 confuses the upgrade amount with the final horsepower total."},
  {"id": "3.6-intermediate-13", "course": "csa", "topic": "3.6", "tier": "intermediate", "lo": "3.6.A.2", "prompt": "Two classes are defined as follows.\npublic class Ticket\n{\n    private int price;\n\n    public Ticket(int startPrice)\n    {\n        price = startPrice;\n    }\n\n    public int getPrice()\n    {\n        return price;\n    }\n\n    public void discount(int amount)\n    {\n        price = price - amount;\n    }\n}\npublic class BoxOffice\n{\n    public Ticket cheaperTicket(Ticket a, Ticket b)\n    {\n        Ticket temp = new Ticket(0);\n        if (a.getPrice() < b.getPrice())\n        {\n            return a;\n        }\n        return b;\n    }\n}\nThe following code segment appears in a separate class.\nTicket t1 = new Ticket(30);\nTicket t2 = new Ticket(45);\nBoxOffice office = new BoxOffice();\nTicket cheap = office.cheaperTicket(t1, t2);\ncheap.discount(5);\nSystem.out.println(t1.getPrice());\nSystem.out.println(t2.getPrice());\nWhat is printed?", "choices": ["t1 prints 30 and t2 prints 40, because temp absorbs the discount instead of either ticket", "t1 prints 25 and t2 prints 40, because both tickets receive part of the discount", "t1 prints 30 and t2 prints 45, because cheap is a new Ticket object unrelated to either t1 or t2", "t1 prints 25 and t2 prints 45, because cheap refers to the same object as t1, and the discount is applied only to that shared object"], "answer": 3, "explanation": "Since t1's price (30) is less than t2's price (45), cheaperTicket returns a, which is the same reference as t1; the locally created temp object is never returned and has no effect on the outcome. cheap therefore becomes an alias for t1, so cheap.discount(5) mutates t1 itself, reducing its price to 25, while t2 is never touched and remains 45 (3.6.A.2, 3.6.A.1). The other choices incorrectly involve temp, split the discount between both tickets, or assume cheap is an unrelated new object."},
  {"id": "3.6-intermediate-14", "course": "csa", "topic": "3.6", "tier": "intermediate", "lo": "3.6.A.3", "prompt": "A GridPoint class is defined as follows.\npublic class GridPoint\n{\n    private int x;\n    private int y;\n\n    public GridPoint(int startX, int startY)\n    {\n        x = startX;\n        y = startY;\n    }\n\n    public GridPoint copyOf(GridPoint other)\n    {\n        GridPoint newPoint = new GridPoint(other.x, other.y);\n        return newPoint;\n    }\n\n    public int getX()\n    {\n        return x;\n    }\n}\nThe following code segment appears in a separate class.\nGridPoint original = new GridPoint(3, 4);\nGridPoint blank = new GridPoint(0, 0);\nGridPoint duplicate = blank.copyOf(original);\nWhich of the following is true about this code?", "choices": ["The code compiles, because copyOf is defined inside GridPoint, so it may access other.x and other.y directly even though other is a parameter; duplicate refers to a new, independent GridPoint object", "The code does not compile, because other.x and other.y are private and cannot be accessed even inside GridPoint", "The code compiles, but duplicate refers to the same object as original, since copyOf simply returns other's reference", "The code compiles, but duplicate's x and y both remain 0, since new GridPoint(other.x, other.y) ignores the parameter values"], "answer": 0, "explanation": "Because copyOf is a method of the GridPoint class, it may directly access the private x and y fields of any GridPoint object, including the parameter other, since private access is restricted by class rather than by object (3.6.A.3). The method builds and returns a brand-new GridPoint object using other's current values, so duplicate is an independent object with x equal to 3, rather than an alias of original or an object left at default values."},
  {"id": "3.6-intermediate-15", "course": "csa", "topic": "3.6", "tier": "intermediate", "lo": "3.6.A.1", "prompt": "A Piggybank class is defined as follows.\npublic class Piggybank\n{\n    private double savings;\n\n    public Piggybank(double startSavings)\n    {\n        savings = startSavings;\n    }\n\n    public void addFunds(double amount)\n    {\n        savings = savings + amount;\n    }\n\n    public double getSavings()\n    {\n        return savings;\n    }\n}\nThe following method appears in a separate class, and its specification states that it should leave the Piggybank unchanged if amount is negative.\npublic void depositIfPositive(Piggybank bank, double amount)\n{\n    if (amount > 0)\n    {\n        bank.addFunds(amount);\n    }\n}\nThe following code segment appears in a method in that same separate class.\nPiggybank kidBank = new Piggybank(20.0);\ndepositIfPositive(kidBank, -5.0);\nSystem.out.println(kidBank.getSavings());\nWhat is printed, and does this implementation correctly follow the specification?", "choices": ["15.0; yes, because addFunds is called with the negative amount, correctly reducing savings", "20.0; yes, because addFunds is only called when amount is positive, so the negative amount never mutates bank", "20.0; no, because bank is still passed by reference even though addFunds is never called", "15.0; no, because the specification is violated by allowing a negative amount to be passed in at all"], "answer": 1, "explanation": "Since amount (-5.0) is not greater than 0, the if condition is false, and addFunds is never called, so the shared Piggybank object kidBank is never mutated and its savings remains 20.0, correctly satisfying the specification (3.6.A.1). Merely passing an object's reference into a method does not by itself change the object; only calling a mutator method actually alters its state, so the third choice's reasoning is incorrect, and the other choices misstate either the printed value or whether the specification was followed."},
  {"id": "3.6-complex-01", "course": "csa", "topic": "3.6", "tier": "complex", "lo": "3.6.A.1", "prompt": "Two classes are defined as follows.\npublic class Vault\n{\n    private int goldBars;\n\n    public Vault(int startBars)\n    {\n        goldBars = startBars;\n    }\n\n    public void deposit(int amount)\n    {\n        goldBars = goldBars + amount;\n    }\n\n    public void withdraw(int amount)\n    {\n        goldBars = goldBars - amount;\n    }\n\n    public int getGoldBars()\n    {\n        return goldBars;\n    }\n}\npublic class Bank\n{\n    public void transfer(Vault from, Vault to, int amount)\n    {\n        from.withdraw(amount);\n        to.deposit(amount);\n    }\n}\nThe following code segment appears in a separate class.\nVault mainVault = new Vault(100);\nVault backupVault = mainVault;\nVault reserveVault = new Vault(50);\nBank centralBank = new Bank();\ncentralBank.transfer(mainVault, reserveVault, 20);\nbackupVault.withdraw(10);\nSystem.out.println(mainVault.getGoldBars());\nSystem.out.println(reserveVault.getGoldBars());\nWhich of the following correctly describes what is printed?", "choices": ["mainVault.getGoldBars() prints 80 and reserveVault.getGoldBars() prints 70", "mainVault.getGoldBars() prints 70 and reserveVault.getGoldBars() prints 50", "mainVault.getGoldBars() prints 70 and reserveVault.getGoldBars() prints 70", "mainVault.getGoldBars() prints 90 and reserveVault.getGoldBars() prints 70"], "answer": 2, "explanation": "backupVault = mainVault makes backupVault an alias for the exact same Vault object, and from and to inside transfer are also just copies of the references mainVault and reserveVault, not new objects (3.6.A.1). transfer withdraws 20 from the shared mainVault/backupVault object, taking it from 100 to 80, and deposits 20 into reserveVault, raising it from 50 to 70. Afterward, backupVault.withdraw(10) mutates that same shared object again, since backupVault is an alias for mainVault, bringing it down to 70. Both mainVault and reserveVault end up printing 70; the other choices fail to account for one of these mutations or contain an arithmetic error."},
  {"id": "3.6-complex-02", "course": "csa", "topic": "3.6", "tier": "complex", "lo": "3.6.A.3", "prompt": "An Employee class is defined as follows.\npublic class Employee\n{\n    private double salary;\n\n    public Employee(double startSalary)\n    {\n        salary = startSalary;\n    }\n\n    public double getSalary()\n    {\n        return salary;\n    }\n}\nConsider five candidate implementations, each intended to compare two Employee objects' salaries.\nI. Defined inside Employee:\npublic boolean earnsMoreThan(Employee other)\n{\n    return salary > other.salary;\n}\nII. Defined inside Employee:\npublic boolean earnsMoreThan(Employee other)\n{\n    return getSalary() > other.getSalary();\n}\nIII. Defined inside a separate class, Payroll:\npublic boolean earnsMoreThan(Employee e1, Employee e2)\n{\n    return e1.salary > e2.salary;\n}\nIV. Defined inside a separate class, Payroll:\npublic boolean earnsMoreThan(Employee e1, Employee e2)\n{\n    return e1.getSalary() > e2.getSalary();\n}\nV. Defined inside Employee, calling a private helper method also defined inside Employee:\npublic boolean earnsMoreThan(Employee other)\n{\n    return isRicherThan(other);\n}\nprivate boolean isRicherThan(Employee other)\n{\n    return salary > other.salary;\n}\nWhich of the five candidate implementations of earnsMoreThan compile successfully?", "choices": ["I and II only", "III and IV only", "I, II, and III only", "I, II, IV, and V only"], "answer": 3, "explanation": "I and II both compile because they are defined inside Employee, where accessing another Employee's private salary field is legal by class, not by object; II simply routes through the public getter instead, but both are equally legal. III fails to compile because it is defined in Payroll, a separate class, and directly accesses e1.salary and e2.salary, which are private; Payroll must use getSalary() instead, exactly as IV correctly does, so IV compiles. V also compiles, since it and its private helper method isRicherThan are both defined inside Employee, making direct access to salary and other.salary inside isRicherThan legal (3.6.A.3). Only III, the cross-class direct access, fails to compile."},
  {"id": "3.6-complex-03", "course": "csa", "topic": "3.6", "tier": "complex", "lo": "3.6.A.1", "prompt": "Three classes are defined as follows.\npublic class Plant\n{\n    private double heightCm;\n\n    public Plant(double startHeight)\n    {\n        heightCm = startHeight;\n    }\n\n    public void grow(double amount)\n    {\n        heightCm = heightCm + amount;\n    }\n\n    public double getHeight()\n    {\n        return heightCm;\n    }\n}\npublic class Greenhouse\n{\n    private Plant tallPlant;\n    private Plant shortPlant;\n\n    public Greenhouse(Plant p1, Plant p2)\n    {\n        tallPlant = p1;\n        shortPlant = p2;\n    }\n\n    public Plant getTallPlant()\n    {\n        return tallPlant;\n    }\n\n    public Plant getShortPlant()\n    {\n        return shortPlant;\n    }\n}\npublic class Botanist\n{\n    public void swapCare(Greenhouse house, double amount)\n    {\n        Plant a = house.getTallPlant();\n        Plant b = house.getShortPlant();\n        a.grow(amount);\n        b.grow(amount * 2);\n    }\n}\nThe following code segment appears in a separate class.\nPlant rose = new Plant(30.0);\nPlant fern = new Plant(15.0);\nGreenhouse house = new Greenhouse(rose, fern);\nBotanist worker = new Botanist();\nworker.swapCare(house, 5.0);\nConsider the following statements after swapCare executes.\nI. rose.getHeight() equals 35.0.\nII. fern.getHeight() equals 25.0.\nIII. house.getTallPlant() and rose refer to two different Plant objects.\nWhich statements are true?", "choices": ["I and II only", "I, II, and III", "II and III only", "I only"], "answer": 0, "explanation": "getTallPlant() and getShortPlant() return the exact references stored in tallPlant and shortPlant, which are the same objects rose and fern refer to, since the Greenhouse constructor simply assigns tallPlant = p1 and shortPlant = p2 without copying. Inside swapCare, a is an alias for rose and b is an alias for fern; a.grow(5.0) makes rose.getHeight() equal 35.0 (I true), and b.grow(10.0) makes fern.getHeight() equal 25.0 (II true) (3.6.A.1, 3.6.A.2). Since tallPlant is never reassigned to a new object, house.getTallPlant() still refers to the exact same object as rose, making III false rather than true."},
  {"id": "3.6-complex-04", "course": "csa", "topic": "3.6", "tier": "complex", "lo": "3.6.A.2", "prompt": "Two classes are defined as follows.\npublic class Money\n{\n    private double amount;\n\n    public Money(double startAmount)\n    {\n        amount = startAmount;\n    }\n\n    public void add(double extra)\n    {\n        amount = amount + extra;\n    }\n\n    public double getAmount()\n    {\n        return amount;\n    }\n}\npublic class ExchangeBooth\n{\n    public Money process(Money input, boolean makeCopy)\n    {\n        if (makeCopy)\n        {\n            Money copy = new Money(input.getAmount());\n            return copy;\n        }\n        return input;\n    }\n}\nThe following code segment appears in a separate class.\nMoney cash = new Money(100.0);\nExchangeBooth booth = new ExchangeBooth();\nMoney resultA = booth.process(cash, true);\nMoney resultB = booth.process(cash, false);\nresultA.add(10.0);\nresultB.add(20.0);\nSystem.out.println(cash.getAmount());\nWhat is printed?", "choices": ["100.0", "120.0", "130.0", "The code does not compile"], "answer": 1, "explanation": "process(cash, true) executes the makeCopy branch, constructing a brand-new Money object from cash's current amount and returning that new reference, so resultA is entirely independent of cash; adding 10.0 to resultA never affects cash (3.6.A.2). process(cash, false) skips that branch and simply returns input, which is a copy of the same reference as cash, making resultB an alias for cash; resultB.add(20.0) therefore mutates cash itself, raising its amount from 100.0 to 120.0 (3.6.A.1). 100.0 ignores the mutation made through resultB, and 130.0 incorrectly assumes resultA's addition also affected cash."},
  {"id": "3.6-complex-05", "course": "csa", "topic": "3.6", "tier": "complex", "lo": "3.6.A.3", "prompt": "Two classes are defined as follows.\npublic class Ingredient\n{\n    private String name;\n    private double grams;\n\n    public Ingredient(String startName, double startGrams)\n    {\n        name = startName;\n        grams = startGrams;\n    }\n\n    public String getName()\n    {\n        return name;\n    }\n\n    public double getGrams()\n    {\n        return grams;\n    }\n}\npublic class Batch\n{\n    private Ingredient main;\n\n    public Batch(Ingredient startMain)\n    {\n        main = startMain;\n    }\n\n    public Ingredient getMain()\n    {\n        return main;\n    }\n\n    public boolean sameName(Ingredient other)\n    {\n        /* return statement goes here */\n    }\n}\nFive candidate replacements for the return statement inside sameName are proposed.\nI. return main.name.equals(other.name);\nII. return main.getName().equals(other.getName());\nIII. return getMain().name.equals(other.name);\nIV. return getMain().getName().equals(other.getName());\nV. return main.getName().equals(other.name);\nWhich of the following replacements compile successfully?", "choices": ["I and III only", "I, III, and V only", "II and IV only", "All five compile successfully"], "answer": 2, "explanation": "Batch is a class separate from Ingredient, so any direct use of dot notation to reach the private name field, such as main.name or other.name, fails to compile, no matter whether main itself was obtained through a public method like getMain() (which eliminates I, III, and V). Only II and IV replace every direct field access with a call to the public getName() accessor, which is legal from any class (3.6.A.3). The five statements are not all equivalent, since three of them still reference a private field directly."},
  {"id": "3.6-complex-06", "course": "csa", "topic": "3.6", "tier": "complex", "lo": "3.6.A.2", "prompt": "Three classes are defined as follows.\npublic class Cargo\n{\n    private int weight;\n\n    public Cargo(int startWeight)\n    {\n        weight = startWeight;\n    }\n\n    public int getWeight()\n    {\n        return weight;\n    }\n\n    public void unload(int amount)\n    {\n        weight = weight - amount;\n    }\n}\npublic class Ship\n{\n    private Cargo hold;\n\n    public Ship(Cargo startCargo)\n    {\n        hold = startCargo;\n    }\n\n    public Cargo getHold()\n    {\n        return hold;\n    }\n}\npublic class Harbor\n{\n    public void inspect(Ship ship, int amount)\n    {\n        Cargo c = ship.getHold();\n        c.unload(amount);\n    }\n}\nThe following code segment appears in a separate class.\nCargo crate = new Cargo(500);\nShip vessel = new Ship(crate);\nHarbor port = new Harbor();\nport.inspect(vessel, 150);\nport.inspect(vessel, 100);\nSystem.out.println(crate.getWeight());\nWhat is printed?", "choices": ["500", "350", "150", "250"], "answer": 3, "explanation": "getHold() returns the reference stored in hold, which is the same object crate refers to, so each call to inspect obtains an alias for crate and mutates it directly through unload (3.6.A.2, 3.6.A.1). The first call reduces the weight from 500 to 350, and the second call reduces it further from 350 to 250, so crate.getWeight() reports 250 after both calls. 500 ignores both mutations, 350 accounts for only the first call, and 150 incorrectly totals the two unloaded amounts as if that were the final weight rather than a sequence of subtractions from 500."},
  {"id": "3.6-complex-07", "course": "csa", "topic": "3.6", "tier": "complex", "lo": "3.6.A.1", "prompt": "A Robot class is defined as follows.\npublic class Robot\n{\n    private int position;\n    private int batteryLevel;\n\n    public Robot(int startPosition, int startBattery)\n    {\n        position = startPosition;\n        batteryLevel = startBattery;\n    }\n\n    public void move(int steps)\n    {\n        position = position + steps;\n    }\n\n    public void drain(int amount)\n    {\n        batteryLevel = batteryLevel - amount;\n    }\n\n    public int getPosition()\n    {\n        return position;\n    }\n\n    public int getBatteryLevel()\n    {\n        return batteryLevel;\n    }\n}\nConsider five independent method calls, each starting from the same Robot object named bot with position 0 and batteryLevel 100.\nI.\npublic void operationOne(Robot r)\n{\n    r.move(5);\n}\nII.\npublic void operationTwo(Robot r)\n{\n    r = new Robot(99, 99);\n}\nIII.\npublic void operationThree(Robot r, int steps)\n{\n    steps = steps + 10;\n    r.move(steps);\n}\nIV.\npublic void operationFour(int position)\n{\n    position = position + 5;\n}\nV.\npublic void operationFive(Robot r)\n{\n    r.drain(10);\n    r.move(1);\n}\nFor which of these method calls does bot's state (position and/or batteryLevel) actually change as a result of the call?", "choices": ["I, III, and V only", "I, II, III, and V only", "I and V only", "I, III, IV, and V only"], "answer": 0, "explanation": "operationOne and operationFive both call mutator methods (move and/or drain) on r, which is an alias for bot, so both genuinely change bot's state; operationThree also mutates bot through r.move(steps), even though steps is first reassigned locally, since that reassignment only affects the local primitive parameter, not which object r refers to (3.6.A.1). operationTwo only reassigns the local reference r to a brand-new Robot object and never calls a mutator on the original, so bot is untouched. operationFour does not even receive a Robot parameter \u2014 it only reassigns a local int copy \u2014 so it has no way to affect bot at all. Only I, III, and V actually mutate bot."},
  {"id": "3.6-complex-08", "course": "csa", "topic": "3.6", "tier": "complex", "lo": "3.6.A.3", "prompt": "Two classes are defined as follows.\npublic class Guest\n{\n    private String guestName;\n    private boolean checkedIn;\n\n    public Guest(String startName)\n    {\n        guestName = startName;\n        checkedIn = false;\n    }\n\n    public String getGuestName()\n    {\n        return guestName;\n    }\n\n    public void markCheckedIn()\n    {\n        checkedIn = true;\n    }\n\n    public void registerAt(Venue place)\n    {\n        place.checkIn(guestName);\n    }\n}\npublic class Venue\n{\n    private int guestCount;\n\n    public void checkIn(String name)\n    {\n        System.out.println(name + \" has checked in.\");\n        guestCount = guestCount + 1;\n    }\n\n    public void checkInDirect(Guest g)\n    {\n        System.out.println(g.guestName + \" has checked in.\");\n        guestCount = guestCount + 1;\n    }\n}\nTwo methods in Venue are shown above, checkIn(String name) and checkInDirect(Guest g). Which statement correctly evaluates these two methods?", "choices": ["Both methods compile, because Venue is allowed to access any field of any class it interacts with", "checkIn compiles because it only uses a String parameter; checkInDirect does not compile because it directly accesses g.guestName, a private field of a different class", "Neither method compiles, because guestCount is never initialized in a constructor", "checkInDirect compiles because Guest passed g through a registerAt method first; checkIn does not compile because String is immutable"], "answer": 1, "explanation": "checkIn(String name) only works with a String parameter and never touches Guest's private data, so it compiles without issue. checkInDirect(Guest g) is defined in Venue, a class other than Guest, and directly accesses g.guestName, which is private, so this line fails to compile (3.6.A.3); Venue would need a public accessor like getGuestName() instead. Access to another class's private data is never blanket-allowed just because the classes interact, guestCount not being explicitly initialized in a constructor does not itself cause a compile error since instance variables default to 0, and String's immutability is unrelated to this compile error."},
  {"id": "3.6-complex-09", "course": "csa", "topic": "3.6", "tier": "complex", "lo": "3.6.A.1", "prompt": "Two classes are defined as follows.\npublic class Backpack\n{\n    private int itemCount;\n\n    public Backpack(int startCount)\n    {\n        itemCount = startCount;\n    }\n\n    public void addItem()\n    {\n        itemCount = itemCount + 1;\n    }\n\n    public int getItemCount()\n    {\n        return itemCount;\n    }\n}\npublic class Student\n{\n    private Backpack bag;\n\n    public Student(Backpack startBag)\n    {\n        bag = startBag;\n    }\n\n    public Backpack getBag()\n    {\n        return bag;\n    }\n\n    public void setBag(Backpack newBag)\n    {\n        bag = newBag;\n    }\n}\nThe following code segment appears in a separate class.\nBackpack shared = new Backpack(2);\nStudent amy = new Student(shared);\nStudent ben = new Student(shared);\namy.getBag().addItem();\nSystem.out.println(ben.getBag().getItemCount());\nben.setBag(new Backpack(10));\namy.getBag().addItem();\nSystem.out.println(ben.getBag().getItemCount());\nWhich of the following correctly describes what is printed by the two println statements, in order?", "choices": ["3 then 4", "2 then 10", "3 then 10", "4 then 4"], "answer": 2, "explanation": "Initially amy and ben both store the same reference, shared, so amy.getBag().addItem() mutates that one shared Backpack, making its itemCount 3; since ben.bag still refers to that same object, the first println prints 3 (3.6.A.1). ben.setBag(new Backpack(10)) then reassigns ben's bag field to point to an entirely new, separate Backpack object, breaking the link between ben and shared. The second amy.getBag().addItem() call still mutates shared (now at itemCount 4), but ben.bag no longer refers to shared, so the second println reflects the new object's untouched value, 10. The other choices fail to account for either the initial sharing or the later reassignment that breaks that link."},
  {"id": "3.6-complex-10", "course": "csa", "topic": "3.6", "tier": "complex", "lo": "3.6.A.2", "prompt": "A Reading class is defined as follows.\npublic class Reading\n{\n    private double tempF;\n\n    public Reading(double startTemp)\n    {\n        tempF = startTemp;\n    }\n\n    public double getTempF()\n    {\n        return tempF;\n    }\n\n    public void adjust(double amount)\n    {\n        tempF = tempF + amount;\n    }\n}\nFive candidate implementations of chooseWarmer are proposed, each defined in a class named WeatherLog, separate from Reading, and each intended only to determine and return whichever Reading is currently warmer without modifying either parameter.\nI.\npublic Reading chooseWarmer(Reading a, Reading b)\n{\n    if (a.getTempF() >= b.getTempF())\n    {\n        return a;\n    }\n    return b;\n}\nII.\npublic Reading chooseWarmer(Reading a, Reading b)\n{\n    if (a.getTempF() >= b.getTempF())\n    {\n        return new Reading(a.getTempF());\n    }\n    return new Reading(b.getTempF());\n}\nIII.\npublic Reading chooseWarmer(Reading a, Reading b)\n{\n    a.adjust(2.5);\n    if (a.getTempF() >= b.getTempF())\n    {\n        return a;\n    }\n    return b;\n}\nIV.\npublic Reading chooseWarmer(Reading a, Reading b)\n{\n    if (a.tempF >= b.tempF)\n    {\n        return a;\n    }\n    return b;\n}\nV.\npublic Reading chooseWarmer(Reading a, Reading b)\n{\n    b.adjust(1.0);\n    if (a.getTempF() >= b.getTempF())\n    {\n        return a;\n    }\n    return b;\n}\nWhich of the five implementations both compile successfully and leave both a and b completely unmodified?", "choices": ["I only", "I, II, and III only", "I, III, and V only", "I and II only"], "answer": 3, "explanation": "I compiles and never calls a mutator on a or b, only reading values through getTempF() and returning one of the original references. II also compiles and never mutates either parameter; it happens to return a brand-new Reading object rather than an existing one, but it still leaves a and b unmodified. III compiles but calls a.adjust(2.5), a mutator, on parameter a, which genuinely changes a's temperature and permanently alters the caller's object, clearly violating the requirement that a be left unmodified. IV does not compile, since it is defined outside the Reading class and directly accesses the private field tempF (3.6.A.3). V compiles but calls b.adjust(1.0), genuinely mutating b's temperature and permanently changing the caller's object, clearly violating the requirement. Only I and II both compile and leave both parameters completely unmodified (3.6.A.1, 3.6.A.2)."},
  {"id": "3.6-complex-11", "course": "csa", "topic": "3.6", "tier": "complex", "lo": "3.6.A.1", "prompt": "Three classes are defined as follows.\npublic class Battery\n{\n    private int charge;\n\n    public Battery(int startCharge)\n    {\n        charge = startCharge;\n    }\n\n    public void use(int amount)\n    {\n        charge = charge - amount;\n    }\n\n    public int getCharge()\n    {\n        return charge;\n    }\n}\npublic class Flashlight\n{\n    private Battery cell;\n\n    public Flashlight(Battery startCell)\n    {\n        cell = startCell;\n    }\n\n    public Battery getCell()\n    {\n        return cell;\n    }\n\n    public void swapCell(Battery newCell)\n    {\n        cell = newCell;\n    }\n}\npublic class CampingTrip\n{\n    public void useLight(Flashlight light, int amount)\n    {\n        Battery b = light.getCell();\n        b.use(amount);\n    }\n}\nThe following code segment appears in a separate class.\nBattery cellA = new Battery(80);\nBattery cellB = new Battery(50);\nFlashlight torch = new Flashlight(cellA);\nCampingTrip trip = new CampingTrip();\ntrip.useLight(torch, 20);\ntorch.swapCell(cellB);\ntrip.useLight(torch, 10);\nConsider the following statements after this code executes.\nI. cellA.getCharge() equals 60.\nII. cellB.getCharge() equals 40.\nIII. torch.getCell() and cellA refer to the same object.\nIV. torch.getCell() and cellB refer to the same object.\nV. cellA and cellB refer to the same Battery object.\nWhich statements are true?", "choices": ["I, II, and IV only", "I, III, and V only", "II, III, and IV only", "I, II, III, and IV only"], "answer": 0, "explanation": "The first useLight call obtains b as an alias for cellA, since torch's cell field still refers to cellA at that point, and calls use(20), reducing cellA's charge from 80 to 60, making I true. torch.swapCell(cellB) then reassigns torch's cell field to refer to cellB instead, disconnecting cellA from torch entirely. The second useLight call now obtains b as an alias for cellB, and use(10) reduces cellB's charge from 50 to 40, making II true. Because torch.getCell() now returns cellB's reference rather than cellA's, III is false and IV is true, and cellA and cellB were always two distinct Battery objects from the moment they were constructed, making V false (3.6.A.1, 3.6.A.2). Only I, II, and IV are true."},
  {"id": "3.6-complex-12", "course": "csa", "topic": "3.6", "tier": "complex", "lo": "3.6.A.3", "prompt": "Two classes are defined as follows.\npublic class Coordinate\n{\n    private int xPos;\n    private int yPos;\n\n    public Coordinate(int startX, int startY)\n    {\n        xPos = startX;\n        yPos = startY;\n    }\n\n    public Coordinate(Coordinate source)\n    {\n        xPos = source.xPos;\n        yPos = source.yPos;\n    }\n\n    public int getX()\n    {\n        return xPos;\n    }\n\n    public int getY()\n    {\n        return yPos;\n    }\n}\npublic class CoordinateFactory\n{\n    public Coordinate duplicate(Coordinate source)\n    {\n        Coordinate result = new Coordinate(source.xPos, source.yPos);\n        return result;\n    }\n}\nWhich statement correctly evaluates these two classes?", "choices": ["Both compile, because any constructor is automatically allowed to access private fields of its own parameters, regardless of which class it is defined in", "Coordinate's copy constructor compiles because it is defined inside Coordinate and may access source's private fields directly, but CoordinateFactory's duplicate method does not compile because it accesses source.xPos and source.yPos from a different class", "Neither compiles, because a class cannot have two constructors with different parameter lists", "Coordinate's copy constructor does not compile because source is a parameter, not the object being constructed, so its private fields are unreachable, but CoordinateFactory's duplicate method compiles fine"], "answer": 1, "explanation": "Coordinate's second constructor is defined inside the Coordinate class itself, so it may directly access the private xPos and yPos fields of any Coordinate object, including the parameter source, since private access is restricted by class rather than by which specific object is involved (3.6.A.3). CoordinateFactory, however, is a separate class, so its duplicate method's direct access to source.xPos and source.yPos is illegal and fails to compile; it would need to call public accessors like getX() and getY() instead. Access is never automatically granted to any constructor regardless of class, Java fully permits constructor overloading with different parameter lists, and a parameter of the same class type is exactly the case where private access remains legal."},
  {"id": "3.6-complex-13", "course": "csa", "topic": "3.6", "tier": "complex", "lo": "3.6.A.2", "prompt": "Three classes are defined as follows.\npublic class Wick\n{\n    private double lengthCm;\n\n    public Wick(double startLength)\n    {\n        lengthCm = startLength;\n    }\n\n    public void burn(double amount)\n    {\n        lengthCm = lengthCm - amount;\n    }\n\n    public double getLength()\n    {\n        return lengthCm;\n    }\n}\npublic class Candle\n{\n    private Wick core;\n\n    public Candle(Wick startCore)\n    {\n        core = startCore;\n    }\n\n    public Wick getCore()\n    {\n        return core;\n    }\n}\npublic class GiftBox\n{\n    private Candle item;\n\n    public GiftBox(Candle startItem)\n    {\n        item = startItem;\n    }\n\n    public Candle getItem()\n    {\n        return item;\n    }\n}\nThe following code segment appears in a separate class.\nWick fuse = new Wick(10.0);\nCandle taper = new Candle(fuse);\nGiftBox box = new GiftBox(taper);\nbox.getItem().getCore().burn(3.0);\nConsider the following statements after this code executes.\nI. fuse.getLength() equals 7.0.\nII. box.getItem().getCore() and fuse refer to the same Wick object.\nIII. A new Wick object was created when burn(3.0) was called.\nWhich statements are true?", "choices": ["I only", "II and III only", "I and II only", "I, II, and III"], "answer": 2, "explanation": "Every getter in this chain, getItem() and getCore(), returns the exact reference stored in its private field without ever creating a new object; box.getItem() returns the same reference as taper, and taper's getCore() call returns the same reference as fuse. Calling burn(3.0) at the end of this chain therefore mutates fuse directly, reducing its length from 10.0 to 7.0, making I true (3.6.A.2, 3.6.A.1). Because no getter along the chain constructs a new object, box.getItem().getCore() and fuse are aliases for the identical Wick object, making II true. No new Wick object is ever created anywhere in this code, so III is false."},
  {"id": "3.6-complex-14", "course": "csa", "topic": "3.6", "tier": "complex", "lo": "3.6.A.2", "prompt": "Two classes are defined as follows.\npublic class Ticket\n{\n    private int seatNumber;\n\n    public Ticket(int startSeat)\n    {\n        seatNumber = startSeat;\n    }\n\n    public int getSeatNumber()\n    {\n        return seatNumber;\n    }\n}\npublic class TicketBooth\n{\n    private Ticket bestTicket;\n\n    public TicketBooth(Ticket startTicket)\n    {\n        bestTicket = startTicket;\n    }\n\n    public Ticket holdBest()\n    {\n        return bestTicket;\n    }\n\n    public void updateBest(Ticket newBest)\n    {\n        bestTicket = newBest;\n    }\n}\nThe following code segment appears in a separate class.\nTicket frontRow = new Ticket(1);\nTicket balcony = new Ticket(99);\nTicketBooth booth = new TicketBooth(frontRow);\nTicket firstCall = booth.holdBest();\nbooth.updateBest(balcony);\nTicket secondCall = booth.holdBest();\nWhich of the following is true about firstCall and secondCall?", "choices": ["firstCall and secondCall both refer to the same object as frontRow, since bestTicket was only ever set once, in the constructor", "firstCall and secondCall both refer to the same object as balcony, since updateBest permanently changes what all earlier returned references point to", "The code does not compile, since holdBest() is called twice on the same booth object", "firstCall refers to the same object as frontRow, and secondCall refers to the same object as balcony, because holdBest() returns whatever reference bestTicket currently holds at the moment it is called"], "answer": 3, "explanation": "holdBest() simply returns whatever reference is currently stored in bestTicket at the moment it is called; firstCall is obtained before updateBest(balcony) runs, so it holds the reference to frontRow. updateBest(balcony) then reassigns bestTicket to refer to balcony instead, and secondCall is obtained after that reassignment, so it holds the reference to balcony (3.6.A.2). Reassigning bestTicket has no effect on the object firstCall already refers to, since firstCall's value was fixed the moment holdBest() first returned, so the claim that both calls return the same object misunderstands that each call captures the current reference at that specific moment. A method may be called on the same object as many times as needed, so the code compiles without issue."},
  {"id": "3.6-complex-15", "course": "csa", "topic": "3.6", "tier": "complex", "lo": "3.6.A.1", "prompt": "Two classes are defined as follows.\npublic class Exhibit\n{\n    private String title;\n    private int visitorCount;\n\n    public Exhibit(String startTitle, int startCount)\n    {\n        title = startTitle;\n        visitorCount = startCount;\n    }\n\n    public String getTitle()\n    {\n        return title;\n    }\n\n    public int getVisitorCount()\n    {\n        return visitorCount;\n    }\n\n    public void addVisitors(int amount)\n    {\n        visitorCount = visitorCount + amount;\n    }\n}\npublic class Curator\n{\n    private Exhibit featured;\n\n    public Curator(Exhibit startFeatured)\n    {\n        featured = startFeatured;\n    }\n\n    public Exhibit getFeatured()\n    {\n        return featured;\n    }\n\n    public void promote(Exhibit e, int amount)\n    {\n        e.addVisitors(amount);\n    }\n\n    public Exhibit createReplica(Exhibit source)\n    {\n        Exhibit replica = new Exhibit(source.getTitle(), 0);\n        return replica;\n    }\n}\nSuppose the following method is proposed to be added to the Curator class.\npublic boolean sameTitle(Exhibit other)\n{\n    return featured.title.equals(other.title);\n}\nConsider the following statements about this code.\nI. The call featured.title.equals(other.title) inside sameTitle compiles successfully, because sameTitle would be defined inside Curator, not Exhibit.\nII. Calling promote(e, amount) mutates the actual Exhibit object passed in as e, since e is a copy of the caller's reference.\nIII. createReplica always returns a reference to the same object as source.\nIV. getFeatured() returns the same reference stored in the private field featured, not a copy of the Exhibit object.\nV. If two different Curator objects are constructed with the same Exhibit object, calling promote through either Curator's featured Exhibit would be impossible, since each Curator has its own separate copy of that Exhibit.\nWhich statements are true?", "choices": ["II and IV only", "I and IV only", "II, III, and IV only", "I, II, and V only"], "answer": 0, "explanation": "I is false: even though sameTitle would be defined inside Curator, Curator is still a class other than Exhibit, so its direct access to featured.title and other.title, both private fields of Exhibit, would cause a compile error; being defined in a different class is exactly why it fails, not why it succeeds (3.6.A.3). II is true: promote(e, amount) receives e as a copy of the caller's reference, and calling the mutator addVisitors through e changes the same Exhibit object the caller referred to (3.6.A.1). III is false: createReplica constructs a brand-new Exhibit object with new every time it runs and returns a reference to that new object, never the same reference as source (3.6.A.2). IV is true: getFeatured() simply returns the reference already stored in featured, not a newly copied object (3.6.A.2). V is false: the Curator constructor merely assigns featured = startFeatured, copying the reference rather than creating an independent Exhibit, so two Curator objects built from the same Exhibit would in fact share, and could mutate, that one object through either Curator, not be prevented from doing so. Only II and IV are true."},
  {"id": "3.7-basic-01", "course": "csa", "topic": "3.7", "tier": "basic", "lo": "3.7.B.1", "prompt": "A class variable, also called a static variable, is declared using which keyword before the variable's type?", "choices": ["static", "final", "private", "void"], "answer": 0, "explanation": "The keyword static designates a class variable, meaning all objects of the class share a single copy of its value (3.7.B.1). final only prevents a variable from being reassigned after it is set; private only restricts which classes may access it; void is a method return type, not a variable modifier."},
  {"id": "3.7-basic-02", "course": "csa", "topic": "3.7", "tier": "basic", "lo": "3.7.B.1", "prompt": "public class ScoreBoard\n{\n    private static int gamesPlayed = 0;\n    public ScoreBoard()\n    {\n        gamesPlayed++;\n    }\n}\nSuppose three ScoreBoard objects are created, one after another, using the no-argument constructor. What is the value of gamesPlayed after all three objects have been created?", "choices": ["0", "3", "1", "9"], "answer": 1, "explanation": "gamesPlayed is a static variable shared by all ScoreBoard objects, so each constructor call increments the same single copy; after three constructor calls its value is 3 (3.7.B.1). 0 would be true only if gamesPlayed were never incremented, 1 would be true only if each object kept its own separate copy the way an instance variable would, and 9 confuses repeated incrementing with multiplication."},
  {"id": "3.7-basic-03", "course": "csa", "topic": "3.7", "tier": "basic", "lo": "3.7.A.1", "prompt": "public class Robot\n{\n    private int batteryLevel;\n    public static void drain()\n    {\n        batteryLevel = batteryLevel - 10;\n    }\n}\nWhy does this class fail to compile?", "choices": ["batteryLevel is declared private, so it can never be used inside the class", "The method drain has no return type, which is required for static methods", "A static method cannot access or modify an instance variable like batteryLevel without being given an instance of the class", "The class Robot needs a constructor before any method can be written"], "answer": 2, "explanation": "A class method (declared static) cannot access or change an instance variable such as batteryLevel unless an instance of the class is passed to it as a parameter, which is exactly why this fails to compile (3.7.A.1). batteryLevel being private is not the problem, since code inside the same class can normally access its own private members; static methods are not required to return a value, since void is a perfectly valid return type; and Java does not require a class to declare an explicit constructor before adding other methods."},
  {"id": "3.7-basic-04", "course": "csa", "topic": "3.7", "tier": "basic", "lo": "3.7.A.2", "prompt": "public class Inventory\n{\n    private static int itemCount = 0;\n    public static void addItem()\n    {\n        itemCount++;\n    }\n}\nWhich statement about the addItem method is true?", "choices": ["addItem cannot compile because static methods cannot modify any variables", "addItem can only be called if an Inventory object has already been created", "addItem modifies itemCount, but only for the specific Inventory object that calls it", "addItem can access and modify itemCount because itemCount is a class variable, not an instance variable"], "answer": 3, "explanation": "Class methods can freely access and change class variables, and can call other class methods, which is exactly what addItem does with itemCount (3.7.A.2). The method compiles without issue, static methods can be called without any object ever existing, and itemCount is a single shared class variable, not a separate copy per object."},
  {"id": "3.7-basic-05", "course": "csa", "topic": "3.7", "tier": "basic", "lo": "3.7.B.2", "prompt": "public class Config\n{\n    public static int maxUsers = 100;\n}\nWhich statement, written in a class other than Config, correctly reads the value of maxUsers?", "choices": ["int m = Config.maxUsers;", "int m = maxUsers;", "int m = maxUsers.Config;", "int m = new maxUsers();"], "answer": 0, "explanation": "Since maxUsers is public and static, it belongs to the class itself and is accessed from outside using the class name and the dot operator, Config.maxUsers (3.7.B.2). Writing maxUsers alone does not compile outside the class since it is not in scope there, reversing the class name and variable name is invalid syntax, and maxUsers is a variable, not a class that can be instantiated with new."},
  {"id": "3.7-basic-06", "course": "csa", "topic": "3.7", "tier": "basic", "lo": "3.7.B.3", "prompt": "A programmer declares a class variable as follows.\npublic static final int MAX_SCORE = 100;\nWhat is the effect of the keyword final in this declaration?", "choices": ["It means MAX_SCORE is shared by all objects of the class", "It means the value of MAX_SCORE cannot be changed after it is initialized", "It means MAX_SCORE can only be accessed from inside the class", "It means MAX_SCORE must be recalculated every time the class is used"], "answer": 1, "explanation": "final means a variable's value cannot be modified once it has been assigned (3.7.B.3). static, not final, is what makes MAX_SCORE shared by all objects; public, not final, controls access from outside the class; and final has no effect on recalculation, since nothing about it forces the value to be recomputed."},
  {"id": "3.7-basic-07", "course": "csa", "topic": "3.7", "tier": "basic", "lo": "3.7.B.1", "prompt": "Which of the following best explains why a class variable is different from an instance variable?", "choices": ["A class variable can only be declared private, while an instance variable can be public or private", "A class variable must be initialized inside a constructor, while an instance variable cannot be", "Every object of the class shares one single copy of a class variable, while each object has its own separate copy of an instance variable", "A class variable can only store String values, while an instance variable can store any data type"], "answer": 2, "explanation": "The defining difference is that all objects of a class share a single copy of a class variable, whereas each object keeps its own independent copy of an instance variable (3.7.B.1). Access modifiers, initialization location, and data type have no bearing on whether a variable is class-level or instance-level."},
  {"id": "3.7-basic-08", "course": "csa", "topic": "3.7", "tier": "basic", "lo": "3.7.A.1", "prompt": "public class Thermostat\n{\n    private double temperature;\n    public static double getTemperature()\n    {\n        return temperature;\n    }\n}\nWhy does this class fail to compile?", "choices": ["getTemperature does not have a parameter", "temperature is not initialized in a constructor", "double is not an allowed return type for a static method", "getTemperature is static, so it cannot return the value of the instance variable temperature without being passed a Thermostat instance"], "answer": 3, "explanation": "A static method cannot access an instance variable directly, since instance variables belong to individual objects rather than to the class as a whole, unless an instance is passed in as a parameter (3.7.A.1). A method's parameter list is unrelated to this restriction, an uninitialized double simply defaults to 0.0 rather than causing a compile error, and static methods may return any data type, including double."},
  {"id": "3.7-basic-09", "course": "csa", "topic": "3.7", "tier": "basic", "lo": "3.7.A.2", "prompt": "public class MathHelper\n{\n    private static int callCount = 0;\n    public static int square(int n)\n    {\n        callCount++;\n        return n * n;\n    }\n}\nWhich statement correctly describes the square method?", "choices": ["square is a valid class method because it only accesses and modifies the class variable callCount, never an instance variable", "square cannot compile because static methods cannot use a return statement", "square cannot compile because it takes a parameter", "square is invalid because class methods cannot call other class methods"], "answer": 0, "explanation": "square only touches callCount, a class variable, which class methods are always permitted to read and modify (3.7.A.2). Static methods can absolutely return values and accept parameters, and nothing in square calls another method at all, so the last distractor misdescribes the code entirely."},
  {"id": "3.7-basic-10", "course": "csa", "topic": "3.7", "tier": "basic", "lo": "3.7.B.2", "prompt": "public class Library\n{\n    private static int totalBooks = 500;\n    public static int getTotalBooks()\n    {\n        return totalBooks;\n    }\n}\nWhich statement, written in a class other than Library, correctly obtains the value of totalBooks?", "choices": ["int b = totalBooks;", "int b = Library.getTotalBooks();", "int b = Library.totalBooks;", "int b = getTotalBooks();"], "answer": 1, "explanation": "Because totalBooks is private, outside classes must call the public static method through the class name, Library.getTotalBooks() (3.7.B.2). Referring to totalBooks directly, whether unqualified or through the class name, fails to compile since it is private, and calling getTotalBooks() without qualifying it with the class name also fails outside the class."},
  {"id": "3.7-basic-11", "course": "csa", "topic": "3.7", "tier": "basic", "lo": "3.7.B.1", "prompt": "public class Ticket\n{\n    private static int nextNumber = 1;\n    private int number;\n    public Ticket()\n    {\n        number = nextNumber;\n        nextNumber++;\n    }\n}\nTicket t1 = new Ticket();\nTicket t2 = new Ticket();\nTicket t3 = new Ticket();\nWhat is the value of t2's instance variable number after these three objects are created, in order?", "choices": ["1", "3", "2", "0"], "answer": 2, "explanation": "t1 receives number 1 and increments the shared nextNumber to 2; t2 then receives number 2 and increments nextNumber to 3 (3.7.B.1). 1 would be t1's value, not t2's; 3 would be t3's value; and 0 never occurs since nextNumber starts at 1."},
  {"id": "3.7-basic-12", "course": "csa", "topic": "3.7", "tier": "basic", "lo": "3.7.B.3", "prompt": "A class declares the following variable.\nprivate static final double TAX_RATE = 0.08;\nWhich of the following statements, if placed inside a method of the same class, would cause a compile-time error?", "choices": ["double t = TAX_RATE * 100;", "System.out.println(TAX_RATE);", "double price = 20.0 * TAX_RATE;", "TAX_RATE = 0.10;"], "answer": 3, "explanation": "Because TAX_RATE is declared final, attempting to assign it a new value after initialization causes a compile-time error (3.7.B.3). Reading TAX_RATE's value in an expression, printing it, or using it in a calculation are all completely legal, since final only blocks reassignment, not use."},
  {"id": "3.7-basic-13", "course": "csa", "topic": "3.7", "tier": "basic", "lo": "3.7.A.1", "prompt": "Which of the following best describes a restriction on class (static) methods?", "choices": ["A class method cannot access or change an instance variable, or call an instance method, unless it is given an object of the class as a parameter", "A class method cannot access or change a class variable under any circumstances", "A class method cannot be called unless at least one object of the class has been created", "A class method cannot accept parameters of a user-defined class type"], "answer": 0, "explanation": "This restriction is the core rule of 3.7.A.1: a static method has no implicit access to instance data because it does not run in the context of any particular object. Class methods can freely use class variables (3.7.A.2), can be called with zero objects ever created, and can accept parameters of any type, including user-defined classes."},
  {"id": "3.7-basic-14", "course": "csa", "topic": "3.7", "tier": "basic", "lo": "3.7.B.1", "prompt": "public class Team\n{\n    private static String mascot = \"Wolves\";\n    public static void setMascot(String newMascot)\n    {\n        mascot = newMascot;\n    }\n}\nTeam.setMascot(\"Hawks\");\nWhich statement is true about every Team object created after this line executes?", "choices": ["Each Team object will have its own mascot value, either \"Wolves\" or \"Hawks\"", "Every Team object will see the same shared value, \"Hawks\", for mascot", "The change to mascot has no effect on any Team object", "Only the next Team object created will see \"Hawks\"; later objects will see \"Wolves\" again"], "answer": 1, "explanation": "Because mascot is a class variable, there is only ever one shared copy, so once it is changed to \"Hawks\" every object, past or future, reflects that same shared value (3.7.B.1). It is not possible for different objects to see different values, for the change to have no effect, or for the value to revert on its own."},
  {"id": "3.7-basic-15", "course": "csa", "topic": "3.7", "tier": "basic", "lo": "3.7.A.2", "prompt": "public class Logger\n{\n    private static int messageCount = 0;\n    public static void logMessage()\n    {\n        messageCount++;\n    }\n    public static int getMessageCount()\n    {\n        return messageCount;\n    }\n}\nWhich statement about the Logger class is true?", "choices": ["getMessageCount cannot compile because it calls logMessage indirectly", "logMessage and getMessageCount cannot both be static in the same class", "Both logMessage and getMessageCount are valid class methods because they only access and modify the class variable messageCount", "logMessage is invalid because it does not return a value"], "answer": 2, "explanation": "Both methods only interact with messageCount, a class variable, which class methods are always allowed to access and modify, and class methods may freely call other class methods as well (3.7.A.2). A class can contain any number of static methods, methods are not required to return a value since void is valid, and nothing here involves an indirect call issue."},
  {"id": "3.7-intermediate-01", "course": "csa", "topic": "3.7", "tier": "intermediate", "lo": "3.7.B.1", "prompt": "public class Account\n{\n    private static double bankTotal = 0.0;\n    private double balance;\n    public Account(double amount)\n    {\n        balance = amount;\n        bankTotal = bankTotal + amount;\n    }\n    public double getBalance()\n    {\n        return balance;\n    }\n}\nAccount a1 = new Account(200.0);\nAccount a2 = new Account(150.0);\nWhat is the value of bankTotal after these two lines execute?", "choices": ["200.0", "350.0", "150.0", "0.0"], "answer": 1, "explanation": "bankTotal is a class variable shared by all Account objects, so each constructor call adds to the same running total: 0.0 + 200.0 + 150.0 = 350.0 (3.7.B.1). 200.0 and 150.0 are each individual deposit amounts rather than the running total, and 0.0 would only be correct if bankTotal were never updated."},
  {"id": "3.7-intermediate-02", "course": "csa", "topic": "3.7", "tier": "intermediate", "lo": "3.7.A.1", "prompt": "public class Vehicle\n{\n    private int mileage;\n    private static int vehicleCount = 0;\n    public Vehicle(int startMileage)\n    {\n        mileage = startMileage;\n        vehicleCount++;\n    }\n    public static void addMileage(int miles)\n    {\n        mileage = mileage + miles;\n    }\n}\nWhich change would allow the class to compile without changing the intent that addMileage adds miles to a specific Vehicle object's mileage?", "choices": ["Change vehicleCount to an instance variable", "Add a return statement to addMileage", "Remove the static keyword from addMileage, since it must operate on a particular object's mileage", "Change mileage to a static variable"], "answer": 2, "explanation": "Since addMileage is meant to update one specific object's mileage, an instance variable, it must be an instance method rather than static, because a static method cannot touch instance variables without receiving an object as a parameter (3.7.A.1). Making vehicleCount an instance variable would break the shared vehicle count, no return statement is required for a void method, and turning mileage into a static variable would make it shared by all vehicles, changing the intended meaning."},
  {"id": "3.7-intermediate-03", "course": "csa", "topic": "3.7", "tier": "intermediate", "lo": "3.7.B.2", "prompt": "public class Warehouse\n{\n    public static int capacity = 1000;\n    private int itemsStored;\n    public Warehouse()\n    {\n        itemsStored = 0;\n    }\n}\nThe following code segment appears in a class other than Warehouse.\nWarehouse w = new Warehouse();\nSystem.out.println(Warehouse.capacity);\nWhat is printed as a result of executing this code segment?", "choices": ["This code does not compile because capacity must be accessed through the object w", "0", "This code does not compile because capacity is not initialized in the constructor", "1000"], "answer": 3, "explanation": "capacity is a public static variable, so it is correctly accessed from outside the class using the class name and dot operator, Warehouse.capacity, which prints its initialized value, 1000 (3.7.B.2). The code compiles fine as written, capacity does not need to be set in the constructor since it already has an initial value, and 0 confuses capacity with the unrelated instance variable itemsStored."},
  {"id": "3.7-intermediate-04", "course": "csa", "topic": "3.7", "tier": "intermediate", "lo": "3.7.B.1", "prompt": "public class Survey\n{\n    private static int responseCount = 0;\n    private String answer;\n    public Survey(String response)\n    {\n        answer = response;\n        responseCount++;\n    }\n    public static int getResponseCount()\n    {\n        return responseCount;\n    }\n}\nSurvey s1 = new Survey(\"yes\");\nSurvey s2 = new Survey(\"no\");\nSurvey s3 = new Survey(\"yes\");\nSystem.out.println(Survey.getResponseCount());\nWhat is printed?", "choices": ["3", "1", "0", "2"], "answer": 0, "explanation": "responseCount is a class variable incremented once in every constructor call, so after three Survey objects are created, its single shared value is 3 (3.7.B.1). 1 would be true only if each object kept a separate copy that reset, 0 would be true only if the increment never executed, and 2 undercounts one of the three constructor calls."},
  {"id": "3.7-intermediate-05", "course": "csa", "topic": "3.7", "tier": "intermediate", "lo": "3.7.A.2", "prompt": "public class Registry\n{\n    private static int entries = 0;\n    public static void addEntry()\n    {\n        entries++;\n        logChange();\n    }\n    private static void logChange()\n    {\n        System.out.println(\"Entries: \" + entries);\n    }\n}\nRegistry.addEntry();\nRegistry.addEntry();\nWhat is printed as a result of executing these two lines?", "choices": ["Entries: 1", "Entries: 1\nEntries: 2", "Entries: 0\nEntries: 1", "Entries: 2"], "answer": 1, "explanation": "Each call to addEntry increments the shared class variable entries and then calls the class method logChange, which prints its current value, so the two calls print \"Entries: 1\" followed by \"Entries: 2\" (3.7.A.2). Printing only one line ignores that addEntry runs twice, and starting from \"Entries: 0\" ignores that entries is incremented before logChange is called each time."},
  {"id": "3.7-intermediate-06", "course": "csa", "topic": "3.7", "tier": "intermediate", "lo": "3.7.B.3", "prompt": "public class Circle\n{\n    public static final double PI_APPROX = 3.14;\n    private double radius;\n    public Circle(double r)\n    {\n        radius = r;\n    }\n    public double getArea()\n    {\n        return PI_APPROX * radius * radius;\n    }\n}\nWhich statement about PI_APPROX is true?", "choices": ["PI_APPROX has a different value for each Circle object", "PI_APPROX cannot be used inside getArea because it is static and getArea is not", "PI_APPROX is a shared, unchangeable value that every Circle object uses in its area calculation", "PI_APPROX must be passed as a parameter to getArea in order to be used"], "answer": 2, "explanation": "PI_APPROX is declared static, so it is shared by all Circle objects, and final, so its value cannot be reassigned once set, making it a fixed constant every object relies on (3.7.B.1, 3.7.B.3). An instance method can freely reference a class variable without it being passed as a parameter, and static variables would only differ across objects if they were instance variables instead, which PI_APPROX is not."},
  {"id": "3.7-intermediate-07", "course": "csa", "topic": "3.7", "tier": "intermediate", "lo": "3.7.A.1", "prompt": "public class Employee\n{\n    private double salary;\n    private static double totalPayroll = 0.0;\n    public Employee(double s)\n    {\n        salary = s;\n        totalPayroll = totalPayroll + s;\n    }\n    public static double raiseSalary(double amount)\n    {\n        salary = salary + amount;\n        return salary;\n    }\n}\nWhy does this class fail to compile?", "choices": ["totalPayroll is never declared final", "The constructor modifies totalPayroll, which is not allowed inside a constructor", "raiseSalary does not take an Employee parameter, so it has no way to know which object created it", "raiseSalary is static, so it cannot access or change the instance variable salary directly"], "answer": 3, "explanation": "raiseSalary is declared static, but it tries to read and modify salary, an instance variable, which is exactly the restriction described in 3.7.A.1: static methods cannot touch instance data without being passed an instance. final has nothing to do with this error, constructors are allowed to update class variables freely, and the real issue is not merely a missing parameter but that the method is static in the first place."},
  {"id": "3.7-intermediate-08", "course": "csa", "topic": "3.7", "tier": "intermediate", "lo": "3.7.B.1", "prompt": "public class CodeChecker\n{\n    private String label;\n    private static String key = \"A\";\n    public CodeChecker(String l)\n    {\n        label = l;\n    }\n    public static void changeKey(String newKey)\n    {\n        key = newKey;\n    }\n    public int locate()\n    {\n        return label.indexOf(key);\n    }\n}\nCodeChecker c1 = new CodeChecker(\"BANANA\");\nCodeChecker c2 = new CodeChecker(\"ABACUS\");\nint loc1 = c1.locate();\nCodeChecker.changeKey(\"C\");\nint loc2 = c2.locate();\nSystem.out.println(loc1 + \" \" + loc2);\nWhat is printed?", "choices": ["1 3", "1 1", "0 3", "0 0"], "answer": 0, "explanation": "key starts as \"A\", so c1.locate() searches for \"A\" in \"BANANA\" and finds it at index 1; key is then changed to \"C\" for every CodeChecker object since it is a shared class variable, so c2.locate() searches for \"C\" in \"ABACUS\" and finds it at index 3, printing \"1 3\" (3.7.B.1). The other choices assume key does not update, that the search starts from \"C\" for both calls, or that neither letter is found."},
  {"id": "3.7-intermediate-09", "course": "csa", "topic": "3.7", "tier": "intermediate", "lo": "3.7.A.2", "prompt": "public class Fleet\n{\n    private static int totalTrucks = 0;\n    private static int totalCars = 0;\n    public static void addTruck()\n    {\n        totalTrucks++;\n    }\n    public static void addCar()\n    {\n        totalCars++;\n    }\n    public static int totalVehicles()\n    {\n        return totalTrucks + totalCars;\n    }\n}\nFleet.addTruck();\nFleet.addTruck();\nFleet.addCar();\nSystem.out.println(Fleet.totalVehicles());\nWhat is printed?", "choices": ["2", "3", "1", "0"], "answer": 1, "explanation": "addTruck is called twice, making totalTrucks equal to 2, and addCar is called once, making totalCars equal to 1; totalVehicles adds these two shared class variables together and returns 3 (3.7.A.2). 2 counts only the trucks, 1 counts only the car, and 0 would only occur if none of the class methods executed."},
  {"id": "3.7-intermediate-10", "course": "csa", "topic": "3.7", "tier": "intermediate", "lo": "3.7.B.2", "prompt": "A student writes the following two classes.\npublic class Settings\n{\n    public static boolean soundOn = true;\n}\npublic class MainApp\n{\n    public static void main(String[] args)\n    {\n        System.out.println(Settings.soundOn);\n        Settings.soundOn = false;\n        System.out.println(Settings.soundOn);\n    }\n}\nWhat is printed as a result of running MainApp?", "choices": ["true\ntrue", "false\nfalse", "true\nfalse", "This code does not compile because soundOn must belong to an object, not the class"], "answer": 2, "explanation": "soundOn is public and static, so MainApp may read and reassign it directly through Settings.soundOn; it prints true first, then is changed to false and printed again (3.7.B.2). The code compiles and runs correctly, so it does not print true twice, print false twice, or fail to compile."},
  {"id": "3.7-intermediate-11", "course": "csa", "topic": "3.7", "tier": "intermediate", "lo": "3.7.B.1", "prompt": "public class Leaderboard\n{\n    private static int highScore = 0;\n    private int score;\n    public Leaderboard(int s)\n    {\n        score = s;\n        if (score > highScore)\n        {\n            highScore = score;\n        }\n    }\n}\nLeaderboard p1 = new Leaderboard(50);\nLeaderboard p2 = new Leaderboard(30);\nLeaderboard p3 = new Leaderboard(75);\nWhat is the final value of highScore after all three objects are created?", "choices": ["50", "30", "0", "75"], "answer": 3, "explanation": "highScore starts at 0, updates to 50 when p1 is created since 50 > 0, stays 50 when p2 is created since 30 is not greater than 50, and updates to 75 when p3 is created since 75 > 50, leaving a final shared value of 75 (3.7.B.1). 50 and 30 are earlier or non-qualifying values, and 0 ignores that any update happened at all."},
  {"id": "3.7-intermediate-12", "course": "csa", "topic": "3.7", "tier": "intermediate", "lo": "3.7.A.1", "prompt": "A programmer wants to add a method to the following class that reports how many Coupon objects have been created so far.\npublic class Coupon\n{\n    private static int couponsCreated = 0;\n    private String code;\n    public Coupon(String c)\n    {\n        code = c;\n        couponsCreated++;\n    }\n}\nThe method will be called using Coupon.getCouponsCreated(), without creating any Coupon object first. Consider these candidate implementations.\nI.\npublic int getCouponsCreated()\n{\n    return couponsCreated;\n}\nII.\npublic static int getCouponsCreated()\n{\n    return couponsCreated;\n}\nIII.\npublic static int getCouponsCreated()\n{\n    return code.length();\n}\nWhich implementation(s) allow the call Coupon.getCouponsCreated() to compile successfully?", "choices": ["II only", "I only", "I and II only", "II and III only"], "answer": 0, "explanation": "Since the method is called using the class name without any object, it must be declared static, ruling out I; II correctly returns the class variable couponsCreated and compiles, while III fails because a static method cannot access the instance variable code (3.7.A.1, 3.7.A.2). Therefore only II compiles successfully."},
  {"id": "3.7-intermediate-13", "course": "csa", "topic": "3.7", "tier": "intermediate", "lo": "3.7.B.3", "prompt": "public class GameConstants\n{\n    public static final int MAX_LIVES = 3;\n    private int livesRemaining;\n    public GameConstants()\n    {\n        livesRemaining = MAX_LIVES;\n    }\n    public void loseLife()\n    {\n        livesRemaining--;\n    }\n}\nWhich statement is true about MAX_LIVES?", "choices": ["MAX_LIVES decreases each time loseLife is called", "MAX_LIVES always stays 3 for every GameConstants object, while livesRemaining can differ per object as loseLife is called", "MAX_LIVES cannot be used to initialize livesRemaining because it is static", "MAX_LIVES is recalculated every time a new GameConstants object is created"], "answer": 1, "explanation": "MAX_LIVES is both static and final, so it is a single shared constant that never changes, while livesRemaining is an instance variable that starts at MAX_LIVES for every object but decreases independently as loseLife is called (3.7.B.1, 3.7.B.3). loseLife only changes livesRemaining, not MAX_LIVES; a static class variable can be freely read inside a constructor; and final values are never recalculated, since they cannot be reassigned in the first place."},
  {"id": "3.7-intermediate-14", "course": "csa", "topic": "3.7", "tier": "intermediate", "lo": "3.7.A.2", "prompt": "public class TemperatureLog\n{\n    private static double totalReadings = 0.0;\n    private static int count = 0;\n    public static void addReading(double temp)\n    {\n        totalReadings = totalReadings + temp;\n        count++;\n    }\n    public static double getAverage()\n    {\n        return totalReadings / count;\n    }\n}\nTemperatureLog.addReading(70.0);\nTemperatureLog.addReading(80.0);\nSystem.out.println(TemperatureLog.getAverage());\nWhat is printed?", "choices": ["70.0", "150.0", "75.0", "80.0"], "answer": 2, "explanation": "Both calls to addReading update the shared class variables totalReadings (150.0) and count (2), so getAverage divides these class variables to correctly return 75.0 (3.7.A.2). 70.0 and 80.0 are only the individual readings, not the average, and 150.0 is the sum before it is divided by the count."},
  {"id": "3.7-intermediate-15", "course": "csa", "topic": "3.7", "tier": "intermediate", "lo": "3.7.B.2", "prompt": "public class School\n{\n    private static String districtName = \"Lincoln\";\n    public static String getDistrictName()\n    {\n        return districtName;\n    }\n    public static void setDistrictName(String name)\n    {\n        districtName = name;\n    }\n}\nThe following code segment appears in a class other than School.\nSchool.setDistrictName(\"Franklin\");\nSystem.out.println(School.getDistrictName());\nWhat is printed?", "choices": ["Lincoln", "This code does not compile because districtName is private", "null", "Franklin"], "answer": 3, "explanation": "setDistrictName and getDistrictName are public static methods, so they may be called from outside using School.methodName() even though districtName itself is private; setDistrictName changes the shared class variable to \"Franklin\", and getDistrictName then returns that updated value (3.7.B.2). The code compiles fine since only the private variable, not the public methods, is restricted, so the output is neither the original value, null, nor a compile error."},
  {"id": "3.7-complex-01", "course": "csa", "topic": "3.7", "tier": "complex", "lo": "3.7.B.1", "prompt": "public class DataPoint\n{\n    private String label;\n    private static int adjustment = 0;\n    public DataPoint(String l)\n    {\n        label = l;\n    }\n    public static void setAdjustment(int a)\n    {\n        adjustment = a;\n    }\n    public int score()\n    {\n        int base = label.length();\n        return base + adjustment;\n    }\n}\nDataPoint d1 = new DataPoint(\"cat\");\nDataPoint d2 = new DataPoint(\"elephant\");\nint s1 = d1.score();\nDataPoint.setAdjustment(5);\nint s2 = d2.score();\nDataPoint.setAdjustment(-2);\nDataPoint d3 = new DataPoint(\"ox\");\nint s3 = d3.score();\nSystem.out.println(s1 + \" \" + s2 + \" \" + s3);\nWhat is printed?", "choices": ["3 8 2", "3 13 2", "3 13 0", "8 13 0"], "answer": 2, "explanation": "s1 uses label \"cat\" (length 3) with adjustment still 0, giving 3. After setAdjustment(5), adjustment becomes 5 for every DataPoint object, so s2 uses \"elephant\" (length 8) plus 5, giving 13. After setAdjustment(-2), adjustment becomes -2, so the newly created d3's score uses \"ox\" (length 2) plus -2, giving 0, since adjustment is a class variable shared and updated for all objects regardless of when they were created (3.7.B.1). The distractors either ignore the first adjustment change, ignore the second adjustment change, or ignore the first score entirely."},
  {"id": "3.7-complex-02", "course": "csa", "topic": "3.7", "tier": "complex", "lo": "3.7.A.1", "prompt": "public class Vault\n{\n    private double contents;\n    private static double totalAcrossVaults = 0.0;\n    public Vault(double amount)\n    {\n        contents = amount;\n        totalAcrossVaults = totalAcrossVaults + amount;\n    }\n    public static void addFunds(double amount)\n    {\n        contents = contents + amount;\n        totalAcrossVaults = totalAcrossVaults + amount;\n    }\n}\nThe class does not compile as written. Which change corrects the error while preserving the intent that addFunds adds money to one specific Vault object's contents?", "choices": ["Change contents to a static variable, so addFunds can modify it directly", "Change totalAcrossVaults to an instance variable, so each Vault has its own copy", "Add a return statement to addFunds", "Remove the static keyword from addFunds, so it can access and modify the instance variable contents"], "answer": 3, "explanation": "Since addFunds needs to update one specific object's contents (an instance variable), it must be an instance method, not static, because a static method cannot access or change instance variables without an instance being passed to it (3.7.A.1). Making contents static would mean all vaults share one balance, contradicting the intent of tracking each vault separately; making totalAcrossVaults an instance variable would break the shared running total across vaults; and adding a return statement does not address the underlying static/instance access violation."},
  {"id": "3.7-complex-03", "course": "csa", "topic": "3.7", "tier": "complex", "lo": "3.7.B.1", "prompt": "public class Runner\n{\n    private static double fastestTime = 100.0;\n    private String name;\n    private double time;\n    public Runner(String n, double t)\n    {\n        name = n;\n        time = t;\n        if (time < fastestTime)\n        {\n            fastestTime = time;\n        }\n    }\n    public static double getFastestTime()\n    {\n        return fastestTime;\n    }\n}\nRunner r1 = new Runner(\"Ana\", 12.4);\nRunner r2 = new Runner(\"Ben\", 15.0);\nRunner r3 = new Runner(\"Cho\", 11.8);\nSystem.out.println(Runner.getFastestTime());\nWhat is printed?", "choices": ["11.8", "12.4", "15.0", "100.0"], "answer": 0, "explanation": "fastestTime starts at 100.0, drops to 12.4 when Ana's time qualifies, stays at 12.4 when Ben's slower time of 15.0 does not qualify, and drops again to 11.8 when Cho's faster time qualifies, leaving a final shared value of 11.8 across all Runner objects (3.7.B.1). 12.4 ignores the final update from Cho, 15.0 was never faster than the current record so it never became fastestTime, and 100.0 ignores that any update occurred."},
  {"id": "3.7-complex-04", "course": "csa", "topic": "3.7", "tier": "complex", "lo": "3.7.A.2", "prompt": "public class Statistics\n{\n    private static int sum = 0;\n    private static int count = 0;\n    private int lastValue;\n    public Statistics(int value)\n    {\n        lastValue = value;\n        sum = sum + value;\n        count++;\n    }\n}\nA programmer wants to add a static method to compute the average of all values recorded so far. Consider these candidate implementations.\nI.\npublic static double average()\n{\n    return sum / count;\n}\nII.\npublic static double average()\n{\n    return (double) sum / count;\n}\nIII.\npublic static double average()\n{\n    return (double) sum / lastValue;\n}\nWhich implementation compiles successfully AND correctly computes the average of all recorded values as a decimal value?", "choices": ["I only", "II only", "I and II only", "III only"], "answer": 1, "explanation": "II compiles and correctly computes the average as a decimal because it casts sum to double before dividing by count, both of which are class variables that a static method may freely access (3.7.A.2). I compiles but silently performs integer division since neither operand is cast to double before the division, discarding the decimal portion, and III does not compile because a static method cannot access the instance variable lastValue."},
  {"id": "3.7-complex-05", "course": "csa", "topic": "3.7", "tier": "complex", "lo": "3.7.B.3", "prompt": "public class Membership\n{\n    public static final int MAX_MEMBERS = 4;\n    private static int currentMembers = 0;\n    private String memberName;\n    public Membership(String name)\n    {\n        memberName = name;\n        if (currentMembers < MAX_MEMBERS)\n        {\n            currentMembers++;\n        }\n    }\n    public static int getCurrentMembers()\n    {\n        return currentMembers;\n    }\n}\nFive Membership objects are created, one after another, using five different names. What is the value of Membership.getCurrentMembers() after all five objects have been created?", "choices": ["5", "0", "4", "This code does not compile because MAX_MEMBERS is final"], "answer": 2, "explanation": "currentMembers increases by 1 for each of the first four objects created, since each time the shared value is still less than the constant MAX_MEMBERS (4), but the fifth object's constructor finds currentMembers already equal to 4, so the condition is false and currentMembers stays at 4 (3.7.B.1, 3.7.B.3). It is not 5, since the fifth call does not increment; it is not 0, since the value clearly did increase; and the code compiles fine, since final only prevents MAX_MEMBERS itself from being reassigned, and nothing in the class attempts to reassign it."},
  {"id": "3.7-complex-06", "course": "csa", "topic": "3.7", "tier": "complex", "lo": "3.7.A.1", "prompt": "public class Inventory2\n{\n    private int quantity;\n    private static int totalItems = 0;\n    public Inventory2(int q)\n    {\n        quantity = q;\n        totalItems = totalItems + q;\n    }\n    public static void restock(int amount)\n    {\n        /* candidate statement */\n    }\n}\nConsider these candidate statements that could replace /* candidate statement */ inside restock.\nI. totalItems = totalItems + amount;\nII. quantity = quantity + amount;\nIII. System.out.println(totalItems);\nWhich of these candidate statements would cause the class to fail to compile if placed inside restock?", "choices": ["I only", "III only", "I and III only", "II only"], "answer": 3, "explanation": "Statement II fails to compile because restock is static and quantity is an instance variable, which a static method cannot access or modify without being passed an instance of the class (3.7.A.1). Statements I and III both compile without issue, since totalItems is a class variable that any static method may freely read and modify (3.7.A.2)."},
  {"id": "3.7-complex-07", "course": "csa", "topic": "3.7", "tier": "complex", "lo": "3.7.B.2", "prompt": "public class Bank\n{\n    private static double interestRate = 0.02;\n    public static void setInterestRate(double rate)\n    {\n        interestRate = rate;\n    }\n    public static double computeInterest(double principal)\n    {\n        return principal * interestRate;\n    }\n}\nThe following code segment appears in a class other than Bank.\nBank.setInterestRate(0.05);\ndouble result1 = Bank.computeInterest(1000.0);\nBank.setInterestRate(0.10);\ndouble result2 = Bank.computeInterest(1000.0);\nSystem.out.println(result1 + \" \" + result2);\nWhat is printed?", "choices": ["50.0 100.0", "20.0 20.0", "50.0 50.0", "This code does not compile because interestRate is private"], "answer": 0, "explanation": "Since setInterestRate and computeInterest are public static methods, external code may call them through the class name, Bank.methodName(), even though interestRate itself is private; the class variable is updated to 0.05 before the first computation, yielding 50.0, and then updated to 0.10 before the second, yielding 100.0 (3.7.B.2). The code compiles successfully because only interestRate is private, not the methods that access it, so the output reflects each updated rate rather than the original 0.02 rate or an unchanging value."},
  {"id": "3.7-complex-08", "course": "csa", "topic": "3.7", "tier": "complex", "lo": "3.7.B.1", "prompt": "public class Tracker\n{\n    private String name;\n    private static int threshold = 10;\n    public Tracker(String n)\n    {\n        name = n;\n    }\n    public static void setThreshold(int t)\n    {\n        threshold = t;\n    }\n    public int checkLength()\n    {\n        int len = name.length();\n        threshold = threshold - 1;\n        return len - threshold;\n    }\n}\nTracker t1 = new Tracker(\"apples\");\nTracker t2 = new Tracker(\"kiwi\");\nint r1 = t1.checkLength();\nTracker.setThreshold(5);\nint r2 = t2.checkLength();\nTracker t3 = new Tracker(\"pear\");\nint r3 = t3.checkLength();\nSystem.out.println(r1 + \" \" + r2 + \" \" + r3);\nWhat is printed?", "choices": ["-3 0 0", "-3 0 1", "-4 -1 0", "6 4 4"], "answer": 1, "explanation": "For t1, threshold starts at 10, drops to 9 after the decrement, and checkLength returns 6 - 9 = -3. After setThreshold(5), threshold becomes 5 for every Tracker object; for t2, threshold drops to 4, and checkLength returns 4 - 4 = 0. For t3, threshold (still shared, currently 4) drops to 3, and checkLength returns 4 - 3 = 1, giving \"-3 0 1\" (3.7.B.1). The distractors miscompute the third call's result, shift every value due to an off-by-one error in the decrement timing, or forget to subtract threshold from len entirely."},
  {"id": "3.7-complex-09", "course": "csa", "topic": "3.7", "tier": "complex", "lo": "3.7.A.2", "prompt": "A programmer is designing a Cache class meant to store how many times a lookup has succeeded and failed, shared across every Cache object. The programmer proposes several designs. Assume all instance variables and methods not shown are declared appropriately.\nI.\npublic class Cache\n{\n    private static int hits = 0;\n    private static int misses = 0;\n    public static void recordHit()\n    {\n        hits++;\n    }\n    public static void recordMiss()\n    {\n        misses++;\n    }\n    public static double hitRate()\n    {\n        return (double) hits / (hits + misses);\n    }\n}\nII.\npublic class Cache\n{\n    private int hits = 0;\n    private int misses = 0;\n    public void recordHit()\n    {\n        hits++;\n    }\n    public void recordMiss()\n    {\n        misses++;\n    }\n}\nIII.\npublic class Cache\n{\n    private static int hits = 0;\n    private int misses = 0;\n    public static void recordHit()\n    {\n        hits++;\n    }\n    public void recordMiss()\n    {\n        misses++;\n    }\n}\nWhich design (I, II, or III) allows hits and misses to be correctly shared and updated across every Cache object created in the program?", "choices": ["II, because instance variables are always shared across objects of the same class", "III, because mixing static and instance variables always guarantees they are shared", "I, because hits and misses are both declared static, so every Cache object updates and sees the same single copy of each", "II and III equally, because both declare at least one static variable"], "answer": 2, "explanation": "Only Design I declares both hits and misses as static class variables, ensuring every Cache object reads and writes the same single shared copy of each (3.7.B.1, 3.7.A.2). Design II uses instance variables, which are never shared, so each object gets its own separate hits and misses; Design III only shares hits, since misses remains an instance variable with a separate copy per object; and II does not even contain a static variable, so it cannot be considered equal to III."},
  {"id": "3.7-complex-10", "course": "csa", "topic": "3.7", "tier": "complex", "lo": "3.7.B.1", "prompt": "public class Voucher\n{\n    public static final int EXPIRATION_DAYS = 30;\n    private static int totalVouchersIssued = 0;\n    private int daysValid;\n    public Voucher()\n    {\n        daysValid = EXPIRATION_DAYS;\n        totalVouchersIssued++;\n    }\n    public void extend(int extraDays)\n    {\n        daysValid = daysValid + extraDays;\n    }\n    public static int getTotalIssued()\n    {\n        return totalVouchersIssued;\n    }\n}\nVoucher v1 = new Voucher();\nv1.extend(10);\nVoucher v2 = new Voucher();\nVoucher v3 = new Voucher();\nv3.extend(5);\nSystem.out.println(Voucher.getTotalIssued());\nWhat is printed?", "choices": ["0", "40", "1", "3"], "answer": 3, "explanation": "totalVouchersIssued is incremented once inside the constructor every time a new Voucher object is created, so after three constructor calls its shared value is 3, regardless of how many times extend is called afterward, since extend only modifies the instance variable daysValid (3.7.B.1). 0 ignores that any constructors ran, 1 undercounts by only registering one voucher, and 40 confuses the total count with an unrelated calculation involving EXPIRATION_DAYS and extra days."},
  {"id": "3.7-complex-11", "course": "csa", "topic": "3.7", "tier": "complex", "lo": "3.7.A.1", "prompt": "public class Scoreboard\n{\n    private int homeScore;\n    private int awayScore;\n    private static int gamesLogged = 0;\n    public Scoreboard(int home, int away)\n    {\n        homeScore = home;\n        awayScore = away;\n        gamesLogged++;\n    }\n    public static int getWinningMargin()\n    {\n        return homeScore - awayScore;\n    }\n}\nThe class does not compile as written. Which change would allow it to compile, given that getWinningMargin should keep computing the margin for one specific Scoreboard object?", "choices": ["Remove the static keyword from getWinningMargin so it can access the instance variables homeScore and awayScore", "Change homeScore and awayScore to static variables so getWinningMargin can access them", "Change gamesLogged to an instance variable", "Add a return type of void to getWinningMargin"], "answer": 0, "explanation": "Because getWinningMargin needs to compute a margin specific to one Scoreboard object, using its instance variables homeScore and awayScore, the method must not be static, since a static method cannot access instance variables without an object being passed in (3.7.A.1). Making homeScore and awayScore static would make them shared across every Scoreboard, losing each game's individual score; gamesLogged is intentionally a shared class variable and changing it would break that count; and the method already correctly returns an int, so changing its return type to void would remove the value it is meant to compute."},
  {"id": "3.7-complex-12", "course": "csa", "topic": "3.7", "tier": "complex", "lo": "3.7.B.2", "prompt": "public class Season\n{\n    private static String currentSeason = \"Spring\";\n    private static int gamesPlayed = 0;\n    public static void advanceSeason(String next)\n    {\n        currentSeason = next;\n        gamesPlayed = 0;\n    }\n    public static void playGame()\n    {\n        gamesPlayed++;\n    }\n}\nThe following code segment appears in a class other than Season.\nSeason.playGame();\nSeason.playGame();\nSeason.advanceSeason(\"Summer\");\nSeason.playGame();\nSystem.out.println(Season.currentSeason + \" \" + Season.gamesPlayed);\nWhat is printed, or does this code fail to compile?", "choices": ["Summer 1", "This code does not compile because currentSeason and gamesPlayed are private and cannot be accessed directly from outside the class using the class name", "Spring 3", "Summer 3"], "answer": 1, "explanation": "Even though currentSeason and gamesPlayed are static, they are also declared private, so outside code cannot access them directly with Season.currentSeason or Season.gamesPlayed; only the public static methods playGame and advanceSeason could be called successfully (3.7.B.2). The other choices describe plausible-looking traced values, but they are irrelevant because the direct field access never compiles in the first place."},
  {"id": "3.7-complex-13", "course": "csa", "topic": "3.7", "tier": "complex", "lo": "3.7.A.2", "prompt": "A programmer is adding a method to the following class that should reset every ID number back to 1 for the next object created.\npublic class Badge\n{\n    private static int nextID = 1;\n    private int idNumber;\n    public Badge()\n    {\n        idNumber = nextID;\n        nextID++;\n    }\n}\nConsider the following candidate methods.\nI.\npublic static void resetIDs()\n{\n    nextID = 1;\n}\nII.\npublic void resetIDs()\n{\n    nextID = 1;\n}\nIII.\npublic static void resetIDs()\n{\n    idNumber = 1;\n}\nWhich of these candidate methods compile successfully?", "choices": ["I only", "III only", "I and II only", "I, II, and III"], "answer": 2, "explanation": "Both I and II compile because nextID is a class variable, which can be freely accessed and modified by a static method (3.7.A.2) or by an ordinary instance method, since instance methods are always allowed to use class variables. III does not compile because resetIDs is static in that version but tries to modify idNumber, an instance variable, which a static method cannot do without being passed an instance (3.7.A.1)."},
  {"id": "3.7-complex-14", "course": "csa", "topic": "3.7", "tier": "complex", "lo": "3.7.B.1", "prompt": "public class Order\n{\n    private static double revenue = 0.0;\n    private static int orderCount = 0;\n    private double amount;\n    public Order(double amt)\n    {\n        amount = amt;\n        if (amt > 0)\n        {\n            revenue = revenue + amt;\n            orderCount++;\n        }\n    }\n    public static double averageOrder()\n    {\n        if (orderCount == 0)\n        {\n            return 0.0;\n        }\n        return revenue / orderCount;\n    }\n}\nOrder o1 = new Order(50.0);\nOrder o2 = new Order(-5.0);\nOrder o3 = new Order(30.0);\nOrder o4 = new Order(10.0);\nSystem.out.println(Order.averageOrder());\nWhat is printed?", "choices": ["0.0", "22.5", "26.25", "30.0"], "answer": 3, "explanation": "The negative amount in o2 fails the amt > 0 check, so it never updates revenue or orderCount, leaving three valid orders (50.0, 30.0, 10.0) that sum to a shared revenue of 90.0 with a shared orderCount of 3, giving an average of 30.0 (3.7.B.1). 0.0 would only be correct if no valid orders existed, and 22.5 and 26.25 result from incorrectly including the negative order or miscounting the number of valid orders."},
  {"id": "3.7-complex-15", "course": "csa", "topic": "3.7", "tier": "complex", "lo": "3.7.B.3", "prompt": "public class Constants\n{\n    public static final double CONVERSION_FACTOR = 2.54;\n    private static double totalConverted = 0.0;\n    public static double convert(double inches)\n    {\n        double result = inches * CONVERSION_FACTOR;\n        totalConverted = totalConverted + result;\n        return result;\n    }\n}\nWhich of the following statements, if added inside another static method of the Constants class, would cause a compile-time error?", "choices": ["CONVERSION_FACTOR = 3.0;", "double x = CONVERSION_FACTOR * 2;", "totalConverted = totalConverted + 1.0;", "System.out.println(CONVERSION_FACTOR);"], "answer": 0, "explanation": "CONVERSION_FACTOR is declared final, so any attempt to assign it a new value after initialization, such as CONVERSION_FACTOR = 3.0, causes a compile-time error (3.7.B.3). Using CONVERSION_FACTOR in an expression, modifying the non-final class variable totalConverted, and printing CONVERSION_FACTOR are all legal, since final only blocks reassignment, not use."},
  {"id": "3.8-basic-01", "course": "csa", "topic": "3.8", "tier": "basic", "lo": "3.8.A.1", "prompt": "A method header is written as follows.\npublic void setSpeed(int newSpeed)\nWhat term best describes newSpeed?", "choices": ["A local variable, because it is declared in the method header and only exists while the method runs", "An instance variable, because it stores data belonging to the object", "A class variable, because its value is shared by every object of the class", "A constant, because its value cannot change once the method begins running"], "answer": 0, "explanation": "A parameter such as newSpeed is declared in the method header, making it a local variable that exists only while setSpeed is executing (3.8.A.1). It is not an instance variable, since instance variables are declared in the class body outside any method; it is not a class variable, since parameters are never shared across objects; and nothing about being a parameter prevents its value from being reassigned inside the method."},
  {"id": "3.8-basic-02", "course": "csa", "topic": "3.8", "tier": "basic", "lo": "3.8.A.1", "prompt": "A student writes the following method inside a class.\npublic void printTotal()\n{\n    private int total = 100;\n    System.out.println(total);\n}\nWhy does this method fail to compile?", "choices": ["The variable total must be declared as an instance variable instead of a local variable", "println cannot be used with a variable that was declared in the same method", "The method must include a return statement because it declares a variable", "A local variable such as total is declared inside the method body and cannot be given an access modifier like private"], "answer": 3, "explanation": "Local variables, including those declared inside a method body, may only be used within that method and can never be marked public or private; only instance variables and class-level members can carry an access modifier (3.8.A.1). total does not need to be an instance variable simply to be printed, println works fine with any local int variable already in scope, and a void method that declares a variable has no requirement to include a return statement."},
  {"id": "3.8-basic-03", "course": "csa", "topic": "3.8", "tier": "basic", "lo": "3.8.A.2", "prompt": "public class Wallet\n{\n    private int balance;\n    public Wallet(int startBalance)\n    {\n        balance = startBalance;\n    }\n    public void deposit(int balance)\n    {\n        balance = balance + 50;\n    }\n    public int getBalance()\n    {\n        return balance;\n    }\n}\nThe following code segment appears in a class other than Wallet.\nWallet w = new Wallet(100);\nw.deposit(25);\nSystem.out.println(w.getBalance());\nWhat is printed as a result of executing this code segment?", "choices": ["150", "125", "100", "50"], "answer": 2, "explanation": "Inside deposit, the parameter balance shadows the instance variable balance for the entire method body, so the statement balance = balance + 50 only updates the local parameter, which is discarded when the method ends; the instance variable balance is never touched (3.8.A.2). Because of this, getBalance() still returns the value set by the constructor, 100. 150 and 125 would only be correct if the instance variable had actually been updated, and 50 is not a value this code produces at all."},
  {"id": "3.8-basic-04", "course": "csa", "topic": "3.8", "tier": "basic", "lo": "3.8.A.1", "prompt": "public void checkTemperature(int reading)\n{\n    if (reading > 90)\n    {\n        String status = \"hot\";\n        System.out.println(status);\n    }\n    System.out.println(status);\n}\nWhy does this method fail to compile?", "choices": ["The variable status is declared inside the if block and is out of scope on the last line, outside that block", "String variables cannot be declared inside an if statement", "The parameter reading must be declared as a String instead of an int", "The method must return a value because it uses an if statement"], "answer": 0, "explanation": "status is a local variable declared inside the if block, so it can only be accessed within that block; once the block ends, status is out of scope, and the final println(status) fails to compile (3.8.A.1). There is no restriction against declaring a String inside an if statement, reading's type is unrelated to this error, and a void method with an if statement does not need to return a value."},
  {"id": "3.8-basic-05", "course": "csa", "topic": "3.8", "tier": "basic", "lo": "3.8.A.2", "prompt": "public class Countdown\n{\n    private int seconds;\n    public Countdown(int startSeconds)\n    {\n        seconds = startSeconds;\n    }\n    public void tick()\n    {\n        for (int seconds = 0; seconds < 3; seconds++)\n        {\n            System.out.println(seconds);\n        }\n    }\n}\nCountdown c = new Countdown(10);\nc.tick();\nWhat is printed as a result of executing this code segment?", "choices": ["10\n11\n12", "0\n1\n2", "0\n1\n2\n10", "10"], "answer": 1, "explanation": "The for loop declares its own local variable seconds, which shadows the instance variable seconds for the entire loop; the loop prints its local seconds counting 0, 1, 2 before the loop condition fails (3.8.A.2). The instance variable seconds, set to 10 by the constructor, is never printed inside tick(), so choices involving 10 or 11/12 incorrectly assume the loop uses or affects the instance variable."},
  {"id": "3.8-basic-06", "course": "csa", "topic": "3.8", "tier": "basic", "lo": "3.8.A.1", "prompt": "public class Wardrobe\n{\n    private int shirtCount;\n    public void addShirts(int amount)\n    {\n        int newTotal = shirtCount + amount;\n        shirtCount = newTotal;\n    }\n    public void printSummary()\n    {\n        System.out.println(newTotal);\n    }\n}\nWhy does this class fail to compile?", "choices": ["shirtCount was never declared as public", "amount must be declared as an instance variable", "newTotal is a local variable declared inside addShirts and cannot be accessed inside printSummary", "addShirts must return an int instead of void"], "answer": 2, "explanation": "newTotal is a local variable declared inside addShirts, so it only exists while addShirts is running and cannot be referenced from a different method like printSummary (3.8.A.1). shirtCount being private is unrelated to this error, amount does not need to be an instance variable to be used as a parameter, and addShirts has no obligation to return a value just because it declares a local variable."},
  {"id": "3.8-basic-07", "course": "csa", "topic": "3.8", "tier": "basic", "lo": "3.8.A.2", "prompt": "public class Traveler\n{\n    private String destination;\n    public Traveler(String destination)\n    {\n        destination = destination;\n    }\n    public String getDestination()\n    {\n        return destination;\n    }\n}\nTraveler t = new Traveler(\"Tokyo\");\nSystem.out.println(t.getDestination());\nWhat is printed as a result of executing this code segment, and why?", "choices": ["\"Tokyo\", because the constructor correctly assigns the parameter to the instance variable", "An empty string, because String instance variables default to \"\" rather than null", "A compile-time error, because a parameter cannot share a name with an instance variable", "null, because the parameter destination shadows the instance variable, so destination = destination just assigns the parameter to itself and the instance variable is never set"], "answer": 3, "explanation": "Because the constructor's parameter is also named destination, that name refers to the local parameter throughout the constructor body, so destination = destination simply reassigns the parameter to itself and never touches the instance variable (3.8.A.2). The instance variable destination therefore keeps its default value, null, for a reference type such as String, not an empty string. It is legal, though a common source of bugs, for a parameter to share a name with an instance variable, so this does not cause a compile error."},
  {"id": "3.8-basic-08", "course": "csa", "topic": "3.8", "tier": "basic", "lo": "3.8.A.1", "prompt": "public class Notebook\n{\n    private String title;\n    private int pageCount;\n    public Notebook(String bookTitle, int pages)\n    {\n        title = bookTitle;\n        pageCount = pages;\n    }\n}\nWhich variables in this class are local variables?", "choices": ["title and pageCount only", "title, pageCount, bookTitle, and pages", "None of the variables in this class are local variables", "bookTitle and pages only"], "answer": 3, "explanation": "bookTitle and pages are the constructor's parameters, and parameters are always local variables that exist only while the constructor runs (3.8.A.1). title and pageCount are declared in the class body outside any constructor or method, making them instance variables rather than local variables, so they cannot be included with bookTitle and pages, and it is false that no local variables exist in this class."},
  {"id": "3.8-basic-09", "course": "csa", "topic": "3.8", "tier": "basic", "lo": "3.8.A.2", "prompt": "public class TicketBooth\n{\n    private double price;\n    public TicketBooth(double startPrice)\n    {\n        price = startPrice;\n    }\n    public double quote(double price)\n    {\n        return price;\n    }\n}\nTicketBooth booth = new TicketBooth(12.0);\nSystem.out.println(booth.quote(5.0));\nWhat is printed as a result of executing this code segment?", "choices": ["17.0", "12.0", "5.0", "0.0"], "answer": 2, "explanation": "The parameter price shadows the instance variable price for the entire body of quote, so return price returns the value passed as an argument, 5.0, not the instance variable's value (3.8.A.2). 12.0 would only be printed if quote returned the instance variable instead, 17.0 would require adding the two values, which the method never does, and 0.0 is not related to any value in this program."},
  {"id": "3.8-basic-10", "course": "csa", "topic": "3.8", "tier": "basic", "lo": "3.8.A.1", "prompt": "public void printSquares(int limit)\n{\n    for (int i = 1; i <= limit; i++)\n    {\n        System.out.println(i * i);\n    }\n    System.out.println(i);\n}\nWhy does this method fail to compile?", "choices": ["limit is a local variable and cannot be used inside a for loop", "The loop variable i is declared inside the for loop and is out of scope once the loop ends", "The multiplication i * i is not allowed inside a for loop", "The method must be declared to return an int"], "answer": 1, "explanation": "The for loop header declares i as a local variable scoped to the loop; once the loop finishes, i is out of scope, so the final println(i) cannot compile (3.8.A.1). limit is a perfectly ordinary local parameter that may be used as a loop bound, multiplication is allowed anywhere an int expression is valid, and a void method has no requirement to return a value."},
  {"id": "3.8-basic-11", "course": "csa", "topic": "3.8", "tier": "basic", "lo": "3.8.A.2", "prompt": "public class Speedometer\n{\n    private int speed;\n    public Speedometer(int startSpeed)\n    {\n        speed = startSpeed;\n    }\n    public void logReadings()\n    {\n        for (int speed = 0; speed < 2; speed++)\n        {\n            System.out.println(\"reading: \" + speed);\n        }\n        System.out.println(\"final: \" + speed);\n    }\n}\nSpeedometer s = new Speedometer(60);\ns.logReadings();\nWhat is printed as a result of executing this code segment?", "choices": ["reading: 0\nreading: 1\nfinal: 60", "reading: 0\nreading: 1\nfinal: 2", "reading: 60\nreading: 61\nfinal: 62", "reading: 0\nreading: 1\nfinal: 0"], "answer": 0, "explanation": "Inside the for loop, the loop's local variable speed shadows the instance variable speed and takes on the values 0 and 1 before the loop condition fails (3.8.A.2). Once the loop ends, its local speed goes out of scope, so the final println refers to the instance variable speed, which still holds 60 from the constructor. Printing 2 or 0 for the final line incorrectly assumes the loop variable's last value or a default value carries over, and starting the loop at 60 incorrectly assumes the loop uses the instance variable as its starting point."},
  {"id": "3.8-basic-12", "course": "csa", "topic": "3.8", "tier": "basic", "lo": "3.8.A.1", "prompt": "public double calculateTip(double bill)\n{\n    public double tipRate = 0.18;\n    return bill * tipRate;\n}\nWhy does this method fail to compile?", "choices": ["bill was never declared as an instance variable", "A local variable such as tipRate cannot be declared with an access modifier like public", "The method must be declared void instead of double", "Multiplication cannot be used in a return statement"], "answer": 1, "explanation": "tipRate is a local variable declared inside the method body, and local variables can never be declared with an access modifier such as public or private; only class-level members can carry one (3.8.A.1). bill does not need to be an instance variable to be used as a parameter, the method correctly returns a double as declared, and a return statement can contain any valid expression, including a multiplication."},
  {"id": "3.8-basic-13", "course": "csa", "topic": "3.8", "tier": "basic", "lo": "3.8.A.1", "prompt": "public class Backpack\n{\n    private int itemCount;\n    public void addItem()\n    {\n        int count = itemCount + 1;\n        itemCount = count;\n    }\n    public void removeItem()\n    {\n        int count = itemCount - 1;\n        itemCount = count;\n    }\n}\nWhich statement is true about the two local variables named count in this class?", "choices": ["They are the same variable, so changing one inside addItem also changes the value seen inside removeItem", "The program fails to compile because a class cannot contain two variables with the same name", "Each amount is a separate local variable scoped only to the method in which it is declared", "They are both treated as instance variables because they share a name"], "answer": 2, "explanation": "Each method has its own local scope, so the count declared inside addItem and the count declared inside removeItem are entirely separate variables that never interact, even though they share a name (3.8.A.1). This is legal and compiles without issue, since local variable scope is limited to the enclosing method, and neither local variable becomes an instance variable simply by sharing a name with one in another method."},
  {"id": "3.8-basic-14", "course": "csa", "topic": "3.8", "tier": "basic", "lo": "3.8.A.1", "prompt": "public class Furnace\n{\n    private boolean running;\n    public Furnace()\n    {\n        boolean startupCheck = true;\n        running = startupCheck;\n    }\n    public void reportStatus()\n    {\n        System.out.println(startupCheck);\n    }\n}\nWhy does this class fail to compile?", "choices": ["running was never initialized inside the constructor", "startupCheck is a local variable declared inside the constructor and cannot be referenced inside reportStatus", "A constructor cannot declare local variables of type boolean", "reportStatus must be declared with a return type instead of void"], "answer": 1, "explanation": "startupCheck is declared as a local variable inside the constructor, so it only exists while the constructor runs and cannot be accessed from a separate method like reportStatus (3.8.A.1). running is properly initialized from startupCheck inside the constructor, boolean local variables are entirely legal in a constructor, and a void method is not required to return a value."},
  {"id": "3.8-basic-15", "course": "csa", "topic": "3.8", "tier": "basic", "lo": "3.8.A.2", "prompt": "public class Invoice\n{\n    private double total;\n    public Invoice(double startTotal)\n    {\n        total = startTotal;\n    }\n    public double applyDiscount(double total)\n    {\n        total = total * 0.9;\n        return total;\n    }\n    public double getTotal()\n    {\n        return total;\n    }\n}\nInvoice inv = new Invoice(200.0);\ndouble discounted = inv.applyDiscount(100.0);\nSystem.out.println(discounted + \" \" + inv.getTotal());\nWhat is printed as a result of executing this code segment?", "choices": ["90.0 200.0", "90.0 90.0", "200.0 200.0", "100.0 200.0"], "answer": 0, "explanation": "Inside applyDiscount, the parameter total shadows the instance variable total for the whole method, so total = total * 0.9 uses the argument passed in, 100.0, producing 90.0, which is what discounted receives and what is returned (3.8.A.2). Because the parameter is local, the instance variable total is never modified, so getTotal() still returns 200.0 from the constructor. Printing 90.0 for both values incorrectly assumes the instance variable was updated, printing 200.0 for both incorrectly assumes the discount had no effect on the local calculation, and printing 100.0 ignores that the discount multiplication actually executed on the local parameter."},
  {"id": "3.8-intermediate-01", "course": "csa", "topic": "3.8", "tier": "intermediate", "lo": "3.8.A.2", "prompt": "public class Battery\n{\n    private int charge;\n    public Battery(int startCharge)\n    {\n        charge = startCharge;\n    }\n    public void drain(int charge)\n    {\n        charge = charge - 10;\n        System.out.println(\"local: \" + charge);\n    }\n    public int getCharge()\n    {\n        return charge;\n    }\n}\nBattery b = new Battery(80);\nb.drain(30);\nSystem.out.println(\"instance: \" + b.getCharge());\nWhat is printed as a result of executing this code segment?", "choices": ["local: 20\ninstance: 80", "local: 70\ninstance: 70", "local: 20\ninstance: 20", "local: 70\ninstance: 80"], "answer": 0, "explanation": "The parameter charge shadows the instance variable charge throughout drain, so charge = charge - 10 uses the argument 30, producing 20, which is what gets printed as 'local' (3.8.A.2). Because the parameter is local, the instance variable charge, set to 80 by the constructor, is never modified, so getCharge() still returns 80. Printing 70 for the local value would require subtracting 10 from 80 instead of the argument, and printing 20 or 70 for the instance value both incorrectly assume the local update reached the instance variable."},
  {"id": "3.8-intermediate-02", "course": "csa", "topic": "3.8", "tier": "intermediate", "lo": "3.8.A.1", "prompt": "A student is deciding how to declare a local variable named count inside a method. Consider three candidate declarations written inside the method body.\nI. int count = 0;\nII. private int count = 0;\nIII. public int count = 0;\nWhich of these declarations will compile successfully?", "choices": ["I, II, and III", "I only", "II and III only", "I and II only"], "answer": 1, "explanation": "Local variables can never be given an access modifier, so only declaration I, which omits public or private entirely, compiles (3.8.A.1). Declarations II and III both attempt to attach an access modifier to a local variable, which is illegal regardless of whether the modifier is private or public, so neither of them compiles."},
  {"id": "3.8-intermediate-03", "course": "csa", "topic": "3.8", "tier": "intermediate", "lo": "3.8.A.2", "prompt": "public class Locker\n{\n    private String combination;\n    private boolean locked;\n    public Locker(String code)\n    {\n        combination = code;\n        locked = true;\n    }\n    public void resetCombination(String combination)\n    {\n        combination = combination.substring(1);\n    }\n    public String getCombination()\n    {\n        return combination;\n    }\n}\nLocker myLocker = new Locker(\"4821\");\nmyLocker.resetCombination(\"9163\");\nSystem.out.println(myLocker.getCombination());\nWhat is printed as a result of executing this code segment?", "choices": ["163", "821", "9163", "4821"], "answer": 3, "explanation": "Inside resetCombination, the parameter combination shadows the instance variable combination for the entire method body, so combination = combination.substring(1) only reassigns the local parameter to \"163\" and never affects the instance variable (3.8.A.2). Because the instance variable combination is never modified, getCombination() still returns the value set by the constructor, \"4821\". \"163\" and \"9163\" both incorrectly assume the local reassignment reached the instance variable, and \"821\" is not a value produced anywhere in this code."},
  {"id": "3.8-intermediate-04", "course": "csa", "topic": "3.8", "tier": "intermediate", "lo": "3.8.A.1", "prompt": "public class Fishbowl\n{\n    private int fishCount;\n    public void feedMorning()\n    {\n        int amount = 2;\n        fishCount += amount;\n    }\n    public void feedEvening()\n    {\n        int amount = 3;\n        fishCount += amount;\n    }\n}\nWhich statement correctly describes the two variables named amount in this class?", "choices": ["They refer to the same memory location, so setting amount in feedMorning also changes it in feedEvening", "The class fails to compile, since a class cannot contain two local variables with the same name in different methods", "Each amount is a separate local variable scoped to its own method, so they do not interact, and both feedMorning and feedEvening correctly update fishCount", "Only the amount declared in feedMorning is legal, since a local variable name can be reused only once per class"], "answer": 2, "explanation": "Local variable scope is limited to the method in which the variable is declared, so the two variables named amount are entirely independent and each correctly contributes to updating the shared instance variable fishCount within its own method (3.8.A.1). It is legal, and quite common, for unrelated methods to reuse the same local variable name, so there is no compile error and no shared memory location between the two."},
  {"id": "3.8-intermediate-05", "course": "csa", "topic": "3.8", "tier": "intermediate", "lo": "3.8.A.2", "prompt": "public class Thermos\n{\n    private double volume;\n    public Thermos(double startVolume)\n    {\n        volume = startVolume;\n    }\n    // Candidate I\n    public void fillA(double volume)\n    {\n        volume = volume + 5.0;\n    }\n    // Candidate II\n    public void fillB(double amount)\n    {\n        volume = volume + amount;\n    }\n    // Candidate III\n    public void fillC(double volume)\n    {\n        double newVolume = volume + 5.0;\n    }\n}\nWhich of the candidate methods, if added to the Thermos class, would correctly increase the instance variable volume by 5.0 when called as fillX(5.0)?", "choices": ["II only", "I and III only", "I, II, and III", "III only"], "answer": 0, "explanation": "Only fillB avoids shadowing: its parameter is named amount, so volume inside the method body still refers to the instance variable, and volume = volume + amount correctly updates it (3.8.A.2). fillA's parameter volume shadows the instance variable for the whole method, so its reassignment is discarded when the method ends, and fillC both shadows volume with its parameter and stores the result in a separate local variable newVolume, so the instance variable is never touched in either case."},
  {"id": "3.8-intermediate-06", "course": "csa", "topic": "3.8", "tier": "intermediate", "lo": "3.8.A.2", "prompt": "public class Aquarium\n{\n    private int capacity;\n    private int level;\n    public Aquarium()\n    {\n        capacity = 4;\n        level = 6;\n    }\n    public int fillCycle(int capacity)\n    {\n        int total = 0;\n        for (int level = 0; level < capacity; level++)\n        {\n            total += level;\n        }\n        total += level;\n        return total;\n    }\n}\nAquarium tank = new Aquarium();\nSystem.out.println(tank.fillCycle(3));\nWhat is printed as a result of executing this code segment?", "choices": ["3", "9", "6", "12"], "answer": 1, "explanation": "The parameter capacity shadows the instance variable capacity for the whole method, so the loop runs while the local level, which shadows the instance variable level only inside the loop, is less than 3, accumulating total = 0 + 1 + 2 = 3 (3.8.A.2). Once the loop ends, its local level goes out of scope, so total += level uses the instance variable level, which is 6, giving a final total of 3 + 6 = 9. Printing 3 stops before adding the instance variable's contribution, printing 6 ignores the loop's accumulated sum entirely, and printing 12 would require the loop to run using the instance variable capacity, 4, instead of the parameter."},
  {"id": "3.8-intermediate-07", "course": "csa", "topic": "3.8", "tier": "intermediate", "lo": "3.8.A.1", "prompt": "A student is writing a method and considers three candidate lines to include inside its body.\nI. int score = 0;\nII. private double average;\nIII. String label = \"none\";\nWhich of these lines, if placed inside a method body, would cause a compile-time error?", "choices": ["I only", "III only", "II only", "I and III only"], "answer": 2, "explanation": "Line II attempts to declare a local variable, average, with the access modifier private, which is illegal since local variables can never carry an access modifier (3.8.A.1). Lines I and III declare ordinary local variables with no access modifier attached, so both compile without any issue."},
  {"id": "3.8-intermediate-08", "course": "csa", "topic": "3.8", "tier": "intermediate", "lo": "3.8.A.2", "prompt": "public class MailBox\n{\n    private int letterCount;\n    public MailBox(int startCount)\n    {\n        letterCount = startCount;\n    }\n    public void addLetters(int letterCount)\n    {\n        letterCount++;\n    }\n    public int getLetterCount()\n    {\n        return letterCount;\n    }\n}\nMailBox box = new MailBox(5);\nbox.addLetters(10);\nSystem.out.println(box.getLetterCount());\nWhat is printed as a result of executing this code segment?", "choices": ["6", "11", "15", "5"], "answer": 3, "explanation": "The parameter letterCount shadows the instance variable letterCount throughout addLetters, so letterCount++ only increments the local parameter (from 10 to 11) and is discarded once the method returns; the instance variable letterCount is never modified (3.8.A.2). getLetterCount() therefore still returns the value set by the constructor, 5. Printing 6 assumes the instance variable was incremented directly, printing 11 assumes the incremented parameter value was somehow stored back, and printing 15 would require adding the constructor value and the argument, which never happens in this code."},
  {"id": "3.8-intermediate-09", "course": "csa", "topic": "3.8", "tier": "intermediate", "lo": "3.8.A.1", "prompt": "Consider the following three statements about local variables and parameters in Java.\nI. A parameter to a method is considered a local variable within that method.\nII. A local variable can be declared public if it is intended to be accessed by other classes.\nIII. A local variable declared inside a for loop's header is no longer in scope once the loop finishes executing.\nWhich of these statements are true?", "choices": ["I and II only", "II and III only", "I, II, and III", "I and III only"], "answer": 3, "explanation": "Statement I is true because method and constructor parameters are treated as local variables (3.8.A.1). Statement III is also true, since a for loop's control variable is scoped to the loop and goes out of scope once the loop ends. Statement II is false, since local variables, including parameters, can never be declared public or private regardless of whether another class might want to access them; that restriction is unconditional (3.8.A.1)."},
  {"id": "3.8-intermediate-10", "course": "csa", "topic": "3.8", "tier": "intermediate", "lo": "3.8.A.2", "prompt": "A Candle class has two instance variables, private double waxLevel and private double reduceBy. Three candidate methods are proposed to decrease waxLevel by reduceBy.\nI.\npublic void burn(double waxLevel)\n{\n    waxLevel = waxLevel - reduceBy;\n}\nII.\npublic void burn(double amount)\n{\n    waxLevel = waxLevel - reduceBy;\n}\nIII.\npublic void burn(double waxLevel)\n{\n    double amount = waxLevel - reduceBy;\n}\nWhich of these candidate methods, if added to the Candle class, correctly updates the instance variable waxLevel?", "choices": ["I only", "I and III only", "II only", "II and III only"], "answer": 2, "explanation": "Only candidate II avoids giving its parameter the name waxLevel, so inside its body waxLevel still refers to the instance variable, and waxLevel = waxLevel - reduceBy correctly reassigns it (3.8.A.2). Candidates I and III both name their parameter waxLevel, which shadows the instance variable for the entire method body; in candidate I this makes the assignment operate only on the local parameter, and in candidate III the subtraction also uses the shadowed parameter and stores its result in an unrelated local variable amount, so the instance variable is never modified in either case."},
  {"id": "3.8-intermediate-11", "course": "csa", "topic": "3.8", "tier": "intermediate", "lo": "3.8.A.1", "prompt": "public class Compass\n{\n    private String direction;\n    public void calibrate(int reading)\n    {\n        if (reading > 180)\n        {\n            String note = \"reversed\";\n            direction = note;\n        }\n        else\n        {\n            direction = \"normal\";\n        }\n        System.out.println(note);\n    }\n}\nWhy does this method fail to compile?", "choices": ["direction was never declared inside the if block", "note is a local variable scoped to the if block and is out of scope in the println statement outside both branches", "An else branch cannot assign a value to an instance variable", "reading must be declared as a String rather than an int"], "answer": 1, "explanation": "note is declared inside the if block, so its scope is limited to that block; once execution leaves the if block, note is no longer in scope, so the final println(note) does not compile (3.8.A.1). direction is a properly declared instance variable used correctly in both branches, an else branch may assign to an instance variable exactly like any other statement, and reading's int type has no bearing on this error."},
  {"id": "3.8-intermediate-12", "course": "csa", "topic": "3.8", "tier": "intermediate", "lo": "3.8.A.2", "prompt": "A GradeReport class has one instance variable, private double average. Three candidate versions of a method intended to compute and store the class average are proposed.\nI.\npublic void computeAverage(double sum, int count)\n{\n    double average = sum / count;\n}\nII.\npublic void computeAverage(double sum, int count)\n{\n    average = sum / count;\n}\nIII.\npublic double computeAverage(double sum, int count)\n{\n    double average = sum / count;\n    return average;\n}\nWhich of these candidate methods correctly updates the instance variable average?", "choices": ["II only", "I and III only", "I only", "III only"], "answer": 0, "explanation": "Only candidate II omits declaring a new local variable named average, so the assignment average = sum / count refers directly to the instance variable and updates it (3.8.A.2). Candidate I declares a local variable average that shadows the instance variable, discarding the computed value once the method ends, and candidate III does the same, merely returning the shadowed local value to the caller instead of storing it in the instance variable, so neither actually updates average."},
  {"id": "3.8-intermediate-13", "course": "csa", "topic": "3.8", "tier": "intermediate", "lo": "3.8.A.1", "prompt": "public class Elevator\n{\n    private int currentFloor;\n    public void moveTo(int targetFloor)\n    {\n        int distance = targetFloor - currentFloor;\n        currentFloor = targetFloor;\n    }\n}\nWhich variables in the moveTo method are local variables?", "choices": ["currentFloor only", "targetFloor only", "targetFloor and distance", "currentFloor, targetFloor, and distance"], "answer": 2, "explanation": "targetFloor is a parameter and distance is declared inside the method body, so both are local variables that exist only while moveTo runs (3.8.A.1). currentFloor is declared in the class body outside any method, making it an instance variable rather than a local variable, so it should not be included in either the correct answer or the fourth option, which incorrectly lumps all three together."},
  {"id": "3.8-intermediate-14", "course": "csa", "topic": "3.8", "tier": "intermediate", "lo": "3.8.A.2", "prompt": "public class Playlist\n{\n    private String currentSong;\n    public Playlist(String firstSong)\n    {\n        currentSong = firstSong;\n    }\n    public void skip(String currentSong)\n    {\n        currentSong = currentSong.substring(1);\n        System.out.println(currentSong);\n    }\n    public int getLength()\n    {\n        return currentSong.length();\n    }\n}\nPlaylist p = new Playlist(\"Sunrise\");\np.skip(\"Nightfall\");\nSystem.out.println(p.getLength());\nWhat is printed as a result of executing this code segment?", "choices": ["ightfall\n7", "ightfall\n8", "Nightfall\n7", "ightfall\n9"], "answer": 0, "explanation": "The parameter currentSong shadows the instance variable currentSong throughout skip, so currentSong.substring(1) operates on the argument \"Nightfall\", producing and printing \"ightfall\"; this reassignment only affects the local parameter (3.8.A.2). Because the instance variable currentSong is never modified, it still holds \"Sunrise\" from the constructor, so getLength() returns 7, the length of \"Sunrise\". Printing 8 would be the length of \"ightfall\" instead of the instance variable's value, 9 is the length of \"Nightfall\", and printing \"Nightfall\" unchanged ignores that substring(1) was actually applied to the local parameter."},
  {"id": "3.8-intermediate-15", "course": "csa", "topic": "3.8", "tier": "intermediate", "lo": "3.8.A.1", "prompt": "public class Scoreboard\n{\n    private int homeScore;\n    private int awayScore;\n    public Scoreboard()\n    {\n        homeScore = 0;\n        awayScore = 0;\n    }\n    public Scoreboard(int home, int away)\n    {\n        homeScore = home;\n        awayScore = away;\n    }\n    public void addHomePoints(int points)\n    {\n        int updated = homeScore + points;\n        homeScore = updated;\n    }\n}\nWhich of the following is true about the variables home, away, points, and updated in this class?", "choices": ["All four are instance variables, since they are used to update homeScore and awayScore", "All four are local variables: home and away are parameters of one constructor, points is a parameter of addHomePoints, and updated is declared inside addHomePoints", "home and away are instance variables, while points and updated are local variables", "home, away, and points are local variables, but updated becomes an instance variable once it is assigned to homeScore"], "answer": 1, "explanation": "Parameters to any constructor or method are local variables, so home and away, parameters of the second constructor, and points, a parameter of addHomePoints, are all local, and updated, declared inside addHomePoints's body, is local as well (3.8.A.1). None of these four become instance variables just because their values are used to update homeScore or awayScore; only variables declared in the class body outside any method or constructor, like homeScore and awayScore themselves, are instance variables."},
  {"id": "3.8-complex-01", "course": "csa", "topic": "3.8", "tier": "complex", "lo": "3.8.A.2", "prompt": "public class TallyBox\n{\n    private int limit;\n    private int base;\n    public TallyBox()\n    {\n        limit = 4;\n        base = 20;\n    }\n    public int accumulate(int limit)\n    {\n        int sum = 0;\n        for (int base = 1; base <= limit; base++)\n        {\n            sum += base;\n        }\n        sum += base;\n        return sum;\n    }\n}\nThe following code segment appears in a class other than TallyBox.\nTallyBox box = new TallyBox();\nSystem.out.println(box.accumulate(3));\nWhich of the following best describes the behavior of this code segment?", "choices": ["The accumulate method sums the integers 1 through 4, adds the instance variable base (20), and returns 30", "The accumulate method sums the integers 1 through 3, adds the instance variable limit (4), and returns 10", "The accumulate method sums the integers 1 through 3, adds the instance variable base (20), and returns 26", "The accumulate method sums the integers 1 through 4, adds the parameter limit (3), and returns 13"], "answer": 2, "explanation": "The parameter limit shadows the instance variable limit for the entire method, so the loop runs while the local base (which shadows the instance variable base only inside the loop) is at most 3, the argument passed in; sum accumulates 1 + 2 + 3 = 6. Once the loop ends, its local base goes out of scope, so sum += base uses the instance variable base, 20, giving a final result of 26 (3.8.A.2). Summing through 4 would incorrectly use the instance variable limit, 4, as the loop bound instead of the parameter, and adding the instance variable limit instead of base misidentifies which instance variable remains accessible after the loop."},
  {"id": "3.8-complex-02", "course": "csa", "topic": "3.8", "tier": "complex", "lo": "3.8.A.2", "prompt": "public class Boxes\n{\n    private int rows;\n    private int width;\n    public Boxes(int r, int w)\n    {\n        rows = r;\n        width = w;\n    }\n    public void draw(int rows)\n    {\n        for (int i = 1; i <= rows; i++)\n        {\n            row(i, width + 1);\n        }\n    }\n    public void row(int n, int width)\n    {\n        for (int j = 0; j < n; j++)\n        {\n            for (int k = 0; k < width; k++)\n            {\n                System.out.print(\"#\");\n            }\n        }\n        System.out.println();\n    }\n}\nBoxes b = new Boxes(2, 1);\nb.draw(3);\nWhat is printed as a result of executing this code segment?", "choices": ["#\n##\n###", "#\n##\n###\n####", "##\n####\n######", "##\n####\n######\n########"], "answer": 2, "explanation": "The parameter rows in draw shadows the instance variable rows, so the loop runs for i from 1 to 3. Each call passes i for n and width + 1 for width's argument; inside row, the parameter width shadows the instance variable width for that call, using the value 2 (the instance variable width, 1, plus 1) throughout row's body regardless of i (3.8.A.2). Each call to row prints n * width symbols on one line: i=1 prints 1*2=2 symbols, i=2 prints 2*2=4 symbols, and i=3 prints 3*2=6 symbols, producing three lines of 2, 4, and 6 symbols. A total of four lines, or lines using 1, 2, 3 symbols, would both be based on an incorrect computation of the shadowed parameter values."},
  {"id": "3.8-complex-03", "course": "csa", "topic": "3.8", "tier": "complex", "lo": "3.8.A.2", "prompt": "A student writes the following class to model a piggy bank. The addCoins method is intended to increase the stored amount by a given number of coins, but it does not work as intended.\npublic class PiggyBank\n{\n    private int ownerAge;\n    private double amount;\n    public PiggyBank(int age, double startAmount)\n    {\n        ownerAge = age;\n        amount = startAmount;\n    }\n    public void addCoins(double coinValue)\n    {\n        double amount = coinValue;\n    }\n}\nWhich of the following best explains why the addCoins method does not work as intended?", "choices": ["coinValue must be declared as an int rather than a double", "addCoins must include a return statement to update amount", "ownerAge must be passed as a parameter to addCoins for the method to compile", "The variable amount inside addCoins is declared as a new local variable, which shadows and is separate from the instance variable amount, so the instance variable is never updated"], "answer": 3, "explanation": "The statement double amount = amount + coinValue; declares a brand-new local variable named amount, which shadows the instance variable amount for the rest of the method; this local variable is computed and then immediately discarded when the method ends, so the instance variable amount is never actually changed (3.8.A.2). coinValue's data type has no bearing on this bug, a void method with no return statement can still update an instance variable correctly if it assigns to the existing field instead of declaring a new one, and ownerAge is unrelated to addCoins and does not need to be passed to it."},
  {"id": "3.8-complex-04", "course": "csa", "topic": "3.8", "tier": "complex", "lo": "3.8.A.1", "prompt": "public class Triangle\n{\n    private double base;\n    private double height;\n    public Triangle(double b, double h)\n    {\n        base = b;\n        height = h;\n    }\n    public double calculateArea()\n    {\n        private double half = 0.5;\n        public double area = half * base * height;\n        return area;\n    }\n}\nWhich of the following best explains why the calculateArea method causes a compilation error?", "choices": ["base and height must be declared public instead of private for calculateArea to use them", "calculateArea must be declared static in order to compute a value using two instance variables", "Local variables declared inside a method, such as half and area, cannot be given an access modifier like private or public", "The multiplication half * base * height is not a legal expression in Java"], "answer": 2, "explanation": "half and area are both local variables declared inside the method body, and local variables can never be given an access modifier such as private or public; this restriction applies regardless of how many access modifiers are used or which one is chosen (3.8.A.1). Instance variables do not need to be public to be used inside a method of their own class, nothing about this method requires a static keyword, and multiplying three double values together is a perfectly legal expression."},
  {"id": "3.8-complex-05", "course": "csa", "topic": "3.8", "tier": "complex", "lo": "3.8.A.2", "prompt": "A student writes the following class to compute a student's final grade as a weighted total, but calling getFinalGrade() always prints 0.0 instead of the expected value.\npublic class GradeCalculator\n{\n    private double quizScore;\n    private double testScore;\n    private double finalGrade;\n    public GradeCalculator(double quiz, double test)\n    {\n        quizScore = quiz;\n        testScore = test;\n    }\n    private void computeFinalGrade()\n    {\n        double finalGrade = quizScore * 0.4 + testScore * 0.6;\n    }\n    public double getFinalGrade()\n    {\n        computeFinalGrade();\n        return finalGrade;\n    }\n}\nWhich of the following best explains why getFinalGrade() always returns 0.0?", "choices": ["computeFinalGrade must be declared public instead of private for the calculation to take effect", "quizScore and testScore were never assigned values in the constructor", "getFinalGrade must call computeFinalGrade before, not after, its return statement", "computeFinalGrade declares finalGrade as a new local variable that shadows the instance variable, so the calculated value is discarded and the instance variable finalGrade keeps its default value, 0.0"], "answer": 3, "explanation": "Inside computeFinalGrade, double finalGrade = ... declares a brand-new local variable that shadows the instance variable finalGrade; the computed weighted total is stored only in that local variable and disappears once the method ends, leaving the instance variable finalGrade at its default value, 0.0 (3.8.A.2). Whether computeFinalGrade is private or public has no bearing on this bug, since getFinalGrade can call it either way; quizScore and testScore are correctly assigned in the constructor; and computeFinalGrade is already called before the return statement in getFinalGrade."},
  {"id": "3.8-complex-06", "course": "csa", "topic": "3.8", "tier": "complex", "lo": "3.8.A.2", "prompt": "A class HeatController has one instance variable, private double setPoint. Five candidate methods are proposed, each intended to increase setPoint by a given amount.\nI.\npublic void raise(double setPoint)\n{\n    setPoint = setPoint + 2.0;\n}\nII.\npublic void raise(double amount)\n{\n    setPoint = setPoint + amount;\n}\nIII.\npublic void raise(double setPoint)\n{\n    double amount = setPoint + 2.0;\n}\nIV.\npublic void raise()\n{\n    setPoint = setPoint + 2.0;\n}\nV.\npublic void raise(double amount)\n{\n    double setPoint = amount;\n}\nWhich of these candidate methods correctly update the instance variable setPoint when called?", "choices": ["I and IV only", "II and IV only", "II, III, and IV only", "I, III, and V only"], "answer": 1, "explanation": "Candidates II and IV never name a parameter or local variable setPoint, so the name setPoint always refers to the instance variable, and both correctly reassign it (3.8.A.2). Candidate I names its parameter setPoint, shadowing the instance variable for the whole method, so its reassignment only affects the local copy; candidate III does the same and additionally stores the result in an unrelated local variable amount instead of reassigning anything to setPoint; and candidate V declares a brand-new local variable named setPoint that shadows the instance variable for the rest of the method, so its assignment never reaches the instance variable either."},
  {"id": "3.8-complex-07", "course": "csa", "topic": "3.8", "tier": "complex", "lo": "3.8.A.1", "prompt": "public class SignalTower\n{\n    private int signalStrength;\n    public void adjustSignal(int reading)\n    {\n        int adjustment = 0;\n        if (reading > 50)\n        {\n            int boost = 5;\n            adjustment = boost;\n        }\n        else\n        {\n            for (int penalty = 1; penalty <= 2; penalty++)\n            {\n                adjustment -= penalty;\n            }\n        }\n        signalStrength += adjustment + boost;\n    }\n}\nWhich best explains why this method fails to compile?", "choices": ["reading is never used inside the else branch, which is not allowed", "boost is a local variable scoped to the if block and is out of scope in the final statement, which lies outside both the if and else blocks", "penalty must be declared outside the for loop for adjustment to be updated", "signalStrength cannot be modified using the += operator inside a method"], "answer": 1, "explanation": "boost is declared inside the if block, so its scope is limited to that block; the final statement, signalStrength += adjustment + boost, lies outside both the if and else blocks, so boost is out of scope there and the method does not compile (3.8.A.1). adjustment is correctly declared before both branches and is used validly in each; reading does not need to be referenced inside every branch of the method; penalty is properly scoped to the for loop it controls, and += is a perfectly legal way to update an instance variable."},
  {"id": "3.8-complex-08", "course": "csa", "topic": "3.8", "tier": "complex", "lo": "3.8.A.2", "prompt": "public class VaultRoom\n{\n    private int code;\n    private int attempts;\n    public VaultRoom(int startCode)\n    {\n        code = startCode;\n        attempts = 0;\n    }\n    public boolean tryCode(int code)\n    {\n        attempts++;\n        return checkMatch(code);\n    }\n    private boolean checkMatch(int code)\n    {\n        return code == code;\n    }\n}\nVaultRoom v = new VaultRoom(1234);\nSystem.out.println(v.tryCode(9999));\nSystem.out.println(v.tryCode(1234));\nWhat is printed as a result of executing this code segment?", "choices": ["false\ntrue", "true\ntrue", "false\nfalse", "true\nfalse"], "answer": 1, "explanation": "In checkMatch, the parameter code shadows the instance variable code entirely, so the expression code == code always compares the local parameter to itself, which is always true, regardless of what value is passed in or what the instance variable code actually holds (3.8.A.2). Because of this shadowing bug, both calls to tryCode return true, not a comparison against the stored instance variable code. A result depending on whether the argument actually matches 1234 would only occur if checkMatch instead compared its parameter to the instance variable using two different names."},
  {"id": "3.8-complex-09", "course": "csa", "topic": "3.8", "tier": "complex", "lo": "3.8.A.1", "prompt": "A student is considering five candidate lines to place inside a method body.\nI. int score = 0;\nII. private int score = 0;\nIII. int score;\nIV. public int score = 0;\nV. String label;\nWhich of these lines, if placed inside a method body, would compile successfully? (Assume each line is considered independently and that score and label are not already declared elsewhere in the method.)", "choices": ["I, III, and V only", "I and V only", "I, II, and V only", "All five lines compile successfully"], "answer": 0, "explanation": "Lines I, III, and V declare ordinary local variables with no access modifier attached, so all three compile (3.8.A.1). Line II attempts to declare a local variable with the access modifier private, and line IV attempts to declare one with the access modifier public; both are illegal because local variables can never carry an access modifier, so neither II nor IV compiles."},
  {"id": "3.8-complex-10", "course": "csa", "topic": "3.8", "tier": "complex", "lo": "3.8.A.2", "prompt": "public class MessageBox\n{\n    private String message;\n    private int position;\n    public MessageBox(String startMessage, int startPosition)\n    {\n        message = startMessage;\n        position = startPosition;\n    }\n    public String process(String message)\n    {\n        int position = message.indexOf(\"a\");\n        String result = message.substring(position);\n        return result + position;\n    }\n}\nMessageBox box = new MessageBox(\"banana\", 10);\nSystem.out.println(box.process(\"lava\"));\nWhat is printed as a result of executing this code segment?", "choices": ["ava1", "lava1", "ava10", "banana1"], "answer": 0, "explanation": "The parameter message shadows the instance variable message for the whole method, so message.indexOf(\"a\") searches \"lava\", where the first \"a\" is at index 1; the local variable position, which also shadows the instance variable position, is set to 1 (3.8.A.2). message.substring(1) on \"lava\" produces \"ava\", so result becomes \"ava\", and the method returns result + position, which concatenates \"ava\" with the local position, 1, giving \"ava1\". Using \"banana\" or the instance variable position, 10, would incorrectly assume the instance variables were used instead of the shadowing parameter and local variable."},
  {"id": "3.8-complex-11", "course": "csa", "topic": "3.8", "tier": "complex", "lo": "3.8.A.1", "prompt": "public class DeliveryRoute\n{\n    private String driverName;\n    private int stopsRemaining;\n    public DeliveryRoute(String name, int stops)\n    {\n        driverName = name;\n        stopsRemaining = stops;\n    }\n    public void completeStop()\n    {\n        int remaining = stopsRemaining - 1;\n        stopsRemaining = remaining;\n    }\n    public String describe(int bonusStops)\n    {\n        int totalStops = stopsRemaining + bonusStops;\n        return driverName + \" has \" + totalStops + \" stops left\";\n    }\n}\nWhich of the following correctly lists every local variable that appears anywhere in this class?", "choices": ["driverName, stopsRemaining, name, stops, remaining, bonusStops, totalStops", "name, stops, remaining, bonusStops, totalStops", "name, stops, remaining, totalStops", "driverName, stopsRemaining, name, stops"], "answer": 1, "explanation": "Local variables include every constructor and method parameter along with every variable declared inside a method or constructor body: name and stops (constructor parameters), remaining (declared inside completeStop), bonusStops (a parameter of describe), and totalStops (declared inside describe) (3.8.A.1). driverName and stopsRemaining are declared in the class body outside any method or constructor, making them instance variables, so any answer that includes them as local variables is incorrect, and omitting bonusStops leaves out one of describe's parameters."},
  {"id": "3.8-complex-12", "course": "csa", "topic": "3.8", "tier": "complex", "lo": "3.8.A.2", "prompt": "A ScoreTracker class has one instance variable, private int highScore. Five candidate methods are proposed, each intended to update highScore to a new value if newScore is greater.\nI.\npublic void update(int newScore)\n{\n    if (newScore > highScore)\n    {\n        highScore = newScore;\n    }\n}\nII.\npublic void update(int highScore)\n{\n    if (highScore > highScore)\n    {\n        highScore = highScore;\n    }\n}\nIII.\npublic void update(int newScore)\n{\n    int highScore = 0;\n    if (newScore > highScore)\n    {\n        highScore = newScore;\n    }\n}\nIV.\npublic void update(int candidate)\n{\n    int highScore = candidate;\n}\nV.\npublic void update(int newScore)\n{\n    if (newScore > highScore)\n    {\n        int highScore = newScore;\n    }\n}\nWhich of these candidate methods correctly updates the instance variable highScore when the argument is greater than the current high score?", "choices": ["I only", "I and II only", "I, III, and V only", "II, III, IV, and V only"], "answer": 0, "explanation": "Only candidate I avoids naming any parameter or local variable highScore, so every reference to highScore inside it refers to the instance variable, correctly comparing against and reassigning it (3.8.A.2). Candidate II's parameter is itself named highScore, shadowing the instance variable so completely that highScore > highScore always compares the parameter to itself and is always false; candidates III and IV each declare a new local variable named highScore directly inside the method body, shadowing the instance variable for the rest of the method, so any assignment to that local highScore is discarded; and candidate V declares its local highScore inside the nested if block, shadowing the instance variable only within that block, so the reassignment there is discarded as well, leaving the instance variable highScore unchanged in every case except candidate I."},
  {"id": "3.8-complex-13", "course": "csa", "topic": "3.8", "tier": "complex", "lo": "3.8.A.1", "prompt": "A student writes the following class and expects it to compile, but it does not.\npublic class ParkingMeter\n{\n    private int minutesLeft;\n    public ParkingMeter(int startMinutes)\n    {\n        minutesLeft = startMinutes;\n    }\n    public void addTime(int minutes)\n    {\n        private int bonus = 5;\n        minutesLeft = minutesLeft + minutes + bonus;\n    }\n    public void printStatus()\n    {\n        for (int check = 0; check < 1; check++)\n        {\n            System.out.println(minutesLeft);\n        }\n        System.out.println(check);\n    }\n}\nWhich of the following identifies ALL the compile errors present in this class?", "choices": ["Only the declaration of bonus in addTime is an error, since a local variable cannot be given an access modifier", "Only the reference to check in printStatus is an error, since check is a local variable scoped to the for loop and is out of scope on the final line", "Both the declaration of bonus in addTime, since a local variable cannot be given an access modifier, and the reference to check in printStatus, since check is out of scope outside the for loop, are errors", "There are no compile errors in this class"], "answer": 2, "explanation": "private int bonus = 5; illegally attaches an access modifier to a local variable, which is never allowed (3.8.A.1), and separately, check is declared in the for loop header inside printStatus, scoping it to the loop, so referencing check in the final println outside the loop is also an error (3.8.A.1). Because both problems exist independently in different methods, an answer identifying only one of them is incomplete, and the class clearly does not compile as written."},
  {"id": "3.8-complex-14", "course": "csa", "topic": "3.8", "tier": "complex", "lo": "3.8.A.2", "prompt": "public class OvenTimer\n{\n    private int minutes;\n    private int temp;\n    public OvenTimer()\n    {\n        minutes = 30;\n        temp = 350;\n    }\n    public int runCycle(int temp)\n    {\n        int total = 0;\n        for (int minutes = 1; minutes <= 3; minutes++)\n        {\n            total += temp / 100;\n        }\n        total += minutes;\n        return total;\n    }\n}\nOvenTimer o = new OvenTimer();\nSystem.out.println(o.runCycle(200));\nWhat is printed as a result of executing this code segment?", "choices": ["36", "6", "56", "30"], "answer": 0, "explanation": "The parameter temp shadows the instance variable temp for the entire method, so the loop, which runs 3 times because its local minutes (which shadows the instance variable minutes only inside the loop) goes from 1 to 3, adds temp / 100 using the argument 200, giving 2 each time, for a total of 6 (3.8.A.2). Once the loop ends, its local minutes goes out of scope, so total += minutes uses the instance variable minutes, 30, giving a final total of 6 + 30 = 36. Printing 6 stops before adding the instance variable's contribution, printing 30 ignores the loop's accumulated total entirely, and 56 would require using the instance variable temp, 350, divided by 100 instead of the parameter's value."},
  {"id": "3.8-complex-15", "course": "csa", "topic": "3.8", "tier": "complex", "lo": "3.8.A.1", "prompt": "public class VendingMachine\n{\n    private int stock;\n    private double price;\n    public VendingMachine(int startStock)\n    {\n        stock = startStock;\n        price = 1.00;\n    }\n    public VendingMachine(int startStock, double startPrice)\n    {\n        stock = startStock;\n        price = startPrice;\n    }\n    public void sell(int quantity)\n    {\n        if (quantity <= stock)\n        {\n            double total = quantity * price;\n            stock = stock - quantity;\n            System.out.println(total);\n        }\n        else\n        {\n            System.out.println(\"unavailable\");\n        }\n    }\n}\nWhich of the following statements about this class is true?", "choices": ["startStock and startPrice are instance variables because they are used to set stock and price", "The class fails to compile because two constructors cannot both use a parameter named startStock", "total is an instance variable because it is used to compute a value that is printed to the console", "startStock, startPrice, quantity, and total are all local variables, each scoped only to the constructor or method in which it is declared"], "answer": 3, "explanation": "startStock and startPrice are parameters of their respective constructors, quantity is a parameter of sell, and total is declared inside sell's if block; all four are local variables, each existing only within its own declaring constructor, method, or block (3.8.A.1). Being used to set an instance variable does not make a parameter itself an instance variable, being printed does not make a local variable an instance variable, and overloaded constructors are completely free to reuse the same parameter name, since each constructor has its own independent scope."},
  {"id": "3.9-basic-01", "course": "csa", "topic": "3.9", "tier": "basic", "lo": "3.9.A.1", "prompt": "A programmer writes the following constructor.\npublic class Wallet\n{\n    private double balance;\n    public Wallet(double balance)\n    {\n        balance = balance;\n    }\n}\nWallet w = new Wallet(50.0);\nAfter this call, what is the value of w's balance instance variable?", "choices": ["0.0, because balance = balance; assigns the parameter to itself and never touches the instance variable", "50.0, because balance = balance; correctly stores the parameter's value", "50.0, because Java automatically matches parameter names to instance variables", "A compile-time error occurs because balance is used twice"], "answer": 0, "explanation": "Because the parameter balance shadows the instance variable balance inside the constructor, the statement balance = balance; refers only to the parameter on both sides, so it is a self-assignment that never affects the instance variable, which is left at its default value 0.0 (3.9.A.1). The instance variable is not automatically matched by name, and the code compiles without error since both sides legally refer to the parameter."},
  {"id": "3.9-basic-02", "course": "csa", "topic": "3.9", "tier": "basic", "lo": "3.9.A.1", "prompt": "Which change to the Wallet constructor below correctly fixes the shadowing problem so that the instance variable balance is set to the value of the parameter?\npublic class Wallet\n{\n    private double balance;\n    public Wallet(double balance)\n    {\n        balance = balance;\n    }\n}", "choices": ["Rename the parameter to Balance, since Java is case-sensitive", "Replace balance = balance; with this.balance = balance;", "Replace balance = balance; with balance = this.balance;", "Delete the parameter from the constructor header"], "answer": 1, "explanation": "Writing this.balance = balance; explicitly directs the assignment to the current object's instance variable, using this to distinguish it from the parameter of the same name (3.9.A.1). Renaming to Balance would technically avoid shadowing but is not the standard fix; balance = this.balance; assigns the old, default instance value into the parameter and leaves the instance variable unchanged; deleting the parameter removes the ability to set balance's value at all."},
  {"id": "3.9-basic-03", "course": "csa", "topic": "3.9", "tier": "basic", "lo": "3.9.A.1", "prompt": "Within an instance method of a class, what does the keyword this refer to?", "choices": ["A brand-new object created to run the method", "The class itself, rather than any object", "The current object, meaning the specific object whose method is being called", "The first parameter passed to the method"], "answer": 2, "explanation": "The keyword this is a reference to the current object, the specific instance whose method or constructor is executing (3.9.A.1). It does not create a new object, does not refer to the class as a whole, and does not refer to a parameter; it refers to the object itself."},
  {"id": "3.9-basic-04", "course": "csa", "topic": "3.9", "tier": "basic", "lo": "3.9.A.1", "prompt": "Consider the constructor below.\npublic class Ticket\n{\n    private int seatNumber;\n    public Ticket(int seatNumber)\n    {\n        this.seatNumber = seatNumber;\n    }\n}\nTicket t = new Ticket(12);\nWhat is the value of t's seatNumber instance variable after this call?", "choices": ["0, because the parameter shadows the instance variable and this.seatNumber cannot be resolved", "An error occurs because this cannot be used in a constructor", "The value is undefined, because seatNumber is never assigned a value", "12, because this.seatNumber refers to the instance variable, and it is assigned the parameter's value"], "answer": 3, "explanation": "Using this.seatNumber on the left side of the assignment explicitly selects the instance variable of the current object, so it correctly receives the parameter's value 12, even though the parameter shares the same name (3.9.A.1). this is legal and commonly used inside constructors, and the assignment is well-defined rather than left at 0 or undefined."},
  {"id": "3.9-basic-05", "course": "csa", "topic": "3.9", "tier": "basic", "lo": "3.9.A.3", "prompt": "A programmer wants to add a class (static) method to the Sensor class that uses this to refer to whichever Sensor object called it. Which statement is true?", "choices": ["A static method cannot use this, because static methods belong to the class itself and are not called on any particular object", "This is legal, because every method in Java automatically has a this reference available", "This is legal, as long as the static method has at least one parameter", "This is legal, but only if the class has exactly one instance variable"], "answer": 0, "explanation": "Class (static) methods do not have a this reference, since they belong to the class as a whole and are not invoked on a specific object (3.9.A.3). this is only available inside instance methods and constructors; the number of parameters or instance variables the class has does not change this rule."},
  {"id": "3.9-basic-06", "course": "csa", "topic": "3.9", "tier": "basic", "lo": "3.9.A.2", "prompt": "A Robot class has an instance method that registers the robot with a Fleet, as shown below.\npublic void register(Fleet fleet)\n{\n    fleet.add(this);\n}\nWhat does the statement fleet.add(this); accomplish?", "choices": ["It creates a brand-new Robot object and passes it to add", "It passes a reference to the current Robot object as the argument to add", "It causes a compile-time error, since this cannot be passed as an argument", "It passes the Fleet object itself into add"], "answer": 1, "explanation": "The keyword this can be used to pass the current object as an argument in a method call, so fleet.add(this); passes a reference to the very Robot object whose register method is executing (3.9.A.2). No new object is created, this is a legal argument, and it refers to the Robot, not to the Fleet."},
  {"id": "3.9-basic-07", "course": "csa", "topic": "3.9", "tier": "basic", "lo": "3.9.A.1", "prompt": "A Badge class is written as follows.\npublic class Badge\n{\n    private String code;\n    public Badge(String code)\n    {\n        code = code;\n    }\n    public String getCode()\n    {\n        return code;\n    }\n}\nBadge b = new Badge(\"A1\");\nSystem.out.println(b.getCode());\nWhat is printed?", "choices": ["\"A1\"", "An error, since a shadowed variable can never be printed", "null", "an empty string \"\""], "answer": 2, "explanation": "Because the parameter code shadows the instance variable, code = code; is a self-assignment on the parameter only, leaving the instance variable at String's default value, null (3.9.A.1). No compile error occurs, \"A1\" is never actually stored in the instance variable, and Java does not default String fields to an empty string."},
  {"id": "3.9-basic-08", "course": "csa", "topic": "3.9", "tier": "basic", "lo": "3.9.A.1", "prompt": "Which constructor correctly assigns a Coin object's instance variable value using a parameter of the same name?", "choices": ["public Coin(int value)\n    {\n        value = this.value;\n    }", "public Coin(int value)\n    {\n        int value = value;\n    }", "public Coin(int coinValue)\n    {\n        this.value = this.coinValue;\n    }", "public Coin(int value)\n    {\n        this.value = value;\n    }"], "answer": 3, "explanation": "this.value = value; assigns the parameter's value into the instance variable, using this to disambiguate it from the parameter of the same name (3.9.A.1). The first option assigns backwards, storing the default instance value into the parameter; the second re-declares a duplicate local variable named value and does not compile; the third incorrectly treats coinValue as if it were also an instance variable, which it is not, since only value is declared as a field."},
  {"id": "3.9-intermediate-01", "course": "csa", "topic": "3.9", "tier": "intermediate", "lo": "3.9.A.1", "prompt": "Consider the Vault class below.\npublic class Vault\n{\n    private int amount;\n    public Vault(int amount)\n    {\n        this.amount = amount;\n    }\n    public int getAmount()\n    {\n        return amount;\n    }\n    public boolean hasMoreThan(Vault other)\n    {\n        return this.amount > other.getAmount();\n    }\n}\nVault v1 = new Vault(200);\nVault v2 = new Vault(150);\nSystem.out.println(v1.hasMoreThan(v2));\nWhat is printed?", "choices": ["true", "false", "A compile-time error occurs because this.amount cannot be compared to other.getAmount()", "150"], "answer": 0, "explanation": "Inside hasMoreThan, this refers to the calling object v1, so this.amount is 200, while other refers to the parameter v2, so other.getAmount() is 150. Since 200 > 150, the method returns true (3.9.A.1). The comparison is legal Java, so no compile error occurs, and 150 is other's amount, not the printed boolean result."},
  {"id": "3.9-intermediate-02", "course": "csa", "topic": "3.9", "tier": "intermediate", "lo": "3.9.A.1", "prompt": "Using the Vault class from before, where hasMoreThan returns this.amount > other.getAmount(), suppose v1 has amount 200 and v2 has amount 150. What is printed by the statement below?\nSystem.out.println(v2.hasMoreThan(v1));", "choices": ["true", "false", "200", "An error occurs because v2 cannot call a method defined for v1"], "answer": 1, "explanation": "When v2.hasMoreThan(v1) is called, this refers to v2 (amount 150) and other refers to the parameter v1 (amount 200). Since 150 > 200 is false, the method returns false (3.9.A.1). true would only result if v2's amount exceeded v1's; 200 is other's amount, not the boolean result; and calling this instance method on any Vault object, including v2, is entirely legal."},
  {"id": "3.9-intermediate-03", "course": "csa", "topic": "3.9", "tier": "intermediate", "lo": "3.9.A.1", "prompt": "A Locker class needs a constructor that sets an instance variable code from a parameter of the same name. Consider these three possible constructor bodies.\nI. this.code = code;\nII. code = this.code;\nIII. code = code;\nWhich correctly assigns the instance variable code the value of the parameter?", "choices": ["II only", "III only", "I only", "I and II"], "answer": 2, "explanation": "Only statement I, this.code = code;, correctly assigns the parameter's value into the instance variable by using this to distinguish it from the identically named parameter (3.9.A.1). Statement II assigns backwards, storing the old instance value into the parameter, and statement III is a self-assignment on the parameter alone that never touches the instance variable, so neither II nor III achieves the intended result."},
  {"id": "3.9-intermediate-04", "course": "csa", "topic": "3.9", "tier": "intermediate", "lo": "3.9.A.2", "prompt": "A Contestant class contains this instance method.\npublic void enter(Tournament t)\n{\n    t.addContestant(this);\n}\nWhat is the effect of calling myContestant.enter(myTournament);?", "choices": ["myTournament is passed into addContestant as the argument", "A brand-new Contestant is created and added to myTournament", "The method does not compile because this cannot appear inside a method argument list", "myContestant itself is passed into myTournament's addContestant method as the argument"], "answer": 3, "explanation": "Inside enter, this refers to the current Contestant object, myContestant, so t.addContestant(this); passes myContestant itself into addContestant (3.9.A.2). myTournament is the object t on which addContestant is called, not the argument; no new Contestant is created; and passing this as an argument is legal Java."},
  {"id": "3.9-intermediate-05", "course": "csa", "topic": "3.9", "tier": "intermediate", "lo": "3.9.A.1", "prompt": "Consider the overloaded Device class below.\npublic class Device\n{\n    private String label;\n    public Device()\n    {\n        this.label = \"unlabeled\";\n    }\n    public Device(String label)\n    {\n        this.label = label;\n    }\n    public String getLabel()\n    {\n        return label;\n    }\n}\nDevice d1 = new Device();\nDevice d2 = new Device(\"Router\");\nSystem.out.println(d1.getLabel() + \" \" + d2.getLabel());\nWhat is printed?", "choices": ["unlabeled Router", "Router unlabeled", "null Router", "unlabeled null"], "answer": 0, "explanation": "The no-argument constructor uses this.label = \"unlabeled\"; to set the instance variable directly, since there is no parameter to shadow it, giving d1 the label \"unlabeled\". The second constructor's parameter label shadows the instance variable, so this.label = label; is required to assign the parameter's value, giving d2 the label \"Router\" (3.9.A.1). Reversing the order, or defaulting either label to null, does not match this trace."},
  {"id": "3.9-intermediate-06", "course": "csa", "topic": "3.9", "tier": "intermediate", "lo": "3.9.A.1", "prompt": "Consider the Gadget class below.\npublic class Gadget\n{\n    private double price;\n    public Gadget(double price)\n    {\n        this.price = price;\n    }\n    public double getPrice()\n    {\n        return price;\n    }\n    public boolean samePriceAs(Gadget other)\n    {\n        return this.price == other.getPrice();\n    }\n}\nGadget g1 = new Gadget(19.99);\nGadget g2 = new Gadget(19.99);\nSystem.out.println(g1.samePriceAs(g2));\nWhat is printed, and why?", "choices": ["false, because g1 and g2 are different objects, so this can never equal other", "true, because this.price and other.getPrice() both evaluate to 19.99, even though g1 and g2 are different objects", "true, because this and other refer to the same object", "A compile-time error occurs because this.price cannot be compared with =="], "answer": 1, "explanation": "samePriceAs compares field values, not object identity: this.price is g1's price (19.99) and other.getPrice() is g2's price (19.99), and since these primitive double values are equal, the method returns true (3.9.A.1). g1 and g2 are indeed different objects, but that does not matter here because the comparison is on the price field, not on this == other; comparing a double with == compiles without error."},
  {"id": "3.9-intermediate-07", "course": "csa", "topic": "3.9", "tier": "intermediate", "lo": "3.9.A.1", "prompt": "A Sensor class defines the method below.\npublic boolean check(Sensor other)\n{\n    return this == other;\n}\nSensor s1 = new Sensor();\nSensor s2 = new Sensor();\nSensor s3 = s1;\nConsider the following calls.\nI. s1.check(s2)\nII. s1.check(s3)\nIII. s1.check(s1)\nWhich of these calls return true?", "choices": ["I only", "I and II only", "II and III only", "I, II, and III"], "answer": 2, "explanation": "this == other tests whether this and the parameter refer to the exact same object in memory, not whether their fields match (3.9.A.1). Since s3 was assigned s1, s3 and s1 refer to the identical object, making s1.check(s3) true, and s1.check(s1) compares an object to itself, also true. s2 is a separate object created independently, so s1.check(s2) is false. Therefore II and III return true, but not I."},
  {"id": "3.9-intermediate-08", "course": "csa", "topic": "3.9", "tier": "intermediate", "lo": "3.9.A.2", "prompt": "A Speaker class links itself to a Playlist when constructed, as shown.\npublic class Speaker\n{\n    private Playlist list;\n    public Speaker(Playlist list)\n    {\n        this.list = list;\n        list.attachSpeaker(this);\n    }\n}\nWhat is the purpose of the this argument in list.attachSpeaker(this);?", "choices": ["It passes the Playlist object into attachSpeaker", "It creates a new Speaker for the Playlist to store", "It causes a null reference error, since this is not fully constructed yet", "It passes a reference to the Speaker object currently being constructed, so the Playlist can store a link back to it"], "answer": 3, "explanation": "Inside the constructor, this refers to the Speaker object currently being built, so passing this to attachSpeaker gives the Playlist a reference back to this very Speaker (3.9.A.2). The Playlist parameter is list, not the argument to attachSpeaker; no new Speaker is created; and using this inside a constructor to pass a reference to another object is legal, not a null reference error."},
  {"id": "3.9-complex-01", "course": "csa", "topic": "3.9", "tier": "complex", "lo": "3.9.A.1", "prompt": "Consider the Parcel class below.\npublic class Parcel\n{\n    private int weight;\n    public Parcel(int weight)\n    {\n        this.weight = weight;\n    }\n    public int getWeight()\n    {\n        return weight;\n    }\n    public String compare(Parcel other)\n    {\n        if (this == other)\n        {\n            return \"same\";\n        }\n        else if (this.weight == other.getWeight())\n        {\n            return \"tie\";\n        }\n        else\n        {\n            return \"different\";\n        }\n    }\n}\nParcel p1 = new Parcel(10);\nParcel p2 = new Parcel(10);\nParcel p3 = p1;\nSystem.out.println(p1.compare(p2));\nSystem.out.println(p1.compare(p3));\nSystem.out.println(p2.compare(p1));\nWhat is printed by these three lines, in order?", "choices": ["tie\nsame\ntie", "same\ntie\nsame", "tie\ntie\ntie", "different\nsame\ndifferent"], "answer": 0, "explanation": "p1 and p2 are separate objects with equal weight, so this == other is false in p1.compare(p2), but this.weight == other.getWeight() (10 == 10) is true, printing \"tie\" (3.9.A.1). p3 was assigned p1, so p1 and p3 refer to the identical object; this == other is true in p1.compare(p3), printing \"same\". p2.compare(p1) again compares two distinct objects with equal weight, printing \"tie\". No line involves genuinely different weights, so \"different\" never appears."},
  {"id": "3.9-complex-02", "course": "csa", "topic": "3.9", "tier": "complex", "lo": "3.9.A.1", "prompt": "Consider the Token class below.\npublic class Token\n{\n    private int id;\n    public Token(int id)\n    {\n        this.id = id;\n    }\n    public boolean sameObject(Token other)\n    {\n        return this == other;\n    }\n}\nToken t1 = new Token(5);\nToken t2 = new Token(5);\nToken t3 = t1;\nToken t4 = t2;\nConsider the following calls.\nI. t1.sameObject(t3)\nII. t1.sameObject(t2)\nIII. t3.sameObject(t1)\nIV. t2.sameObject(t4)\nV. t1.sameObject(t4)\nHow many of these five calls return true?", "choices": ["2", "3", "4", "1"], "answer": 1, "explanation": "Since t3 was assigned t1, they refer to the same object, making calls I and III true; since t4 was assigned t2, they also refer to the same object, making call IV true. t1 and t2 are two independently created objects, so II is false, and t1 compared with t4 (which is really t2) is also comparing two distinct objects, so V is false. In total, three of the five calls return true (3.9.A.1)."},
  {"id": "3.9-complex-03", "course": "csa", "topic": "3.9", "tier": "complex", "lo": "3.9.A.2", "prompt": "Consider the two classes below.\npublic class Board\n{\n    private Note pinned;\n    public void pin(Note n)\n    {\n        pinned = n;\n    }\n    public String getPinnedText()\n    {\n        return pinned.getText();\n    }\n}\npublic class Note\n{\n    private String text;\n    public Note(String text)\n    {\n        this.text = text;\n    }\n    public String getText()\n    {\n        return text;\n    }\n    public void setText(String text)\n    {\n        this.text = text;\n    }\n    public void attachTo(Board b)\n    {\n        b.pin(this);\n    }\n}\nBoard board = new Board();\nNote note = new Note(\"Meeting at 9\");\nnote.attachTo(board);\nnote.setText(\"Meeting at 10\");\nSystem.out.println(board.getPinnedText());\nWhat is printed?", "choices": ["Meeting at 9", "null", "Meeting at 10", "A compile-time error occurs because this cannot be passed to pin"], "answer": 2, "explanation": "attachTo passes this, meaning the actual note object itself, into b.pin(this);, so board's pinned field becomes an alias for note rather than a separate copy (3.9.A.2). Because pinned refers to the very same object as note, the later call note.setText(\"Meeting at 10\"); changes the object that both note and pinned point to, so board.getPinnedText() reflects the updated text, \"Meeting at 10\". Passing this as an argument is legal Java, and pinned is never left null since pin assigns it before setText runs."},
  {"id": "3.9-complex-04", "course": "csa", "topic": "3.9", "tier": "complex", "lo": "3.9.A.1", "prompt": "Consider the Account class below.\npublic class Account\n{\n    private double balance;\n    public Account(double balance)\n    {\n        this.balance = balance;\n    }\n    public double getBalance()\n    {\n        return balance;\n    }\n    public boolean richerThan(Account other)\n    {\n        return this.balance > other.getBalance();\n    }\n    public boolean isSameAccount(Account other)\n    {\n        return this == other;\n    }\n}\nAccount a1 = new Account(500.0);\nAccount a2 = new Account(500.0);\nAccount a3 = a1;\nConsider the following statements.\nI. a1.richerThan(a2) is false\nII. a1.isSameAccount(a3) is true\nIII. a2.richerThan(a1) is true\nIV. a3.isSameAccount(a2) is false\nWhich statements are true?", "choices": ["I and III only", "II and III only", "I, II, and III only", "I, II, and IV only"], "answer": 3, "explanation": "Since a1 and a2 have equal balances, richerThan returns false both ways (500.0 > 500.0 is false), so statement I is true and statement III, which claims a2.richerThan(a1) is true, is false. Since a3 was assigned a1, a1 and a3 refer to the identical object, so a1.isSameAccount(a3) is true (statement II), while a3 and a2 are different objects, so a3.isSameAccount(a2) is false, making statement IV true (3.9.A.1). Only I, II, and IV hold."},
  {"id": "3.9-complex-05", "course": "csa", "topic": "3.9", "tier": "complex", "lo": "3.9.A.2", "prompt": "Consider the two classes below.\npublic class Athlete\n{\n    private String name;\n    public Athlete(String name)\n    {\n        this.name = name;\n    }\n    public void join(Team t)\n    {\n        t.setCaptain(this);\n    }\n    public boolean isCaptainOf(Team t)\n    {\n        return t.getCaptain() == this;\n    }\n}\npublic class Team\n{\n    private Athlete captain;\n    public void setCaptain(Athlete a)\n    {\n        captain = a;\n    }\n    public Athlete getCaptain()\n    {\n        return captain;\n    }\n}\nTeam teamA = new Team();\nAthlete alex = new Athlete(\"Alex\");\nAthlete jordan = new Athlete(\"Jordan\");\nalex.join(teamA);\njordan.join(teamA);\nSystem.out.println(alex.isCaptainOf(teamA));\nSystem.out.println(jordan.isCaptainOf(teamA));\nWhat is printed by these two lines?", "choices": ["false\ntrue", "true\nfalse", "true\ntrue", "false\nfalse"], "answer": 0, "explanation": "When alex.join(teamA) runs, it passes this, referring to alex, into teamA.setCaptain, so teamA's captain becomes alex. When jordan.join(teamA) then runs, it passes this, referring to jordan, into the same method, overwriting captain to jordan (3.9.A.2). By the time isCaptainOf is checked, teamA.getCaptain() is jordan, not alex, so alex.isCaptainOf(teamA) compares jordan == alex and prints false, while jordan.isCaptainOf(teamA) compares jordan == jordan and prints true."},
  {"id": "3.9-complex-06", "course": "csa", "topic": "3.9", "tier": "complex", "lo": "3.9.A.1", "prompt": "Consider the Cart class below.\npublic class Cart\n{\n    private int items;\n    public Cart(int items)\n    {\n        this.items = items;\n    }\n    public Cart(Cart source)\n    {\n        items = source.items;\n    }\n    public int getItems()\n    {\n        return items;\n    }\n    public boolean hasMoreItemsThan(Cart other)\n    {\n        return this.items > other.getItems();\n    }\n}\nCart c1 = new Cart(5);\nCart c2 = new Cart(c1);\nCart c3 = new Cart(8);\nSystem.out.println(c1.hasMoreItemsThan(c2));\nSystem.out.println(c3.hasMoreItemsThan(c1));\nSystem.out.println(c2.hasMoreItemsThan(c3));\nWhat is printed by these three lines, in order?", "choices": ["true\nfalse\ntrue", "false\ntrue\nfalse", "false\nfalse\nfalse", "true\ntrue\nfalse"], "answer": 1, "explanation": "The copy constructor Cart(Cart source) reads source.items directly, which is legal since the access happens within the same class, giving c2 the same item count as c1, namely 5, while c3 is independently constructed with 8. Comparing this.items to other.getItems(): c1.hasMoreItemsThan(c2) is 5 > 5, which is false; c3.hasMoreItemsThan(c1) is 8 > 5, which is true; and c2.hasMoreItemsThan(c3) is 5 > 8, which is false (3.9.A.1)."},
  {"id": "3.9-complex-07", "course": "csa", "topic": "3.9", "tier": "complex", "lo": "3.9.A.3", "prompt": "Consider the following statements about the keyword this in Java.\nI. Inside an instance method, this refers to the object on which the method was called.\nII. Inside a constructor, this can be used to distinguish an instance variable from a parameter of the same name.\nIII. Inside a class (static) method, this refers to the class itself, since static methods operate independently of any object.\nWhich of these statements are true?", "choices": ["I, II, and III", "II and III only", "I and II only", "I only"], "answer": 2, "explanation": "Statements I and II correctly describe how this behaves in instance methods and constructors (3.9.A.1). Statement III is false: a class (static) method has no this reference at all, not even one referring to the class itself, since static methods are not invoked on any particular object (3.9.A.3)."},
  {"id": "3.9-complex-08", "course": "csa", "topic": "3.9", "tier": "complex", "lo": "3.9.A.1", "prompt": "Consider the Contestant class below.\npublic class Contestant\n{\n    private int score;\n    public Contestant(int score)\n    {\n        this.score = score;\n    }\n    public int getScore()\n    {\n        return score;\n    }\n    public String challenge(Contestant other)\n    {\n        if (this == other)\n        {\n            return \"self\";\n        }\n        else if (this.score > other.getScore())\n        {\n            return \"win\";\n        }\n        else if (this.score < other.getScore())\n        {\n            return \"loss\";\n        }\n        else\n        {\n            return \"draw\";\n        }\n    }\n}\nContestant a = new Contestant(30);\nContestant b = new Contestant(30);\nContestant c = a;\nSystem.out.println(a.challenge(b));\nSystem.out.println(a.challenge(c));\nSystem.out.println(b.challenge(a));\nSystem.out.println(c.challenge(b));\nWhat is printed by these four lines, in order?", "choices": ["self\ndraw\ndraw\ndraw", "draw\ndraw\nself\ndraw", "draw\nself\nself\ndraw", "draw\nself\ndraw\ndraw"], "answer": 3, "explanation": "a and b are separate objects with equal scores, so a.challenge(b) finds this == other false and falls to the tie case, printing \"draw\". Since c was assigned a, a and c refer to the identical object, so a.challenge(c) prints \"self\". b.challenge(a) again compares two distinct objects with equal scores, printing \"draw\", and c.challenge(b) compares c, which is really a, to b, two distinct objects with equal scores, also printing \"draw\" (3.9.A.1)."},
];
